globalThis.ORDO_PROPERS_MONTHS ||= {}; globalThis.ORDO_PROPERS_MONTHS["2026-10"] = {"month":"2026-10","days":{"2026-10-01":{"date":"2026-10-01","title":"Féria da 18ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Quinta infra Hebdomadam XVIII post Octavam Pentecostes IV. Septembris\tFeria","winner":"Tempora/Pent18-4.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 36:18\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>a pacem, Dómine, sustinéntibus te, ut prophétæ tui fidéles inveniántur: exáudi preces servi tui et plebis tuæ Israël\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 121:1\u003c/I>\u003c/FONT>\u003cbr/>\nLætátus sum in his, quæ dicta sunt mihi: in domum Dómini íbimus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>a pacem, Dómine, sustinéntibus te, ut prophétæ tui fidéles inveniántur: exáudi preces servi tui et plebis tuæ Israël\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ecl 36:18\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai paz, Senhor, àqueles que em Vós esperam, a fim de que os vossos Profetas sejam julgados fiéis: Ouvi as preces de Israel, vosso servo e vosso povo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 121:1\u003c/I>\u003c/FONT>\u003cbr/>\nAlegrei-me com aqueles que me disseram estas palavras: iremos para a casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai paz, Senhor, àqueles que em Vós esperam, a fim de que os vossos Profetas sejam julgados fiéis: Ouvi as preces de Israel, vosso servo e vosso povo.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDírigat corda nostra, quǽsumus, Dómine, tuæ miseratiónis operátio: quia tibi sine te placére non póssumus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Remigii Episcopi et Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>v\u003c/I>\u003c/B>\u003c/FONT>. Da, quǽsumus, omnípotens Deus: ut beáti Remígii Confessóris tui atque Pontíficis veneránda solémnitas, et devotiónem nobis áugeat et salútem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDignai-Vos, Senhor, Vos imploramos, dirigir os nossos corações segundo as inspirações da vossa misericórdia, pois sem Vós não podemos agradar-Vos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Remígio, Bispo e Confessor\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ignai-Vos permitir, ó Deus omnipotente, que a veneranda solenidade do vosso Confessor e Pontífice Remígio aumente a nossa piedade e nos assegure a salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corinthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 1:4-8\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Grátias ago Deo meo semper pro vobis in grátia Dei, quæ data est vobis in Christo Jesu: quod in ómnibus dívites facti estis in illo, in omni verbo et in omni sciéntia: sicut testimónium Christi confirmátum est in vobis: ita ut nihil vobis desit in ulla grátia, exspectántibus revelatiónem Dómini nostri Jesu Christi, qui et confirmábit vos usque in finem sine crímine, in die advéntus Dómini nostri Jesu Christi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor. 1:4-8\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Rendo contínuas acções de graças a Deus por vós, visto que vos foi dada a graça de Deus, em Jesus Cristo. Pois pela vossa união com Cristo ficastes repletos de riquezas espirituais, particularmente pelo que respeita ao dom da palavra e da ciência. O testemunho, que vos tinha sido dado de Jesus Cristo, foi assim confirmado em vós, de modo que não cedeis a ninguém em nenhum dom da graça, esperando com confiança a manifestação de Nosso Senhor. E ainda até ao fim Deus vos confirmará, para que vos encontre irrepreensíveis no dia da vinda de Nosso Senhor Jesus Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 121:1; 121:7\u003c/I>\u003c/FONT>\u003cbr/>\nLætátus sum in his, quæ dicta sunt mihi: in domum Dómini íbimus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Fiat pax in virtúte tua: et abundántia in túrribus tuis. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 101:16\u003c/I>\u003c/FONT>\u003cbr/>\nTimébunt gentes nomen tuum, Dómine, et omnes reges terræ glóriam tuam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 121:1, 7.\u003c/I>\u003c/FONT>\u003cbr/>\nAlegro-me com aqueles que me disseram estas palavras: iremos para a casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Que a paz reine nas tuas fortalezas e a abundância nos teus palácios. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 101:16\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> As nações, Senhor, temerão o vosso nome e os reis da terra contemplarão a vossa glória. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 9:1-8\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Ascéndens Jesus in navículam, transfretávit et venit in civitátem suam. Et ecce, offerébant ei paralýticum jacéntem in lecto. Et videns Jesus fidem illórum, dixit paralýtico: Confíde, fili, remittúntur tibi peccáta tua. Et ecce, quidam de scribis dixérunt intra se: Hic blasphémat. Et cum vidísset Jesus cogitatiónes eórum, dixit: Ut quid cogitátis mala in córdibus vestris? Quid est facílius dícere: Dimittúntur tibi peccáta tua; an dícere: Surge et ámbula? Ut autem sciátis, quia Fílius hóminis habet potestátem in terra dimitténdi peccáta, tunc ait paralýtico: Surge, tolle lectum tuum, et vade in domum tuam. Et surréxit et ábiit in domum suam. Vidéntes autem turbæ timuérunt, et glorificavérunt Deum, qui dedit potestátem talem homínibus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 9:1-8\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, subindo Jesus para uma barca, passou o lago e foi para a cidade de Cafarnaum, onde Lhe apresentaram um paralítico, deitado num leito. Vendo Jesus a fé de todos, disse ao paralítico: «Tem confiança, meu filho, os teus pecados ficam-te perdoados». Logo alguns dos escribas disseram intimamente: «Este homem blasfema!». Jesus, conhecendo os seus pensamentos, disse-lhes: «Para que cogitais mal nos vossos corações? Qual é mais fácil dizer: Os teus pecados ficam-te perdoados, ou levanta-te e caminha? Pois, para que conheçais que o Filho do homem tem na terra poder de perdoar os pecados, levanta-te \u003cFONT SIZE='1' COLOR=\"red\">continuou Ele, dirigindo-se ao paralítico\u003c/FONT>, leva a tua cama e vai para tua casal». E o paralítico levantou-se e foi para casa. Vendo as turbas do povo este acontecimento, ficaram cheias de temor e deram glória a Deus, que havia dado tal poder aos homens!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Exodi 24:4; 24:5\u003c/I>\u003c/FONT>\u003cbr/>\nSanctificávit Móyses altáre Dómino, ófferens super illud holocáusta et ímmolans víctimas: fecit sacrifícium vespertínum in odórem suavitátis Dómino Deo, in conspéctu filiórum Israël.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ex 24:4-5\u003c/I>\u003c/FONT>\u003cbr/>\nMoisés consagrou um altar ao Senhor, sobre o qual ofereceu holocaustos e imolou vítimas: e na presença dos filhos de Israel celebrou o sacrifício da tarde em odor de suavidade ao Senhor.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDeus, qui nos, per hujus sacrifícii veneránda commércia, uníus summæ divinitátis partícipes éfficis: præsta, quǽsumus; ut, sicut tuam cognóscimus veritátem, sic eam dignis móribus assequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Remigii Episcopi et Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ancti tui, quǽsumus, Dómine, nos ubíque lætíficant: ut, dum eórum mérita recólimus, patrocínia sentiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nÓ Deus, que, pela augusta mudança que este sacrifício estabelece entre Vós e nós, nos fazeis participantes da vossa divindade una e soberana, permiti, Vos imploramos, que, conhecendo a vossa verdade, mostremos possuí-la nos nossos costumes dignos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Remígio, Bispo e Confessor\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue os vossos santos, Senhor, Vos suplicamos, nos alegrem em toda a parte, a fim de que, honrando os seus méritos, sintamos o efeito do seu patrocínio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 95:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nTóllite hóstias, et introíte in átria ejus: adoráte Dóminum in aula sancta ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 95:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nTrazei vossas hóstias e entrai nos átrios do Senhor: adorai o Senhor no seu santo templo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nGrátias tibi reférimus, Dómine, sacro múnere vegetáti: tuam misericórdiam deprecántes; ut dignos nos ejus participatióne perfícias.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Remigii Episcopi et Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta, quǽsumus, omnípotens Deus: ut, de percéptis munéribus grátias exhibéntes, intercedénte beáto Remígio Confessóre tuo atque Pontífice, benefícia potióra sumámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nVos damos graças, Senhor, por nos haverdes alimentado com o sacratíssimo dom; e imploramos da vossa misericórdia que nos torneis dignos desta participação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Remígio, Bispo e Confessor\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ignai-Vos permitir, ó Deus omnipotente, que, dando-Vos nós graças pelos benefícios recebidos, alcancemos por intercessão do B. Remígio, vosso Confessor e Pontífice, ainda outros maiores.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-02":{"date":"2026-10-02","title":"Santos Anjos da Guarda","forms":[{"number":1,"title":"Ss. Angelorum Custodum Duplex majus vide Commune Confessoris Pontificis (Missa Statuit) [Commune/C4.txt]","winner":"Sancti/10-02.txt","rule":"Gloria\nCredoDA\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 102:20\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>B\u003c/I>\u003c/B>\u003c/FONT>enedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 102:1\u003c/I>\u003c/FONT>\u003cbr/>\nBenedic, ánima mea, Dómino: et ómnia, quæ intra me sunt, nómini sancto ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>B\u003c/I>\u003c/B>\u003c/FONT>enedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 102:20\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>B\u003c/I>\u003c/B>\u003c/FONT>endizei o Senhor, ó vós, todos os Anjos do Senhor: Sois cheios de poder e virtude: e fazeis o que Ele vos manda, obedecendo às suas palavras e ordens.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 102:1\u003c/I>\u003c/FONT>\u003cbr/>\nBendiz o Senhor, ó minha alma: Que tudo quanto houver em mim bendiga o santo Nome do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>B\u003c/I>\u003c/B>\u003c/FONT>endizei o Senhor, ó vós, todos os Anjos do Senhor: Sois cheios de poder e virtude: e fazeis o que Ele vos manda, obedecendo às suas palavras e ordens.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui ineffábili providéntia sanctos Angelos tuos ad nostram custódiam míttere dignáris: largíre supplícibus tuis; et eórum semper protectióne deféndi, et ætérna societáte gaudére.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que por vossa inefável Providência Vos dignastes mandar os vossos Anjos para nos guardarem, concedei aos vossos suplicantes a graça de serem sempre defendidos pela sua protecção e de gozarem eternamente, a sua companhia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Exodi\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Exod 23:20-23\u003c/I>\u003c/FONT>\u003cbr/>\nHæc dicit Dóminus Deus: Ecce, ego mittam Angelum meum, qui præcédat te, et custódiat in via, et intróducat in locum, quem parávi. Obsérva eum, et audi vocem ejus, nec contemnéndum putes: quia non dimíttet, cum peccáveris, et est nomen meum in illo. Quod si audiéris vocem ejus et féceris ómnia, quæ loquor, inimícus ero inimícis tuis et affligam affligéntes te: præcedétque te Angelus meus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro Êxodo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ex 23:20-23\u003c/I>\u003c/FONT>\u003cbr/>\nIsto diz o Senhor, nosso Deus: «Eis que enviarei o meu Anjo, a fim de que ele vá adiante de vós; vos guarde no caminho; e vos introduza no lugar que vos preparei. Respeitai-o, ouvi a sua voz e não deixeis de atendê-lo, porque vos não perdoará, quando pecardes. Ele vos falará em meu nome. Se escutardes a sua voz e se fizerdes o que vos ordenar, serei inimigo do vosso inimigo e afligirei aqueles que vos afligirem, pois o meu Anjo preceder-vos-á».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 90:11-12\u003c/I>\u003c/FONT>\u003cbr/>\nAngelis suis Deus mandávit de te, ut custódiant te in ómnibus viis tuis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In mánibus portábunt te, ne umquam offéndas ad lápidem pedem tuum.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 102:21.\u003c/I>\u003c/FONT>\u003cbr/>\nBenedícite Dómino, omnes virtútes ejus: minístri ejus, qui fácitis voluntátem ejus. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 90:11-12\u003c/I>\u003c/FONT>\u003cbr/>\nDeus mandou aos seus Anjos que te guardassem em todas as tuas vias.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E eles te conduzirão em cima de suas mãos, para que o teu pé não tropece. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 102:21\u003c/I>\u003c/FONT>\u003cbr/>\nBendizei todos o Senhor, ó exércitos do Senhor; pois estais ao seu serviço e desempenhais as suas ordens. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 18:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Accessérunt discípuli ad Jesum, dicéntes: Quis, putas, major est in regno cœlórum? Et ádvocans Jesus párvulum, státuit eum in médio eórum et dixit: Amen, dico vobis, nisi convérsi fuéritis et efficiámini sicut párvuli, non intrábitis in regnum cœlórum. Quicúmque ergo humiliáverit se sicut párvulus iste, hic est major in regno cœlórum. Et qui suscéperit unum párvulum talem in nómine meo, me súscipit. Qui autem scandalizáverit unum de pusíllis istis, qui in me credunt, expédit ei, ut suspendátur mola asinária in collo ejus, et demergátur in profúndum maris. Væ mundo a scándalis! Necésse est enim, ut véniant scándala: verúmtamen væ hómini illi, per quem scándalum venit! Si autem manus tua vel pes tuus scandalízat te, abscíde eum et projíce abs te: bonum tibi est ad vitam ingrédi débilem vel claudum, quam duas manus vel duos pedes habéntem niitti in ignem ætérnum. Et si óculus tuus scandalízat te, érue eum et projice abs te: bonum tibi est cum uno óculo in vitam intráre, quam duos óculos habéntem mitti in gehénnam ignis. Vidéte, ne contemnátis unum ex his pusíllis: dico enim vobis, quia Angeli eórum in cœlis semper vident fáciem Patris mei, qui in cœlis est.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 18:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, os discípulos aproximaram-se de Jesus, dizendo-Lhe: «Quem, pois, pensais Vós que é o maior no reino dos céus?». Jesus, havendo chamado um pequeno, colocou-o no meio deles e disse: «Em verdade vos digo: Se vos não converteis e não vos tornais como os pequenos, não entrareis no reino dos céus; todo aquele que se fizer pequeno, como este menino, esse, é o maior no reino dos céus; e quem receber um destes pequenos em meu nome, recebe-me a mim mesmo; e quem escandalizar um destes pequenos, que crêem em mim, melhor será que se lhe pendure ao pescoço uma mó de moinho e seja lançado ao fundo do mar! Ai do mundo por causa dos escândalos! Contudo é necessário que aconteçam os escândalos; mas ai do homem por quem vier o escândalo. Se a vossa mão ou o vosso pé são ocasião de escândalo, cortai-os e lançai-os para longe; pois melhor é entrar na vida manco ou coxo do que ser lançado no fogo eterno, tendo as duas mãos ou os dois pés. Se o vosso olho é ocasião de escândalo, arrancai-o e lançai-o para longe; pois é melhor entrar na vida só com um olho do que ser lançado no fogo eterno, tendo os dois olhos. Vede que não seja desprezado nenhum destes pequeninos; pois, digo-vos: os seus Anjos nos céus estão sempre na presença de meu Pai, que está nos céus».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 102:20-21\u003c/I>\u003c/FONT>\u003cbr/>\nBenedícite Dóminum, omnes Angeli ejus: minístri ejus, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 102:20-21\u003c/I>\u003c/FONT>\u003cbr/>\nBendizei o Senhor, ó vós, Anjos, heróis poderosos, executores das suas ordens e sempre fiéis aos seus chamamentos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSúscipe, Dómine, múnera, quæ pro sanctórum Angelórum tuórum veneratióne deférimus: et concéde propítius; ut, perpétuis eórum præsídiis, a præséntibus perículis liberémur et ad vitam perveniámus ætérnam.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nRecebei, Senhor, as ofertas que Vos apresentamos em honra dos vossos Santos Anjos e concedei-nos propício que pela sua contínua protecção sejamos livres dos perigos da vida presente e alcancemos a vida eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dan 3:58\u003c/I>\u003c/FONT>\u003cbr/>\nBenedícite, omnes Angeli Dómini, Dóminum: hymnum dícite et superexaltáte eum in sǽcula.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dn 3:58\u003c/I>\u003c/FONT>\u003cbr/>\nAnjos do Senhor, bendizei todos o Senhor: cantai hinos em seu louvor e exaltai-O em todos os séculos.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSúmpsimus, Dómine, divína mystéria, sanctórum Angelórum tuórum festivitáte lætántes: quǽsumus; ut eórum protectióne ab hóstium júgiter liberémur insídiis, et contra ómnia advérsa muniámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido os divinos mystérios enquanto celebramos com júbilo a festa dos vossos Santos Anjos, dignai-Vos permitir, Vos suplicamos, que pela sua protecção sejamos sempre livres das insídias dos nossos inimigos e de todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-03":{"date":"2026-10-03","title":"Santa Teresinha do Menino Jesus, virgem","forms":[{"number":1,"title":"S. Theresiæ a Jesu Infante Virginis Duplex vide Commune Unius Virginis tantum (Missa Dilexisti) [Commune/C6a.txt]","winner":"Sancti/10-03.txt","rule":"vide C6a;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cant 4:8-9.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>eni de Líbano, sponsa mea, veni de Líbano, veni: vulnerásti cor meum, soror mea sponsa, vulnerásti cor meum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 112:1\u003c/I>\u003c/FONT>\u003cbr/>\nLaudáte, púeri, Dóminum: laudáte nomen Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>eni de Líbano, sponsa mea, veni de Líbano, veni: vulnerásti cor meum, soror mea sponsa, vulnerásti cor meum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ct 4:8-9\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>em comigo do Líbano, ó minha esposa; Vem comigo do Líbano; vem. Tu feriste o meu coração, minha irmã, minha esposa; tu feriste o meu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 112:1\u003c/I>\u003c/FONT>\u003cbr/>\nLouvai o Senhor, ó meninos; louvai o nome do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>em comigo do Líbano, ó minha esposa; Vem comigo do Líbano; vem. Tu feriste o meu coração, minha irmã, minha esposa; tu feriste o meu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDómine, qui dixísti: Nisi efficiámini sicut párvuli, non intrábitis in regnum cœlórum: da nobis, quǽsumus: ita sanctæ Teresiæ Vírginis in humilitáte et simplicitáte cordis vestígia sectári, ut præmia consequámur ætérna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, que Vos dignastes ensinar-nos «Se vos não tornardes semelhantes a estes pequenos não entrareis no reino dos céus», concedei-nos, Vos suplicamos, que de tal modo imitemos os exemplos da humildade e simplicidade da Virgem Santa Teresa que consigamos alcançar os prémios eternos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Isaíæ Prophétæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Is 66:12-14\u003c/I>\u003c/FONT>\u003cbr/>\nHæc dicit Dóminus: Ecce, ego declinábo super eam quasi flúvium pacis, et quasi torréntem inundántem glóriam géntium, quam sugétis: ad úbera portabímini, et super génua blandiéntur vobis. Quómodo si cui mater blandiátur, ita ego consolábor vos, et in Jerúsalem consolabímini. Vidébitis, et gaudébit cor vestrum, et ossa vestra quasi herba germinábunt, et cognoscétur manus Dómini servis ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Profeta Isaías.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Is 66:12-14\u003c/I>\u003c/FONT>\u003cbr/>\nAssim fala o Senhor: «Eis que farei correr sobre ela como que um rio de paz; e como que uma torrente caudalosa inundará com riquezas os povos. Sereis alimentados com leite, acalentados no seu seio e acariciados sobre os seus joelhos. Eu vos consolarei, como aquele a quem a mãe consola; e serei a vossa alegria em Jerusalém. Vê-lo-eis, e regozijar-se-á o vosso coração; os vossos ossos reconquistarão o vigor, como a erva dos campos; e a mão do Senhor se manifestará em favor dos seus servos».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 11:25\u003c/I>\u003c/FONT>\u003cbr/>\nConfíteor tibi, Pater, Dómine cœli et terræ, quia abscondísti hæc a sapiéntibus, et prudéntibus, et revelásti ea párvulis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 70:5\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, spes mea a juventúte mea.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 39:17-19\u003c/I>\u003c/FONT>\u003cbr/>\nQuasi rosa plantáta super rivos aquárum fructificate: quasi Libanus odórem suavitátis habete: florete, flores, quasi lílium, et date odórem, et frondete in grátiam, et collaudate cánticum, et benedicite Dóminum in opéribus suis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 11:25\u003c/I>\u003c/FONT>\u003cbr/>\nDou-Vos graças, ó Pai, Senhor do céu e da terra, porque ocultastes estas cousas aos sábios e aos prudentes deste mundo, e as revelastes aos «pequenos».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 70:5\u003c/I>\u003c/FONT>\u003cbr/>\nSois a minha esperança, Senhor, desde a minha juventude. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 39:17-19\u003c/I>\u003c/FONT>\u003cbr/>\nFrutificai, como a rosa plantada à beira das águas; espalhai vosso suave perfume, como o monte Líbano; como os lírios, desabrochai vossas flores e exalai vossos perfumes; enchei-vos de beleza; entoai hinos e cânticos em honra do Senhor, louvando-O Pela magnificência das suas obras. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 18:1-4\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Accessérunt discípuli ad Jesum, dicéntes: Quis, putas, major est in regno cœlórum? Et advocans Jesus párvulum, státuit eum in médio eórum, et dixit; Amen, dico vobis, nisi convérsi fuéritis, et efficiámini sicut párvuli, non intrábitis in regnum cœlorum. Quicúmque ergo humiliáverit se sicut párvulus iste, hic est major in regno cœlórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 18:1-4\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, aproximaram-se de Jesus os seus discípulos, dizendo-Lhe: «Qual pensais Vós que é o maior no reino dos céus?». E Jesus, havendo chamado um pequeno, colocou-o no meio deles e disse: «Em verdade vos digo: se vos não converteis e não vos tornais como os pequenos, não entrareis no reino dos céus».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 1:46-49\u003c/I>\u003c/FONT>\u003cbr/>\nMagníficat ánima mea Dóminum: et exsultávit spíritus meus in Deo salutári meo: quia respéxit humilitátem ancíllæ suæ: fecit mihi magna qui potens est.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 1:46-49\u003c/I>\u003c/FONT>\u003cbr/>\nA minha alma engrandece o Senhor e o meu espírito alegra-se em Deus, meu Salvador, pois Ele dignou-se olhar benignamente para a humildade da sua escrava; e praticou em mim grandes cousas.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSacrifícium nostrum tibi, Dómine, quǽsumus, sanctæ Terésiæ Vírginis tuæ precátio sancta concíliet: ut, in cujus honóre sollémniter exhibétur, ejus méritis efficiátur accéptum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor, Vos suplicamos, permiti que a oração da vossa Virgem Santa Teresa Vos torne agradável o nosso sacrifício, a fim de que por Vós seja aceite, pelos méritos daquela em cuja honra Vo-lo oferecemos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deut 32:10-12\u003c/I>\u003c/FONT>\u003cbr/>\nCircumdúxit eam, et dócuit: et custodívit quasi pupíllam óculi sui. Sicut aquila expándit alas suas, et assúmpsit eam, atque portávit in húmeris suis. Dóminus solus dux ejus fuit.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dt 32:10-12\u003c/I>\u003c/FONT>\u003cbr/>\nRodeou-a, protegeu-a e guardou-a, como à pupila dos seus olhos. Como a águia, abriu suas asas, arrebatou-a e colocou-a sobre os seus joelhos. O Senhor foi o seu único guia.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nIllo nos, Dómine amóris igne cœléste mystérium inflámmet: quo sancta Teresia Virgo tua se tibi pro homínibus caritátis víctimam devóvit.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nQue este mystério, Senhor, nos abrase no fogo celestial, ao qual a vossa Virgem Santa Teresa se ofereceu como vítima de amor pelos homens.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-04":{"date":"2026-10-04","title":"XIX Domingo depois de Pentecostes","forms":[{"number":1,"title":"Dominica XIX Post Pentecosten I. Octobris\tSemiduplex","winner":"Tempora/Pent19-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alus pópuli ego sum, dicit Dóminus: de quacúmque tribulatióne clamáverint ad me, exáudiam eos: et ero illórum Dóminus in perpétuum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 77:1\u003c/I>\u003c/FONT>\u003cbr/>\nAttendite, pópule meus, legem meam: inclináte aurem vestram in verba oris mei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alus pópuli ego sum, dicit Dóminus: de quacúmque tribulatióne clamáverint ad me, exáudiam eos: et ero illórum Dóminus in perpétuum\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ou a salvação do povo, diz o Senhor; em qualquer tribulação clamarão por mim e ouvi-los-ei, pois serei o seu Senhor eternamente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 77:1\u003c/I>\u003c/FONT>\u003cbr/>\nSede atentos à minha Lei, ó meu povo; escutai as palavras que saem da minha boca.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ou a salvação do povo, diz o Senhor; em qualquer tribulação clamarão por mim e ouvi-los-ei, pois serei o seu Senhor eternamente.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens et miséricors Deus, univérsa nobis adversántia propitiátus exclúde: ut mente et córpore páriter expedíti, quæ tua sunt, líberis méntibus exsequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e misericordioso, afastai benignamente de nós tudo quanto se opõe à salvação, a fim de que, estando a nossa alma e o nosso corpo livres de todos os obstáculos, possamos com inteira liberdade de espírito cumprir o que diz respeito ao vosso serviço.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Ephésios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ephes 4:23-28\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Renovámini spíritu mentis vestræ, et indúite novum hóminem, qui secúndum Deum creátus est in justítia et sanctitáte veritátis. Propter quod deponéntes mendácium, loquímini veritátem unusquísque cum próximo suo: quóniam sumus ínvicem membra. Irascímini, et nolíte peccáre: sol non occídat super iracúndiam vestram. Nolíte locum dare diábolo: qui furabátur, jam non furétur; magis autem labóret, operándo mánibus suis, quod bonum est, ut hábeat, unde tríbuat necessitátem patiénti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Efésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eph 4:23-28\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Renovai-vos no íntimo da vossa alma e revesti-vos do «homem novo», que foi criado à semelhança de Deus na justiça e santidade verdadeiras. Eis porque deveis renunciar à mentira, e falar a cada um, nas relações com o próximo, segundo a verdade, pois somos todos membros uns dos outros. Se vos irardes, que seja sem pecar; e que o sol se não esconda sem que a vossa ira desapareça. Não deis lugar no vosso coração ao demónio. Aquele que furtava não torne a furtar, mas trabalhe, empregando as mãos em alguma obra boa e útil, para socorrer os que padecem de necessidade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 140:2\u003c/I>\u003c/FONT>\u003cbr/>\nDirigátur orátio mea, sicut incénsum in conspéctu tuo, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Elevatio mánuum meárum sacrifícium vespertínum. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 104:1\u003c/I>\u003c/FONT>\u003cbr/>\nConfitémini Dómino, et invocáte nomen ejus: annuntiáte inter gentes ópera ejus. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 140:2\u003c/I>\u003c/FONT>\u003cbr/>\nQue a minha oração, Senhor, chegue até Vós, como perfume de incenso:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E que minhas mãos erguidas Vos sejam agradáveis, como o sacrifício vespertino. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 104:1\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Louvai o Senhor e invocai o seu nome: publicai as suas obras em todos os povos. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 22:1-14\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Loquebátur Jesus princípibus sacerdótum et pharisǽis in parábolis, dicens: Símile factum est regnum cœlórum hómini regi, qui fecit núptias fílio suo. Et misit servos suos vocáre invitátos ad nuptias, et nolébant veníre. Iterum misit álios servos, dicens: Dícite invitátis: Ecce, prándium meum parávi, tauri mei et altília occísa sunt, et ómnia paráta: veníte ad núptias. Illi autem neglexérunt: et abiérunt, álius in villam suam, álius vero ad negotiatiónem suam: réliqui vero tenuérunt servos ejus, et contuméliis afféctos occidérunt. Rex autem cum audísset, iratus est: et, missis exercítibus suis, pérdidit homicídas illos et civitátem illórum succéndit. Tunc ait servis suis: Núptiæ quidem parátæ sunt, sed, qui invitáti erant, non fuérunt digni. Ite ergo ad exitus viárum et, quoscúmque invenéritis, vocáte ad núptias. Et egréssi servi ejus in vias, congregavérunt omnes, quos invenérunt, malos et bonos: et implétæ sunt núptiæ discumbéntium. Intrávit autem rex, ut vidéret discumbéntes, et vidit ibi hóminem non vestítum veste nuptiáli. Et ait illi: Amíce, quómodo huc intrásti non habens vestem nuptiálem? At ille obmútuit. Tunc dixit rex minístris: Ligátis mánibus et pédibus ejus, míttite eum in ténebras exterióres: ibi erit fletus et stridor déntium. Multi enim sunt vocáti, pauci vero elécti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 22:1-14\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, falando Jesus aos príncipes dos sacerdotes e aos fariseus por meio de parábolas, disse-lhes: O reino dos céus é semelhante a um rei que, que rendo celebrar as bodas do filho, mandou os servos chamar aqueles que haviam sido convidados para assistir. Eles, porém, não quiseram vir. Novamente mandou outros servos com esta participação: «Preparei o banquete; estão já mortos os bois e os animais gordos; tudo está preparado; vinde, pois, às bodas». Mas nenhuma atenção lhes dispensaram; e um foi para a sua casa de campo, outro para os seus negócios, e ainda outros detiveram os servos, ultrajando-os e matando-os. Então o rei, tendo conhecimento do que se passara, ficou cheio de ira e mandou os seus exércitos matar os assassinos e queimar a sua cidade. Depois disse aos servos: «As bodas estão preparadas, mas aqueles que haviam sido convidados não eram dignos. Ide vós, pois, pelas encruzilhadas dos caminhos e chamai para as bodas todos quantos encontrardes». Saíram os servos pelos caminhos e reuniram todos quantos encontraram, quer bons, quer maus, ficando cheia de convivas a sala das bodas. Entretanto o rei entrou para ver os que estavam. E tendo visto um dos convivas sem as vestes das bodas, disse-lhe: «Amigo, como te atreveste a entrar sem a veste das bodas?». O conviva guardou silêncio. Então o rei disse aos servos: «Amarrai-o de pés e mãos e lançai-o fora nas trevas, nesse lugar de choro e de ranger de dentes; pois muitos são os chamados, mas poucos os escolhidos».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 137:7\u003c/I>\u003c/FONT>\u003cbr/>\nSi ambulávero in médio tribulatiónis, vivificábis me, Dómine: et super iram inimicórum meórum exténdes manum tuam, et salvum me fáciet déxtera tua.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 137:7\u003c/I>\u003c/FONT>\u003cbr/>\nQuando estiver na tribulação, dar-me-eis a vida, Senhor! Estendereis a vossa mão contra o furor dos meus inimigos: e serei salvo pela vossa dextra.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHæc múnera, quǽsumus, Dómine, quæ óculis tuæ majestátis offérimus, salutária nobis esse concéde.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor, permiti que estes dons, que colocamos diante da vossa majestade, sejam úteis à nossa salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:4-5\u003c/I>\u003c/FONT>\u003cbr/>\nTu mandásti mandáta tua custodíri nimis: útinam dirigántur viæ meæ, ad custodiéndas justificatiónes tuas.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:4-5\u003c/I>\u003c/FONT>\u003cbr/>\nOrdenastes que os vossos mandamentos fossem cabalmente cumpridos: dignai-Vos, pois, dirigir os meus passos, para que sigam o caminho das vossas ordens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nTua nos, Dómine, medicinális operátio, et a nostris perversitátibus cleménter expédiat, et tuis semper fáciat inhærére mandátis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, Senhor, que as operações da vossa graça nos sirvam de remédio contra as perversidades; e, pela vossa clemência, dignai-Vos livrar-nos das más inclinações e manter-nos no cumprimento dos vossos mandamentos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-05":{"date":"2026-10-05","title":"Féria da 19ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Secunda infra Hebdomadam XIX post Octavam Pentecostes I. Octobris\tFeria","winner":"Tempora/Pent19-1.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alus pópuli ego sum, dicit Dóminus: de quacúmque tribulatióne clamáverint ad me, exáudiam eos: et ero illórum Dóminus in perpétuum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 77:1\u003c/I>\u003c/FONT>\u003cbr/>\nAttendite, pópule meus, legem meam: inclináte aurem vestram in verba oris mei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alus pópuli ego sum, dicit Dóminus: de quacúmque tribulatióne clamáverint ad me, exáudiam eos: et ero illórum Dóminus in perpétuum\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ou a salvação do povo, diz o Senhor; em qualquer tribulação clamarão por mim e ouvi-los-ei, pois serei o seu Senhor eternamente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 77:1\u003c/I>\u003c/FONT>\u003cbr/>\nSede atentos à minha Lei, ó meu povo; escutai as palavras que saem da minha boca.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ou a salvação do povo, diz o Senhor; em qualquer tribulação clamarão por mim e ouvi-los-ei, pois serei o seu Senhor eternamente.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens et miséricors Deus, univérsa nobis adversántia propitiátus exclúde: ut mente et córpore páriter expedíti, quæ tua sunt, líberis méntibus exsequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Placidi et Sociorum Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui nos concédis sanctórum Mártyrum tuórum Plácidi et Sociórum ejus natalítia cólere: da nobis in ætérna beatitúdine de eórum societáte gaudére.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e misericordioso, afastai benignamente de nós tudo quanto se opõe à salvação, a fim de que, estando a nossa alma e o nosso corpo livres de todos os obstáculos, possamos com inteira liberdade de espírito cumprir o que diz respeito ao vosso serviço.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Ss. Placidi et Sociorum Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que nos permitistes a graça de celebrarmos o nascimento no céu dos vossos Santos Mártires Plácidi et Sociórum ejus, concedei-nos ainda a graça de gozarmos na sua companhia a bem-aventurança eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Ephésios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ephes 4:23-28\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Renovámini spíritu mentis vestræ, et indúite novum hóminem, qui secúndum Deum creátus est in justítia et sanctitáte veritátis. Propter quod deponéntes mendácium, loquímini veritátem unusquísque cum próximo suo: quóniam sumus ínvicem membra. Irascímini, et nolíte peccáre: sol non occídat super iracúndiam vestram. Nolíte locum dare diábolo: qui furabátur, jam non furétur; magis autem labóret, operándo mánibus suis, quod bonum est, ut hábeat, unde tríbuat necessitátem patiénti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Efésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eph 4:23-28\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Renovai-vos no íntimo da vossa alma e revesti-vos do «homem novo», que foi criado à semelhança de Deus na justiça e santidade verdadeiras. Eis porque deveis renunciar à mentira, e falar a cada um, nas relações com o próximo, segundo a verdade, pois somos todos membros uns dos outros. Se vos irardes, que seja sem pecar; e que o sol se não esconda sem que a vossa ira desapareça. Não deis lugar no vosso coração ao demónio. Aquele que furtava não torne a furtar, mas trabalhe, empregando as mãos em alguma obra boa e útil, para socorrer os que padecem de necessidade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 140:2\u003c/I>\u003c/FONT>\u003cbr/>\nDirigátur orátio mea, sicut incénsum in conspéctu tuo, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Elevatio mánuum meárum sacrifícium vespertínum. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 104:1\u003c/I>\u003c/FONT>\u003cbr/>\nConfitémini Dómino, et invocáte nomen ejus: annuntiáte inter gentes ópera ejus. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 140:2\u003c/I>\u003c/FONT>\u003cbr/>\nQue a minha oração, Senhor, chegue até Vós, como perfume de incenso:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E que minhas mãos erguidas Vos sejam agradáveis, como o sacrifício vespertino. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 104:1\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Louvai o Senhor e invocai o seu nome: publicai as suas obras em todos os povos. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 22:1-14\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Loquebátur Jesus princípibus sacerdótum et pharisǽis in parábolis, dicens: Símile factum est regnum cœlórum hómini regi, qui fecit núptias fílio suo. Et misit servos suos vocáre invitátos ad nuptias, et nolébant veníre. Iterum misit álios servos, dicens: Dícite invitátis: Ecce, prándium meum parávi, tauri mei et altília occísa sunt, et ómnia paráta: veníte ad núptias. Illi autem neglexérunt: et abiérunt, álius in villam suam, álius vero ad negotiatiónem suam: réliqui vero tenuérunt servos ejus, et contuméliis afféctos occidérunt. Rex autem cum audísset, iratus est: et, missis exercítibus suis, pérdidit homicídas illos et civitátem illórum succéndit. Tunc ait servis suis: Núptiæ quidem parátæ sunt, sed, qui invitáti erant, non fuérunt digni. Ite ergo ad exitus viárum et, quoscúmque invenéritis, vocáte ad núptias. Et egréssi servi ejus in vias, congregavérunt omnes, quos invenérunt, malos et bonos: et implétæ sunt núptiæ discumbéntium. Intrávit autem rex, ut vidéret discumbéntes, et vidit ibi hóminem non vestítum veste nuptiáli. Et ait illi: Amíce, quómodo huc intrásti non habens vestem nuptiálem? At ille obmútuit. Tunc dixit rex minístris: Ligátis mánibus et pédibus ejus, míttite eum in ténebras exterióres: ibi erit fletus et stridor déntium. Multi enim sunt vocáti, pauci vero elécti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 22:1-14\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, falando Jesus aos príncipes dos sacerdotes e aos fariseus por meio de parábolas, disse-lhes: O reino dos céus é semelhante a um rei que, que rendo celebrar as bodas do filho, mandou os servos chamar aqueles que haviam sido convidados para assistir. Eles, porém, não quiseram vir. Novamente mandou outros servos com esta participação: «Preparei o banquete; estão já mortos os bois e os animais gordos; tudo está preparado; vinde, pois, às bodas». Mas nenhuma atenção lhes dispensaram; e um foi para a sua casa de campo, outro para os seus negócios, e ainda outros detiveram os servos, ultrajando-os e matando-os. Então o rei, tendo conhecimento do que se passara, ficou cheio de ira e mandou os seus exércitos matar os assassinos e queimar a sua cidade. Depois disse aos servos: «As bodas estão preparadas, mas aqueles que haviam sido convidados não eram dignos. Ide vós, pois, pelas encruzilhadas dos caminhos e chamai para as bodas todos quantos encontrardes». Saíram os servos pelos caminhos e reuniram todos quantos encontraram, quer bons, quer maus, ficando cheia de convivas a sala das bodas. Entretanto o rei entrou para ver os que estavam. E tendo visto um dos convivas sem as vestes das bodas, disse-lhe: «Amigo, como te atreveste a entrar sem a veste das bodas?». O conviva guardou silêncio. Então o rei disse aos servos: «Amarrai-o de pés e mãos e lançai-o fora nas trevas, nesse lugar de choro e de ranger de dentes; pois muitos são os chamados, mas poucos os escolhidos».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 137:7\u003c/I>\u003c/FONT>\u003cbr/>\nSi ambulávero in médio tribulatiónis, vivificábis me, Dómine: et super iram inimicórum meórum exténdes manum tuam, et salvum me fáciet déxtera tua.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 137:7\u003c/I>\u003c/FONT>\u003cbr/>\nQuando estiver na tribulação, dar-me-eis a vida, Senhor! Estendereis a vossa mão contra o furor dos meus inimigos: e serei salvo pela vossa dextra.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHæc múnera, quǽsumus, Dómine, quæ óculis tuæ majestátis offérimus, salutária nobis esse concéde.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Placidi et Sociorum Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>désto, Dómine, supplicatiónibus nostris, quas in Sanctórum tuórum commemoratióne deférimus: ut, qui nostræ justítiæ fidúciam non habémus, eórum, qui tibi placuérunt, méritis adjuvémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor, permiti que estes dons, que colocamos diante da vossa majestade, sejam úteis à nossa salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Ss. Placidi et Sociorum Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>tendei, Senhor, às súplicas que Vos dirigimos em memória dos vossos Santos, a fim de que nós, que não temos confiança na nossa própria justiça, sejamos auxiliados pelos méritos daqueles que Vos agradaram nesta vida.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:4-5\u003c/I>\u003c/FONT>\u003cbr/>\nTu mandásti mandáta tua custodíri nimis: útinam dirigántur viæ meæ, ad custodiéndas justificatiónes tuas.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:4-5\u003c/I>\u003c/FONT>\u003cbr/>\nOrdenastes que os vossos mandamentos fossem cabalmente cumpridos: dignai-Vos, pois, dirigir os meus passos, para que sigam o caminho das vossas ordens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nTua nos, Dómine, medicinális operátio, et a nostris perversitátibus cleménter expédiat, et tuis semper fáciat inhærére mandátis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Placidi et Sociorum Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta nobis, quǽsumus, Dómine: intercedéntibus sanctis Martýribus tuis Plácido et Sóciis ejus; ut, quod ore contíngimus, pura mente capiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, Senhor, que as operações da vossa graça nos sirvam de remédio contra as perversidades; e, pela vossa clemência, dignai-Vos livrar-nos das más inclinações e manter-nos no cumprimento dos vossos mandamentos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Ss. Placidi et Sociorum Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, por intercessão dos vossos santos Mártires Plácido et Sóciis ejus, dignai-Vos conceder-nos a graça de guardarmos com o coração sempre puro o que a nossa boca agora recebeu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-06":{"date":"2026-10-06","title":"São Bruno, confessor","forms":[{"number":1,"title":"S. Brunonis Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/10-06.txt","rule":"vide C5;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSancti Brunónis Confessóris tui, quǽsumus, Dómine, intercessiónibus adjuvémur: ut, qui majestátem tuam gráviter delinquéndo offéndimus, ejus méritis et précibus, nostrórum delictórum véniam consequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nQue a intercessão do vosso Santo Confessor Bruno nos auxilie, Senhor, Vos rogamos, a fim de que, havendo ofendido gravemente a vossa majestade, obtenhamos o perdão dos nossos pecados pelos méritos e preces do mesmo santo.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ecl 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o homem que foi julgado sem mácula; que não correu após o ouro; e não pôs as esperanças nem no dinheiro, nem nos tesouros! Quem é ele, para que o louvemos? Porquanto operou cousas admiráveis durante a vida. Aquele que foi provado pelo ouro e foi julgado perfeito alcançará a glória eterna; pois poderia ter violado o mandamento, e o não violou; poderia ter praticado acções más, e as não praticou. É por esta razão que seus bens lhe estarão assegurados no Senhor e que toda a assembleia dos justos proclamará as boas acções que praticou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ja 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nPara publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sabe sofrer a tentação, porque, quando acabar a tentação, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Estejam cingidos os vossos rins; tende nas vossas mãos lâmpadas acesas; sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para que, quando chegar e bater à porta, logo lha abram. Bem-aventurados aqueles servos que seu senhor, quando chegar, os achar vigilantes. Em verdade vos digo que se cingirá, e, mandando-os sentar à mesa, passará por entre eles e os servirá. E, se chegar na segunda ou terceira vigília e assim os achar, bem-aventurados são esses servos. Ora, sabei que, se o pai de família conhecesse a hora em que viria o ladrão, vigiava, sem dúvida, para que sua casa não fosse assaltada. Vós, pois, estai preparados, porque o Filho do homem virá à hora em que menos cuidais».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLaudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nA Vós, Senhor, imolamos esta víctimas de louvor em memória de vossos Santos, esperando ser livres por sua intercessão de todos os males presentes e futuros.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nQuǽsumus, omnípotens Deus: ut, qui cœléstia aliménta percépimus, intercedénte beáto Brunóne Confessóre tuo, per hæc contra ómnia advérsa muniámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente, Vos imploramos, havendo nós recebido o alimento celestial, fazei que, por intercessão do B. Confessor Bruno sejamos fortificados contra todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-07":{"date":"2026-10-07","title":"Nossa Senhora do Rosário","forms":[{"number":1,"title":"Sanctissimi Rosarii Beatæ Mariæ Virginis Duplex 2 classis ex Commune Beatae Mariae Virginis [Commune/C11.txt]","winner":"Sancti/10-07.txt","rule":"ex C11;\nGloria\nCredo\nPrefatio=Maria=Festivitate;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>G\u003c/I>\u003c/B>\u003c/FONT>audeámus omnes in Dómino, diem festum celebrántes sub honóre beátæ Maríæ Vírginis: de cujus sollemnitáte gaudent Angeli et colláudant Fílium Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>G\u003c/I>\u003c/B>\u003c/FONT>audeámus omnes in Dómino, diem festum celebrántes sub honóre beátæ Maríæ Vírginis: de cujus sollemnitáte gaudent Angeli et colláudant Fílium Dei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>legremo-nos todos no Senhor, no dia em que celebramos a festa em honra da B. V. Maria: os Anjos regozijam-se com esta festa e louvam unissonamente o Filho de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: «Consagro ao Rei as minhas obras»!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>legremo-nos todos no Senhor, no dia em que celebramos a festa em honra da B. V. Maria: os Anjos regozijam-se com esta festa e louvam unissonamente o Filho de Deus.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, cujus Unigénitus per vitam, mortem et resurrectiónem suam nobis salútis ætérnæ præmia comparávit: concéde, quǽsumus; ut, hæc mystéria sacratíssimo beátæ Maríæ Vírginis Rosário recoléntes, et imitémur, quod cóntinent, et quod promíttunt, assequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Marci Papæ Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>v\u003c/I>\u003c/B>\u003c/FONT>. Da, quǽsumus, omnípotens Deus: ut beáti N. Confessóris tui atque Pontíficis veneránda solémnitas, et devotiónem nobis áugeat et salútem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, cujo Filho Unigénito, pela sua vida, morte e ressurreição, nos alcançou os prémios da salvação eterna, fazei, Vos rogamos, que, honrando nós estes mystérios pelo SS. Rosário da B. V. Maria, imitemos o que contêm e obtenhamos o que prometem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Marci Papæ Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Pastor eterno, atendei propício ao vosso rebanho; e guardai-o com vossa perpétua protecção por intercessão do bem-aventurado Marcum Sumo Pontífice, o qual escolhestes como pastor de toda a Igreja.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 8:22-24; 8:32-35\u003c/I>\u003c/FONT>\u003cbr/>\nDóminus possédit me in inítio viárum suárum, ántequam quidquam fáceret a princípio. Ab ætérno ordináta sum et ex antíquis, ántequam terra fíeret. Nondum erant abýssi, et ego jam concépta eram. Nunc ergo, fílii, audíte me: Beáti, qui custódiunt vias meas. Audíte disciplínam, et estóte sapiéntes, et nolíte abjícere eam. Beátus homo, qui audit me et qui vígilat ad fores meas cotídie, et obsérvat ad postes óstii mei. Qui me invénerit, invéniet vitam et háuriet salútem a Dómino.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Pr 8:22-24; 8:32-35\u003c/I>\u003c/FONT>\u003cbr/>\nO Senhor possuiu-me desde o princípio das suas vias e ainda antes de criar qualquer cousa, no princípio, antes da origem da terra. Quando fui concebido, ainda não existiam os abysmos. Portanto, agora, meus filhos, escutai-me: Bem-aventurados aqueles que transitam pelas minhas vias; atendei às instruções, para que sejais prudentes; não as rejeiteis. Bem-aventurado o homem que me escuta; que vigia continuamente às minhas portas; e que está sempre em observação às ombreiras das suas entradas. Aquele que me tiver encontrado, terá encontrado a vida e alcançará do Senhor a salvação.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5; 44:11; 44:12\u003c/I>\u003c/FONT>\u003cbr/>\nPropter veritátem et mansuetúdinem et justítiam, et dedúcet te mirabíliter déxtera tua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Sollémnitas gloriósæ Vírginis Maríæ ex sémine Abrahæ, ortæ de tribu Juda, clara ex stirpe David. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:5; 44:11; 44:12\u003c/I>\u003c/FONT>\u003cbr/>\nReinai pela verdade, mansidão e justiça: e a vossa dextra vos conduzirá admiravelmente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ouvi, minha filha, e vede; inclinai o vosso ouvido, pois o Rei está extasiado com vossa formosura! Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Eis a solenidade da gloriosa Virgem Maria: da raça de Abraão, da geração de Judá e da nobre linhagem de David. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secundum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 1:26-38\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo tempore: Missus est Angelus Gábriel a Deo in civitatem Galilǽæ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Joseph, de domo David, et nomen Vírginis María. Et ingréssus Angelus ad eam, dixit: Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Quæ cum audísset, turbáta est in sermóne ejus: et cogitábat, qualis esset ista salutátio. Et ait Angelus ei: Ne tímeas, María, invenísti enim grátiam apud Deum: ecce, concípies in útero, et páries fílium, et vocábis nomen ejus Jesum. Hic erit magnus, et Fílius Altíssimi vocábitur, et dabit illi Dóminus Deus sedem David, patris ejus: et regnábit in domo Jacob in ætérnum, et regni ejus non erit finis. Dixit autem María ad Angelum: Quómodo fiet istud, quóniam virum non cognósco? Et respóndens Angelus, dixit ei: Spíritus Sanctus supervéniet in te, et virtus Altíssimi obumbrábit tibi. Ideóque et quod nascétur ex te Sanctum, vocábitur Fílius Dei. Et ecce, Elísabeth, cognáta tua, et ipsa concépit fílium in senectúte sua: et hic mensis sextus est illi, quæ vocátur stérilis: quia non erit impossíbile apud Deum omne verbum. Dixit autem María: Ecce ancílla Dómini, fiat mihi secúndum verbum tuum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 1:26-38\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, foi mandado por Deus o Anjo Gabriel a uma cidade da Galileia, chamada Nazaré, a uma Virgem, desposada com um varão, cujo nome era José, da casa de David; e o nome da Virgem era Maria. Entrando o Anjo onde ela estava, disse: «Eu te saúdo, cheia de graça: o Senhor é contigo: bendita és tu entre todas as mulheres». Ouvindo ela isto, perturbou-se; e pensava na significação desta saudação. Então, disse-lhe o Anjo: «Não temas, Maria, porquanto alcançaste graça diante do Senhor: eis que conceberás no teu seio e darás à luz um Filho; e o seu nome será Jesus. Ele será grande e será chamado Filho do Altíssimo; o Senhor Deus lhe dará o trono de David, seu pai; reinará eternamente na casa de Jacob; e o seu reino não terá fim. Porém, Maria disse ao Anjo: «Como acontecerá isso, se não conheço varão?», O Anjo, respondendo, disse-lhe: «O Espírito Santo descerá sobre ti, e a virtude do Altíssimo te tocará com sua sombra. Por isso o Santo, que nascer de ti, será chamado Filho de Deus. E eis que Isabel, tua parenta, concebeu um filho na sua velhice: este é o sexto mês daquela que é chamada estéril: porque nada é impossível a Deus». Então disse Maria: «Eis aqui a escrava do Senhor, faça-se em mim segundo a tua palavra».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 24:25; Eccli 39:17\u003c/I>\u003c/FONT>\u003cbr/>\nIn me grátia omnis viæ et veritátis, in me omnis spes vitæ et virtútis: ego quasi rosa plantáta super rivos aquárum fructificávi.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 24:25; Ecl 39:17\u003c/I>\u003c/FONT>\u003cbr/>\nEm mim reside toda a graça dos caminhos e da verdade; em mim reside toda a esperança da vida e da virtude! Eu floresci, como a roseira plantada nas margens das ribeiras!\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nFac nos, quǽsumus, Dómine, his munéribus offeréndis conveniénter aptári: et per sacratíssimi Rosárii mystéria sic vitam, passiónem et glóriam Unigéniti tui recólere; ut ejus digni promissiónibus efficiámur:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Marci Papæ Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ancti tui, quǽsumus, Dómine, nos ubíque lætíficant: ut, dum eórum mérita recólimus, patrocínia sentiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPermiti, Senhor, Vos suplicamos, que estejamos convenientemente preparados para Vos apresentar estas ofertas; e que pelos mystérios do SS. Rosário honremos de tal sorte a vida, a paixão e a glória do vosso Filho Unigénito que sejamos dignos das suas promessas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Marci Papæ Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>om as ofertas destes dons, Vos suplicamos, Senhor, iluminai benignamente a vossa Igreja, a fim de que não só o vosso rebanho triunfe em toda a parte, mas também pelo poder do vosso nome os pastores sejam bem acolhidos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Beata Maria Virgine\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in Festivitate beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da B. Virgem Maria\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, e de sempre Vos louvar, bendizer e anunciar da Bem-aventurada Maria, sempre Virgem. Foi ela quem concebeu o vosso Filho Unigénito por obra do Espírito Santo, e, sem a mais leve perda de glória da virgindade, deu ao mundo a Luz eterna, Jesus Cristo, Nosso Senhor, por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos céus e os bem-aventurados Serafins a festejam em transportes de alegria. E, Vos imploramos, permiti que unamos as nossas vozes às de todos estes, dizendo em suplicante confissão:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 39:19\u003c/I>\u003c/FONT>\u003cbr/>\nFloréte, flores, quasi lílium, et date odórem, et frondéte in grátiam, collaudáte cánticum, et benedícite Dóminum in opéribus suis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 39:19\u003c/I>\u003c/FONT>\u003cbr/>\nFazei despontar a vossa flor, como um lírio; exalai o vosso perfume; lançai ramos graciosos; cantai hinos de louvor; e bendizei o Senhor nas suas obras.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSacratíssimæ Genetrícis tuæ, cujus Rosárium celebrámus, quǽsumus, Dómine, précibus adjuvémur: ut et mysteriórum, quæ cólimus, virtus percipiátur; et sacramentórum, quæ súmpsimus, obtineátur efféctus:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Marci Papæ Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta, quǽsumus, omnípotens Deus: ut, de percéptis munéribus grátias exhibéntes, intercedénte beáto N. Confessóre tuo atque Pontífice, benefícia potióra sumámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPossamos nós, Senhor, Vos rogamos, ser auxiliados pelas preces da vossa Santíssima Mãe, cujo Rosário celebramos, a fim de que obtenhamos as graças inerentes aos mystérios, que comemoramos, e o efeito dos sacramentos, que recebemos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Marci Papæ Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, Vos suplicamos, governai com mansidão a vossa Igreja, agora que foi alimentada com a sagrada refeição, a fim de que, dirigida com firme suavidade, alcance o incremento da sua liberdade e persista na integridade da sua doutrina.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-08":{"date":"2026-10-08","title":"Santa Brígida da Suécia, viúva","forms":[{"number":1,"title":"S. Birgittæ Viduæ Duplex vide Commune Unius non Virginis nec Martyris (Missa Cognovi) [Commune/C7a.txt]","winner":"Sancti/10-08.txt","rule":"vide C7a;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:75; 118:120\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:75; 118:120\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onheço, Senhor, que os vossos juízos são equitativos e que me humilhastes com justiça. Esmagai as minhas carnes com vosso temor; os vossos Mandamentos inspiram-me temor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles que são imaculados nos seus caminhos e cumprem a lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onheço, Senhor, que os vossos juízos são equitativos e que me humilhastes com justiça. Esmagai as minhas carnes com vosso temor; os vossos Mandamentos inspiram-me temor.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDómine, Deus noster, qui beátæ Birgíttæ per Fílium tuum unigénitum secreta cœléstia revelásti: ipsíus pia intercessióne da nobis, fámulis tuis; in revelatióne sempitérna glóriæ tuæ gaudére lætántes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Sergii, Bacchi, Marcelli et Apuleji Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anctórum Martyrum tuórum nos, Dómine, Sérgii, Bacchi, Marcélli et Apuléji beáta mérita prosequántur: et tuo semper fáciant amóre fervéntes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, nosso Deus, que pelo vosso Unigénito Filho revelastes os segredos celestiais à B. Brígida, concedei-nos, já que somos vossos servos, que nos alegremos na felicidade da contemplação da vossa eterna glória.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Ss. Sergii, Bacchi, Marcelli et Apuleji Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anctórum Martyrum tuórum nos, Dómine, Sérgii, Bacchi, Marcélli et Apuléji beáta mérita prosequántur: et tuo semper fáciant amóre fervéntes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Timótheum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Tim 5:3-10\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssime: Víduas honóra, quæ vere víduæ sunt. Si qua autem vídua fílios aut nepótes habet, discat primum domum suam régere, et mútuam vicem réddere paréntibus: hoc enim accéptum est coram Deo. Quæ autem vere vídua est et desoláta, speret in Deum, et instet obsecratiónibus et oratiónibus nocte ac die. Nam quæ in delíciis est, vivens mórtua est. Et hoc prǽcipe, ut irreprehensíbiles sint. Si quis autem suórum, et máxime domesticórum curam non habet, fidem negávit, et est infidéli detérior. Vídua eligátur non minus sexagínta annórum, quæ fúerit uníus viri uxor, in opéribus bonis testimónium habens, si fílios educávit, si hospítio recépit, si sanctórum pedes lavit, si tribulatiónem patiéntibus subministrávit, si omne opus bonum subsecúta est.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.º do B. Ap.º Paulo a Timóteo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Tm 5:3-10\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssimos: Honrai as, viúvas que são verdadeiramente viúvas. Se alguma viúva tem filhos ou netos, ensine-os, primeiramente, a governar a sua casa e a retribuir a seus pais conforme o que havia recebido deles; porque tal é a vontade de Deus. Aquela viúva, que é verdadeiramente viúva e vive só, espere em Deus e persevere noite e dia em suas súplicas e preces. Porém, aquela viúva que vive nas delícias, não está viva, mas sim morta. Fazei-lhes, pois, saber isto, a fim de que sejam irrepreensíveis. Se alguém se não interessa pelos seus, e principalmente pelos de sua casa, nega a fé e é pior do que um infiel. Que a viúva, que for escolhida, não tenha menos de sessenta anos, nem haja tido mais do que um marido, e que tenha reputação de ter praticado boas obras; que tenha educado os seus filhos; praticado a hospitalidade; lavado os pés aos santos; socorrido os aflitos; e, enfim, praticado toda a espécie de boas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:3; 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nDiffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nSpécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:3; 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nA graça espalhou-se nos vossos lábios: eis porque Deus vos abençoou para a eternidade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Por causa da vossa verdade, mansidão e justiça, a vossa dextra praticará maravilhas. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nCaminhai, pois, com beleza e com majestade; ide gozar a vitória e reinai. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 13:44-52\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 13:44-52\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos esta parábola: «O reino dos céus é semelhante a um tesouro escondido no campo, o qual um homem acha e esconde; e, alegre com o achado, vai, vende tudo o que tem e compra o campo. Igualmente o reino dos céus é semelhante a um negociante, que busca pedras preciosas; e, achando uma de grande preço, vai, vende tudo o que tem e compra-a. O reino dos céus é ainda semelhante a uma rede que, lançada ao mar, prende toda a casta de peixes, e, estando já cheia, os pescadores a puxam para a praia, escolhem os bons peixes para os vasos e deitam fora os maus. Assim será no fim dos séculos: virão os Anjos e separarão os maus do meio dos justos e os lançarão na fornalha do fogo, onde não haverá senão fogo e ranger de dentes. Haveis compreendido tudo isto?». «Sim», responderam eles. E Jesus disse-lhes: «Por esta razão todo o escriba douto no que diz respeito ao reino dos céus é semelhante a um pai de família, que tira dos seus tesouros cousas novas e velhas».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:3\u003c/I>\u003c/FONT>\u003cbr/>\nDiffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:3\u003c/I>\u003c/FONT>\u003cbr/>\nA graça espalhou-se nos vossos lábios: por isso Deus vos abençoou para a eternidade e para todos os séculos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAccépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Sergii, Bacchi, Marcelli et Apuleji Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>ajestátem tuam nobis, Dómine, quǽsumus, hæc hóstia reddat immolánda placátam, tuórum digna postulatióne Sanctórum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai, Senhor, esta oferta, que Vos consagra o vosso povo fiel em honra dos vossos santos, pelos méritos dos quais reconhece que tem alcançado a vossa assistência nas tribulações.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Ss. Sergii, Bacchi, Marcelli et Apuleji Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ermiti, Senhor, Vos suplicamos, que estejamos convenientemente preparados para Vos apresentar estas ofertas; e que pelos mystérios do SS. Rosário honremos de tal sorte a vida, a paixão e a glória do vosso Filho Unigénito que sejamos dignos das suas promessas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nDilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nAmastes a justiça e odiastes a iniquidade: eis porque o Senhor, vosso Deus, vos ungiu com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSatiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Sergii, Bacchi, Marcelli et Apuleji Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>acraméntis, Dómine, muniámur accéptis: et sanctórum Mártyrum tuórum Sérgii, Bacchi, Marcélli et Apuléji intercessióne, contra omnes nequítias irruéntes, annis cœléstibus protegámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo Vós, Senhor, saciado a vossa família com vossos dons sagrados, dignai-Vos favorecer-nos sempre com a intercessão daquela cuja festa celebrámos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Ss. Sergii, Bacchi, Marcelli et Apuleji Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>acraméntis, Dómine, muniámur accéptis: et sanctórum Mártyrum tuórum Sérgii, Bacchi, Marcélli et Apuléji intercessióne, contra omnes nequítias irruéntes, annis cœléstibus protegámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-09":{"date":"2026-10-09","title":"São João Leonardi, confessor","forms":[{"number":1,"title":"S. Joannis Leonardi Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/10-09.txt","rule":"vide C5;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 42:15-16.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n sermónibus Dómini ópera ejus: sol illúminans per ómnia respéxit, et glória Dómini plenum est opus ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 95:1\u003c/I>\u003c/FONT>\u003cbr/>\nCantáte Dómino cánticum novum: cantáte Dómino, omnis terra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n sermónibus Dómini ópera ejus: sol illúminans per ómnia respéxit, et glória Dómini plenum est opus ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 42:15-16\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elas palavras do Senhor existem as suas obras. Assim como o sol resplandecente ilumina todas as cousas, assim as suas obras estão cheias da glória do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 95:1\u003c/I>\u003c/FONT>\u003cbr/>\nCantai ao Senhor um cântico novo: cantai ao Senhor, ó habitantes de toda a terra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elas palavras do Senhor existem as suas obras. Assim como o sol resplandecente ilumina todas as cousas, assim as suas obras estão cheias da glória do Senhor.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum Joánnem Confessórem tuum ad fidem in géntibus propagándam mirabíliter excitáre dignátus es, ac per eum in erudiéndis fidélibus novam in Ecclésia tua famíliam congregásti: da nobis fámulis tuis; ita ejus institútis profícere, ut prǽmia consequámur ætérna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Dionysii Epíscopi, Rustici et Eleutherii Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui hodiérna die beátum Dionýsium, Mártyrem tuum atque Pontíficem, virtúte constantiæ in passióne roborásti, quique illi, ad prædicándum géntibus glóriam tuam, Rústicum et Eleuthérium sociáre dignátus es: tríbue nobis, quǽsumus; eórum imitatióne, pro amóre tuo próspera mundi despícere, et nulla ejus advérsa formidáre.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que pelo B. João, vosso Confessor, Vos dignastes animar de um modo admirável a propagação da fé entre os gentios, e por ele instituístes na vossa Igreja uma nova família para a instrução dos fiéis, concedei-nos a nós, vossos servos, que de tal maneira nos aproveitem os seus conselhos que alcancemos os prémios eternos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Dionísio e Outros, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que neste dia fortalecestes o B. Dionísio, vosso Mártir e Pontífice, com a virtude da constância no martírio e que Vos dignastes associar-lhe Rústico e Eleutério para pregarem a vossa glória aos povos, concedei-nos, Vos suplicamos, que, seguindo os seus exemplos, desprezemos por vosso amor as prosperidades do mundo e nunca temamos as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corinthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 4:1-6, 15-18\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Habéntes administratiónem juxta quod misericórdiam consecúti sumus, non defícimus, sed abdicámus occúlta dedécoris, non ambulántes in astútia, neque adulterántes verbum Dei, sed in manifestatióne veritátis commendántes nosmetípsos ad omnem consciéntiam hóminum coram Deo. Quod si étiam opértum est Evangélium nostrum: in iis, qui péreunt, est opértum: in quibus Deus hujus sǽculi excæcávit mentes infidélium, ut non fúlgeat illis illuminátio Evangélii glóriæ Christi, qui est imágo Dei. Non enim nosmetípsos prædicámus, sed Jesum Christum Dóminum nostrum: nos autem servos vestros per Jesum: quóniam Deus, qui dixit de ténebris lucem splendéscere, ipse illúxit in córdibus nostris ad illuminatiónem sciéntiæ claritátis Dei, in fácie Christi Jesu. Omnia enim propter vos: ut grátia abúndans, per multos in gratiárum actione, abúndet in glóriam Dei. Propter quod non deficimus: sed licet is, qui foris est, noster homo corrumpátur: tamen is, qui intus est, renovatur de die in diem. Id enim, quod in præsenti est momentáneum et leve tribulatiónis nostræ, supra modum in sublimitáte ætérnum glóriæ pondus operátur in nobis, non contemplántibus nobis quæ vidéntur, sed quæ non vidéntur. Quæ enim vidéntur, temporália sunt: quæ autem non vidéntur, ætérna sunt.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 4:1-6; 15-18\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Pelo que, tendo nós tal ministério em virtude da misericórdia que alcançámos, não perdemos a coragem, antes renunciámos a cousas que a vergonha manda ocultar, não nos conduzindo com artifício, nem adulterando a palavra de Deus, mas recomendando-nos à consciência de todos os homens diante de Deus, por meio da manifestação da verdade. E, se o nosso Evangelho ainda está oculto, é só para aqueles que se perdem: para aqueles infiéis a quem o deus deste mundo cegou os entendimentos, para que não resplandeça para eles a luz do Evangelho da glória de Cristo, o qual é a imagem de Deus. Nós não nos pregamos a nós mesmos, mas a Jesus Cristo, Nosso Senhor; nós, pois, vossos servos, por amor de Jesus; porque Deus, que quis que das trevas resplandecesse a luz, Ele mesmo resplandeceu nos nossos corações, para que fizéssemos brilhar o conhecimento da glória de Deus, que brilha na face de Jesus Cristo. Pois tudo isto aconteceu por amor de vós, a fim de que a graça, espalhando-se com abundância, faça também abundar a acção de graças, à glória de Deus, em muitos outros de entre vós. É por tudo isto que não desfalecemos; antes, pelo contrário, embora se destrua em nós o homem exterior, todavia o interior vai-se renovando de dia para dia; porque aquelas cousas que agora são para nós uma tribulação momentânea e ligeira produzirão um estado eterno de uma sublime e incomparável glória, não atendendo nós às cousas que se vêem, mas sim às que se não vêem, pois as cousas que se vêem são passageiras, e as que se não vêem são eternas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 72:21; 68:10\u003c/I>\u003c/FONT>\u003cbr/>\nInflammátum est cor meum, et renes mei commutáti sunt: zelus domus tuæ comédit me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Isa 49:2\u003c/I>\u003c/FONT>\u003cbr/>\nPósuit os meum quasi gládium acutum: in umbra manus suæ protéxit me, et pósuit me sicut sagíttam eléctam. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 70:7\u003c/I>\u003c/FONT>\u003cbr/>\nTamquam prodígium factus sum multis: et tu adjútor fortis, Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 72:21; 68:10\u003c/I>\u003c/FONT>\u003cbr/>\nInflamou-se o meu coração e comoveram-se as minhas entranhas: o zelo da tua casa devorou-me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Is 49:2\u003c/I>\u003c/FONT>\u003cbr/>\nO Senhor tornou a minha boca como uma espada aguda: protegeu-me com a sombra da sua mão: e fez de mim como que uma seta escolhida. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 70:7\u003c/I>\u003c/FONT>\u003cbr/>\nFui considerado por muitos corno um prodígio: tu és um poderoso auxiliar. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 10:1-9\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Designávit Dóminus et álios septuagínta duos: et misit illos binos ante fáciem suam in omnem civitátem et locum, quo erat ipse ventúrus. Et dicebat illis: Messis quidem multa, operárii autem pauci. Rogáte ergo Dóminum messis, ut mittat operários in messem suam. Ite: ecce, ego mitto vos sicut agnos inter lupos. Nolíte portáre sácculum neque peram neque calceaménta; et néminem per viam salutavéritis. In quamcúmque domum intravéritis, primum dícite: Pax huic dómui: et si ibi fúerit fílius pacis, requiéscet super illum pax vestra: sin autem, ad vos revertétur. In eádem autem domo manéte, edéntes et bibéntes quæ apud illos sunt: dignus est enim operárius mercéde sua. Nolíte transíre de domo in domum. Et in quamcúmque civitátem intravéritis, et suscéperint vos, manducáte quæ apponúntur vobis: et curáte infírmos, qui in illa sunt, et dícite illis: Appropinquávit in vos regnum Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 10:1-9\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, escolheu o Senhor ainda setenta e dois discípulos e mandou-os, dois a dois, adiante d’Ele, a todas as cidades e lugares onde devia ir, dizendo-lhes: «A messe é abundante, mas os operários são poucos; pedi, pois ao Senhor da messe que mande mais operários para a messe. Ide; eis que vos envio como cordeiros para o meio dos lobos; não leveis bolsa, nem saco, nem saudeis ninguém pelo caminho. Em qualquer casa em que entrardes, dizei em primeiro lugar: «A paz esteja nesta casa»! Se aí houver um filho da paz, a vossa paz repousará nele; e, se não um houver, voltará para vós. Permanecei na mesma casa e comei e bebei do que houver nessa casa, pois o operário merece salário. Não transiteis de casa para casa. Em qualquer casa em que entrardes e vos receberem comei do que vos derem, curai os enfermos que aí houver, e dizei-lhes: «Eis que se aproxima o reino de Deus».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 1:25\u003c/I>\u003c/FONT>\u003cbr/>\nChristi factus sum ego miníster secúndum dispensatiónem Dei, quæ data est mihi, ut ímpleam verbum Dómini.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 1:25\u003c/I>\u003c/FONT>\u003cbr/>\nEu fui constituído ministro de Cristo, segundo o cargo que Deus me deu junto de vós, para que se cumpra a palavra do Senhor.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSúscipe, Dómine, oblatiónem mundam salutáris hóstiæ: et præsta; ut, intercedénte beáto Joánne Confessóre tuo, úbique géntium júgiter offerátur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Dionysii Epíscopi, Rustici et Eleutherii Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>bláta tibi, Dómine, múnera pópuli tui, pro tuórum honóre Sanctórum, súscipe propítius, quǽsumus: et eórum nos intercessióne sanctífica.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nRecebei, Senhor, a oblação pura da hóstia salutar; e concedei-nos por intercessão do B. João, vosso Confessor, que ela seja oferecida constantemente em todos os povos da terra.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Dionísio e Outros, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei propício, Senhor, Vos rogamos, os dons que o vosso povo apresenta em honra dos vossos Santos; e pela sua intercessão santificai-nos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Phil 3:7\u003c/I>\u003c/FONT>\u003cbr/>\nQuæ mihi fuérunt lucra, hæc arbitrátus sum propter Christum detriménta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Fl 3:7\u003c/I>\u003c/FONT>\u003cbr/>\nAquelas cousas que reputava como lucro, considerei-as depois, por amor de Cristo, como prejudiciais.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPretiósi córporis, et sánguinis tui sacris refécti mystériis, Dómine, adprecámur: ut beáti Joánnis Confessóris tui exémplo, studeámus confitéri quod crédidit, et ópere exercére quod dócuit:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Dionysii Epíscopi, Rustici et Eleutherii Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>umptis, Dómine, sacraméntis, quǽsumus: ut, intercedéntibus beátis Martýribus tuis Dionýsio, Rústico et Eleuthério, ad redemptiónis ætérnæ proficiamus augméntum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nAlimentados, Senhor, com os sacrossantos mystérios do vosso precioso Corpo e Sangue, Vos rogamos instantemente que com o exemplo do B. João, vosso Confessor, procuremos confessar o que ele acreditou e praticar com nossas obras o que ele ensinou.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Dionísio e Outros, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>avendo nós recebido estes sacramentos, Senhor, Vos suplicamos, dignai-Vos permitir que por intercessão dos vossos B. B. Mártires Dionísio, Rústico e Eleutério cada vez mais avancemos no caminho da redenção eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-10":{"date":"2026-10-10","title":"São Francisco de Borja, confessor","forms":[{"number":1,"title":"S. Francisci Borgiæ Confessoris Semiduplex vide Commune Abbatum (Missa altera Os justi) [Commune/C5b.txt]","winner":"Sancti/10-10.txt","rule":"vide C5b;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDómine Jesu Christe, veræ humilitátis et exémplar et prǽmium: quǽsumus; ut, sicut beátum Francíscum in terréni honóris contémptu imitatórem tui gloriósum effecísti, ita nos eiúsdem imitatiónis et glóriæ tríbuas esse consórtes:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDómine Jesu Christe, veræ humilitátis et exémplar et prǽmium: quǽsumus; ut, sicut beátum Francíscum in terréni honóris contémptu imitatórem tui gloriósum effecísti, ita nos eiúsdem imitatiónis et glóriæ tríbuas esse consórtes:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 45:1-6\u003c/I>\u003c/FONT>\u003cbr/>\nDiléctus Deo et homínibus, cujus memória in benedictióne est. Símilem illum fecit in glória sanctórum, et magnificávit eum in timóre inimicórum, et in verbis suis monstra placávit. Glorificávit illum in conspéctu regum, et jussit illi coram pópulo suo, et osténdit illi glóriam suam. In fide et lenitáte ipsíus sanctum fecit illum, et elégit eum ex omni carne. Audívit enim eum et vocem ipsíus, et indúxit illum in nubem. Et dedit illi coram præcépta, et legem vitæ et disciplínæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 45:1-6\u003c/I>\u003c/FONT>\u003cbr/>\nFoi amado de Deus e dos homens; a sua memória é uma bênção. O Senhor deu-lhe uma glória, semelhante à dos Santos; tornou-o temeroso e invencível perante seus inimigos; e com suas palavras aplacou os monstros. O Senhor honrou-o diante dos reis; deu-lhe as suas ordens diante do seu povo; e mostrou-lhe a sua glória. O Senhor santificou-o pela sua fé e mansidão; e escolheu-o entre todos os homens. Deus escutou-o; ouviu a sua voz; e fê-lo entrar na nuvem. Então, deu-lhe face a face os seus preceitos e a lei da vida e da doutrina.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 20:4-5\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vitam pétiit a te, et tribuísti ei longitúdinem diérum in sǽculum sǽculi. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 20:4-5\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, concedestes-lhe bênçãos escolhidas as mais suaves; e impusestes na sua cabeça uma coroa de pedras preciosas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Concedestes-lhe a vida, que Vos suplicara, e prolongastes-lhe a duração dos seus dias pelos séculos dos séculos. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 19:27-29\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Petrus ad Jesum: Ecce, nos relíquimus ómnia, et secúti sumus te: quid ergo erit nobis? Jesus autem dixit illis: Amen, dico vobis, quod vos, qui secúti estis me, in regeneratióne, cum séderit Fílius hóminis in sede majestátis suæ, sedébitis et vos super sedes duódecim, judicántes duódecim tribus Israël. Et omnis, qui relíquerit domum, vel fratres, aut soróres, aut patrem, aut matrem, aut uxórem, aut fílios, aut agros, propter nomen meum, céntuplum accípiet, et vitam ætérnam possidébit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 19:27-29\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Pedro a Jesus: «Eis que deixámos tudo e Vos seguimos. Que recompensa teremos por isso?». Jesus disse-lhes: «Em verdade vos digo: vós, que me seguistes, quando, no tempo da regeneração, o Filho do homem se sentar no trono da sua glória, também vos sentareis sobre doze tronos para julgar as doze tribos de Israel. Todo aquele que deixar a sua casa, ou os seus irmãos, ou os seus campos, ou o seu pai, ou a sua mãe, ou a sua mulher por causa do meu nome receberá o cêntuplo e possuirá a vida eterna».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 20:3-4\u003c/I>\u003c/FONT>\u003cbr/>\nDesidérium ánimæ ejus tribuísti ei, Dómine, et voluntáte labiórum ejus non fraudásti eum: posuísti in cápite ejus corónam de lápide pretióso.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 20:3; 20:4\u003c/I>\u003c/FONT>\u003cbr/>\nConcedestes-lhe o desejo da sua alma e não desprezastes a prece dos seus lábios. Impusestes na sua cabeça uma coroa de pedras preciosas.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSacris altáribus, Dómine, hóstias superpósitas sanctus Francíscus, quǽsumus, in salútem nobis proveníre depóscat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nVos imploramos, Senhor, que o vosso santo B. Francisco nos alcance que a hóstia, oferecida no vosso altar, nos proporcione a salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nFidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nEis o servo fiel e prudente que o Senhor estabeleceu acima da sua família para distribuir, oportunamente, a cada um a sua medida de trigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPrótegat nos, Dómine, cum tui perceptióne sacraménti beátus Francíscus, pro nobis intercedéndo: ut et conversatiónis ejus experiámur insígnia, et intercessiónis percipiámus suffrágia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, unida às preces do B. Francisco, nos sirva de protecção, a fim de que, imitando os insignes exemplos da sua vida, sintamos os efeitos da sua intercessão.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-11":{"date":"2026-10-11","title":"XX Domingo depois de Pentecostes","forms":[{"number":1,"title":"Dominica XX Post Pentecosten II. Octobris\tSemiduplex","winner":"Tempora/Pent20-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dan 3:31; 31:29; 31:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>mnia, quæ fecísti nobis, Dómine, in vero judício fecísti, quia peccávimus tibi et mandátis tuis non obœdívimus: sed da glóriam nómini tuo, et fac nobíscum secúndum multitúdinem misericórdiæ tuæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>mnia, quæ fecísti nobis, Dómine, in vero judício fecísti, quia peccávimus tibi et mandátis tuis non obœdívimus: sed da glóriam nómini tuo, et fac nobíscum secúndum multitúdinem misericórdiæ tuæ.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dan 3:31; 3:29; 3:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>udo quanto fizestes contra nós, Senhor, foi com justiça, pois pecámos e não Obedecemos aos vossos mandamentos; mas glorificai o vosso nome e tratai-nos segundo a grandeza da vossa misericórdia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles cuja vida é imaculada: aqueles que praticam a Lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>udo quanto fizestes contra nós, Senhor, foi com justiça, pois pecámos e não Obedecemos aos vossos mandamentos; mas glorificai o vosso nome e tratai-nos segundo a grandeza da vossa misericórdia.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nLargíre, quǽsumus, Dómine, fidélibus tuis indulgéntiam placátus et pacem: ut páriter ab ómnibus mundéntur offénsis, et secúra tibi mente desérviant.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Maternitatis Beatæ Mariæ Virginis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui de beátæ Maríæ Vírginis útero Verbum tuum, Angelo nuntiánte, carnem suscípere voluísti: præsta supplícibus tuis; ut, qui vere eam Genitrícem Dei crédimus, ejus apud te intercessiónibus adjuvémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nCompadecei-Vos dos vossos fiéis, Senhor, e dignai-Vos conceder-lhes o perdão e a paz, a fim de que, havendo sido limpos de suas faltas, possam servir-Vos com toda a confiança.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Maternitatis Beatæ Mariæ Virginis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que segundo a anunciação do Anjo quisestes que o vosso Verbo assumisse a carne humana no seio da B. V. Maria, concedei-nos, Vos suplicamos, que, assim como acreditamos que ela é verdadeira Mãe de Deus, assim sejamos auxiliados na vossa presença com a intercessão das suas preces.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Ephésios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ephes 5:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Vidéte, quómodo caute ambulétis: non quasi insipiéntes, sed ut sapiéntes, rediméntes tempus, quóniam dies mali sunt. Proptérea nolíte fíeri imprudéntes, sed intellegéntes, quæ sit volúntas Dei. Et nolíte inebriári vino, in quo est luxúria: sed implémini Spíritu Sancto, loquéntes vobismetípsis in psalmis et hymnis et cánticis spirituálibus, cantántes et psalléntes in córdibus vestris Dómino: grátias agéntes semper pro ómnibus, in nómine Dómini nostri Jesu Christi, Deo et Patri. Subjecti ínvicem in timóre Christi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Efésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eph 5:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Tende cuidado de vos conduzirdes com prudência, não como insensatos, mas como prudentes, aproveitando o tempo, pois os dias são maus. Assim, pois, não sejais imprudentes, mas procurai conhecer qual é a vontade de Deus. Não bebais vinho com excesso, o que é luxúria. Enchei-vos do Espírito Santo, entretendo-vos uns aos outros com Salmos, Hinos, cânticos espirituais e outros cânticos e louvores, saídos do íntimo dos vossos corações, para glória do Senhor, dando graças sempre e em tudo a Deus Pai, em nome de Nosso Senhor Jesus Cristo, e submetendo-vos uns aos outros no temor de Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 144:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nOculi ómnium in te sperant, Dómine: et tu das illis escam in témpore opportúno. \u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Aperis tu manum tuam: et imples omne ánimal benedictióne. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 107:2\u003c/I>\u003c/FONT>\u003cbr/>\nParátum cor meum, Deus, parátum cor meum: cantábo, et psallam tibi, glória mea. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 144:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nTodos os olhares se volvem para Vós, Senhor; a todos os entes dais alimento em tempo conveniente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Abris as mãos e encheis de bênçãos tudo o que tem vida. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 107:2\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Meu coração está preparado, ó Deus; o meu coração está preparado: cantarei vossos louvores, ó Vós, que sois a minha glória. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joannes 4:46-53\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Erat quidam régulus, cujus fílius infirmabátur Caphárnaum. Hic cum audísset, quia Jesus adveníret a Judǽa in Galilǽam, ábiit ad eum, et rogábat eum, ut descénderet et sanáret fílium ejus: incipiébat enim mori. Dixit ergo Jesus ad eum: Nisi signa et prodígia vidéritis, non créditis. Dicit ad eum régulus: Dómine, descénde, priúsquam moriátur fílius meus. Dicit ei Jesus: Vade, fílius tuus vivit. Crédidit homo sermóni, quem dixit ei Jesus, et ibat. Jam autem eo descendénte, servi occurrérunt ei et nuntiavérunt, dicéntes, quia fílius ejus víveret. Interrogábat ergo horam ab eis, in qua mélius habúerit. Et dixérunt ei: Quia heri hora séptima relíquit eum febris. Cognóvit ergo pater, quia illa hora erat, in qua dixit ei Jesus: Fílius tuus vivit: et crédidit ipse et domus ejus tota.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 4:46-53\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, havia um oficial em Cafarnaum, cujo filho estava enfermo. Tendo ele sabido que Jesus vinha da Judeia para a Galileia, foi ter com Ele, rogando-Lhe que fosse a sua casa curar seu filho, que principiava a agonizar. Disse-lhe Jesus: «Se não vedes prodígios e milagres não acreditais!». Respondeu-Lhe o oficial: «Senhor, vinde, antes que meu filho morra». Jesus disse-lhe: «Vai; o teu filho vive!». Acreditou este homem na palavra de Jesus e partiu. Ia já no caminho, e eis que seus servos foram ao seu encontro, anunciando-lhe que o filho vivia! Então perguntou-lhes qual a hora em que se achara melhor o filho. Os servos responderam: «Ontem, à hora sétima, deixou-o a febre». E o pai reconheceu ter sido aquela a hora em que Jesus lhe dissera: «O teu filho vive». Ele, pois, assim como toda sua família, acreditou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 136:1\u003c/I>\u003c/FONT>\u003cbr/>\nSuper flúmina Babylónis illic sédimus et flévimus: dum recordarémur tui, Sion.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 136:1\u003c/I>\u003c/FONT>\u003cbr/>\nJunto das margens dos rios da Babilónia nos assentámos, chorando as recordações do vosso passado, ó Sião.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nCœléstem nobis prǽbeant hæc mystéria, quǽsumus, Dómine, medicínam: et vítia nostri cordis expúrgent.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Maternitatis Beatæ Mariæ Virginis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>ua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nQue estes mystérios, Senhor, nos sirvam de remédio celestial, Vos suplicamos, e purifiquem os nossos corações de todas nossas iniquidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Maternitatis Beatæ Mariæ Virginis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ela vossa misericórdia, Senhor, e pela intercessão da B. Maria, sempre Virgem, fazei que esta oferta nos assegure agora e sempre a prosperidade e a paz.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:49-50\u003c/I>\u003c/FONT>\u003cbr/>\nMeménto verbi tui servo tuo, Dómine, in quo mihi spem dedísti: hæc me consoláta est in humilitáte mea.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:49-50\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-Vos da vossa promessa ao vosso servo, Senhor, na qual tenho esperado com toda a confiança: é ela que me consola na minha humilhação.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nUt sacris, Dómine, reddámur digni munéribus: fac nos, qu&#509;sumus, tuis semper obœdíre mandátis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Maternitatis Beatæ Mariæ Virginis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>æc nos commúnio, Dómine, purget a crímine: et, intercedénte beáta Vírgine Dei Genetríce María, cœléstis remédii fáciat esse consórtes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, permiti que para sermos dignos dos vossos sacratíssimos mystérios obedeçamos sempre aos vossos mandamentos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Maternitatis Beatæ Mariæ Virginis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue esta comunhão, Senhor, nos purifique de nossos crimes e que por intercessão da B. V. Maria, Mãe de Deus, nos torne participantes do remédio celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-12":{"date":"2026-10-12","title":"Féria da 20ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Secunda infra Hebdomadam XX post Octavam Pentecostes II. Octobris\tFeria","winner":"Tempora/Pent20-1.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dan 3:31; 31:29; 31:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>mnia, quæ fecísti nobis, Dómine, in vero judício fecísti, quia peccávimus tibi et mandátis tuis non obœdívimus: sed da glóriam nómini tuo, et fac nobíscum secúndum multitúdinem misericórdiæ tuæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>mnia, quæ fecísti nobis, Dómine, in vero judício fecísti, quia peccávimus tibi et mandátis tuis non obœdívimus: sed da glóriam nómini tuo, et fac nobíscum secúndum multitúdinem misericórdiæ tuæ.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dan 3:31; 3:29; 3:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>udo quanto fizestes contra nós, Senhor, foi com justiça, pois pecámos e não Obedecemos aos vossos mandamentos; mas glorificai o vosso nome e tratai-nos segundo a grandeza da vossa misericórdia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles cuja vida é imaculada: aqueles que praticam a Lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>udo quanto fizestes contra nós, Senhor, foi com justiça, pois pecámos e não Obedecemos aos vossos mandamentos; mas glorificai o vosso nome e tratai-nos segundo a grandeza da vossa misericórdia.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nLargíre, quǽsumus, Dómine, fidélibus tuis indulgéntiam placátus et pacem: ut páriter ab ómnibus mundéntur offénsis, et secúra tibi mente desérviant.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nCompadecei-Vos dos vossos fiéis, Senhor, e dignai-Vos conceder-lhes o perdão e a paz, a fim de que, havendo sido limpos de suas faltas, possam servir-Vos com toda a confiança.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Ephésios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ephes 5:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Vidéte, quómodo caute ambulétis: non quasi insipiéntes, sed ut sapiéntes, rediméntes tempus, quóniam dies mali sunt. Proptérea nolíte fíeri imprudéntes, sed intellegéntes, quæ sit volúntas Dei. Et nolíte inebriári vino, in quo est luxúria: sed implémini Spíritu Sancto, loquéntes vobismetípsis in psalmis et hymnis et cánticis spirituálibus, cantántes et psalléntes in córdibus vestris Dómino: grátias agéntes semper pro ómnibus, in nómine Dómini nostri Jesu Christi, Deo et Patri. Subjecti ínvicem in timóre Christi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Efésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eph 5:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Tende cuidado de vos conduzirdes com prudência, não como insensatos, mas como prudentes, aproveitando o tempo, pois os dias são maus. Assim, pois, não sejais imprudentes, mas procurai conhecer qual é a vontade de Deus. Não bebais vinho com excesso, o que é luxúria. Enchei-vos do Espírito Santo, entretendo-vos uns aos outros com Salmos, Hinos, cânticos espirituais e outros cânticos e louvores, saídos do íntimo dos vossos corações, para glória do Senhor, dando graças sempre e em tudo a Deus Pai, em nome de Nosso Senhor Jesus Cristo, e submetendo-vos uns aos outros no temor de Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 144:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nOculi ómnium in te sperant, Dómine: et tu das illis escam in témpore opportúno. \u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Aperis tu manum tuam: et imples omne ánimal benedictióne. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 107:2\u003c/I>\u003c/FONT>\u003cbr/>\nParátum cor meum, Deus, parátum cor meum: cantábo, et psallam tibi, glória mea. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 144:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nTodos os olhares se volvem para Vós, Senhor; a todos os entes dais alimento em tempo conveniente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Abris as mãos e encheis de bênçãos tudo o que tem vida. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 107:2\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Meu coração está preparado, ó Deus; o meu coração está preparado: cantarei vossos louvores, ó Vós, que sois a minha glória. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joannes 4:46-53\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Erat quidam régulus, cujus fílius infirmabátur Caphárnaum. Hic cum audísset, quia Jesus adveníret a Judǽa in Galilǽam, ábiit ad eum, et rogábat eum, ut descénderet et sanáret fílium ejus: incipiébat enim mori. Dixit ergo Jesus ad eum: Nisi signa et prodígia vidéritis, non créditis. Dicit ad eum régulus: Dómine, descénde, priúsquam moriátur fílius meus. Dicit ei Jesus: Vade, fílius tuus vivit. Crédidit homo sermóni, quem dixit ei Jesus, et ibat. Jam autem eo descendénte, servi occurrérunt ei et nuntiavérunt, dicéntes, quia fílius ejus víveret. Interrogábat ergo horam ab eis, in qua mélius habúerit. Et dixérunt ei: Quia heri hora séptima relíquit eum febris. Cognóvit ergo pater, quia illa hora erat, in qua dixit ei Jesus: Fílius tuus vivit: et crédidit ipse et domus ejus tota.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 4:46-53\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, havia um oficial em Cafarnaum, cujo filho estava enfermo. Tendo ele sabido que Jesus vinha da Judeia para a Galileia, foi ter com Ele, rogando-Lhe que fosse a sua casa curar seu filho, que principiava a agonizar. Disse-lhe Jesus: «Se não vedes prodígios e milagres não acreditais!». Respondeu-Lhe o oficial: «Senhor, vinde, antes que meu filho morra». Jesus disse-lhe: «Vai; o teu filho vive!». Acreditou este homem na palavra de Jesus e partiu. Ia já no caminho, e eis que seus servos foram ao seu encontro, anunciando-lhe que o filho vivia! Então perguntou-lhes qual a hora em que se achara melhor o filho. Os servos responderam: «Ontem, à hora sétima, deixou-o a febre». E o pai reconheceu ter sido aquela a hora em que Jesus lhe dissera: «O teu filho vive». Ele, pois, assim como toda sua família, acreditou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 136:1\u003c/I>\u003c/FONT>\u003cbr/>\nSuper flúmina Babylónis illic sédimus et flévimus: dum recordarémur tui, Sion.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 136:1\u003c/I>\u003c/FONT>\u003cbr/>\nJunto das margens dos rios da Babilónia nos assentámos, chorando as recordações do vosso passado, ó Sião.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nCœléstem nobis prǽbeant hæc mystéria, quǽsumus, Dómine, medicínam: et vítia nostri cordis expúrgent.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nQue estes mystérios, Senhor, nos sirvam de remédio celestial, Vos suplicamos, e purifiquem os nossos corações de todas nossas iniquidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:49-50\u003c/I>\u003c/FONT>\u003cbr/>\nMeménto verbi tui servo tuo, Dómine, in quo mihi spem dedísti: hæc me consoláta est in humilitáte mea.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:49-50\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-Vos da vossa promessa ao vosso servo, Senhor, na qual tenho esperado com toda a confiança: é ela que me consola na minha humilhação.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nUt sacris, Dómine, reddámur digni munéribus: fac nos, qu&#509;sumus, tuis semper obœdíre mandátis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, permiti que para sermos dignos dos vossos sacratíssimos mystérios obedeçamos sempre aos vossos mandamentos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-13":{"date":"2026-10-13","title":"Santo Eduardo, rei, rei e confessor","forms":[{"number":1,"title":"S. Eduardi Regis Confessoris Semiduplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/10-13.txt","rule":"vide C5;mtv\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum regem Eduárdum Confessórem tuum æternitátis glória coronásti: fac nos, quǽsumus; ita eum venerári in terris, ut cum eo regnáre possímus in cœlis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que coroastes com a glória eterna o B. Rei Eduardo, vosso Confessor, fazei, Vos suplicamos, que o veneremos de tal modo na terra que com ele possamos reinar no céu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ecl 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o homem que foi julgado sem mácula; que não correu após o ouro; e não pôs as esperanças nem no dinheiro, nem nos tesouros! Quem é ele, para que o louvemos? Porquanto operou cousas admiráveis durante a vida. Aquele que foi provado pelo ouro e foi julgado perfeito alcançará a glória eterna; pois poderia ter violado o mandamento, e o não violou; poderia ter praticado acções más, e as não praticou. É por esta razão que seus bens lhe estarão assegurados no Senhor e que toda a assembleia dos justos proclamará as boas acções que praticou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ja 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nPara publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sabe sofrer a tentação, porque, quando acabar a tentação, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Estejam cingidos os vossos rins; tende nas vossas mãos lâmpadas acesas; sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para que, quando chegar e bater à porta, logo lha abram. Bem-aventurados aqueles servos que seu senhor, quando chegar, os achar vigilantes. Em verdade vos digo que se cingirá, e, mandando-os sentar à mesa, passará por entre eles e os servirá. E, se chegar na segunda ou terceira vigília e assim os achar, bem-aventurados são esses servos. Ora, sabei que, se o pai de família conhecesse a hora em que viria o ladrão, vigiava, sem dúvida, para que sua casa não fosse assaltada. Vós, pois, estai preparados, porque o Filho do homem virá à hora em que menos cuidais».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLaudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nA Vós, Senhor, imolamos esta víctimas de louvor em memória de vossos Santos, esperando ser livres por sua intercessão de todos os males presentes e futuros.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nRefécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPelos celestes alimentos recebidos, nós Vos rogamos e suplicamos, ó Senhor, nosso Deus, que nos seja concedido o auxílio das orações daquele Santo em cuja festa os recebemos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-14":{"date":"2026-10-14","title":"São Calisto I, papa e mártir","forms":[{"number":1,"title":"S. Callisti Papæ et Martyris Duplex vide Commune Unius Martyris Summi Pontificis (Missa Si diligis) [Commune/C2b.txt]","winner":"Sancti/10-14.txt","rule":"vide C2b;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 21:15-17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i díligis me, Simon Petre, pasce agnos meos, pasce oves meas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 29:2\u003c/I>\u003c/FONT>\u003cbr/>\nExaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i díligis me, Simon Petre, pasce agnos meos, pasce oves meas.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 21:15-17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e me amas, Simão-Pedro, apascenta os meus cordeiros, apascenta as minhas ovelhas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 29:2\u003c/I>\u003c/FONT>\u003cbr/>\nLouvar-Vos-ei, Senhor, pois me acolhestes e não permitistes que meus inimigos se rissem de mim.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e me amas, Simão-Pedro, apascenta os meus cordeiros, apascenta as minhas ovelhas.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui nos cónspicis ex nostra infirmitáte defícere: ad amórem tuum nos misericórditer per Sanctórum tuórum exémpla restáura.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que nos vedes desfalecer por causa da nossa fraqueza, dignai-Vos pela vossa misericórdia restaurar-nos no vosso amor, segundo os exemplos dos vossos Santos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Petri Apóstoli\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Pet 5:1-4; 5:10-11\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssimi: Senióres, qui in vobis sunt, obsécro consénior et testis Christi passiónum, qui et ejus, quæ in futúro revelánda est, glóriæ communicátor: páscite qui in vobis est gregem Dei, providéntes non coácte, sed spontánee secúndum Deum, neque turpis lucri grátia, sed voluntárie; neque ut dominántes in cleris, sed forma facti gregis ex ánimo. Et, cum apparúerit princeps pastórum, percipiétis immarcescíbilem glóriæ corónam. Deus autem omnis grátiæ, qui vocávit nos in ætérnam suam glóriam in Christo Jesu, módicum passos ipse perfíciet, confirmábit solidabítque. Ipsi glória et impérium in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Pedro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 P 5:1-4; 5:10-11\u003c/I>\u003c/FONT>\u003cbr/>\nAos sacerdotes que estão entre vós rogo eu, sacerdote como eles e testemunha dos sofrimentos de Cristo e que tomarei parte com eles naquela glória que será manifestada um dia: apascentai o rebanho de Deus que vos está confiado, cuidai dele não constrangidos, mas de boa vontade, segundo Deus; não por amor de lucro vil, mas por dedicação; não como para dominar sobre a herança \u003cFONT SIZE='1' COLOR=\"red\">do Senhor\u003c/FONT>, mas fazendo-vos modelos do rebanho. E quando aparecer o príncipe dos pastores, recebereis a coroa imarcescível da glória. Foi Deus de toda a graça que nos chamou em Jesus Cristo à sua eterna glória; e, depois de terdes sofrido um pouco, vos aperfeiçoará, fortificará e consolidará. A Ele: glória e império pelos séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 106:32; 106:31.\u003c/I>\u003c/FONT>\u003cbr/>\nExáltent eum in ecclésia plebis: et in cáthedra seniórum laudent eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Confiteántur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 106:32; 106:31\u003c/I>\u003c/FONT>\u003cbr/>\nQue seja exaltado na assembleia do povo; que seja louvado no conselho dos anciãos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glorifiquem o Senhor pelas suas misericórdias: e pelas suas maravilhas em favor dos filhos dos homens. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu és Pedro, e sobre esta pedra edificarei a minha Igreja. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 16:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 16:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, foi Jesus para a região de Cesareia, de Filipe, e interrogou os seus discípulos, dizendo-lhes: «Quem dizem os homens que é o Filho do homem?». Eles responderam: «Uns dizem que é João Baptista, outros que é Elias e outros que é Jeremias ou algum dos Profetas». Jesus disse-lhes: «E quem dizeis vós que eu sou?». Respondendo, Simão-Pedro disse: «Tu és Cristo, Filho de Deus vivo!». E Jesus disse-lhe: «Bem-aventurado és tu, Simão Barjona, porque não foi a carne nem o sangue que te revelaram o que dizes, mas meu Pai, que está nos céus. E Eu digo-te: tu és Pedro, e sobre esta pedra edificarei a minha Igreja; e as portas do inferno não prevalecerão contra ela. Eu te darei as chaves do reino dos céus; e tudo o que ligares sobre a terra será ligado também nos céus; e tudo o que desatares sobre a terra será desatado também nos céus».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 1:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nEcce, dedi verba mea in ore tuo: ecce, constítui te super gentes et super regna, ut evéllas et déstruas, et ædífices et plantes.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jr 1:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nEis que pus as minhas palavras na tua boca: eis que te constituí sobre os povos e sobre os reinos para arrancares e destruíres, e para edificares e plantares.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nMýstica nobis, Dómine, prosit oblátio: quæ nos et a reátibus nostris expédiat, et perpétua salvatióne confírmet.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nQue esta mística oblação nos aproveite, Senhor; e que nos livre das nossas faltas e nos assegure a salvação eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Apostolis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre: Te, Dómine, supplíciter exoráre, ut gregem tuum, Pastor ætérne, non déseras: sed per beátos Apóstolos tuos contínua protectióne custódias. Ut iísdem rectóribus gubernétur, quos óperis tui vicários eídem contulísti præésse pastóres. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Apóstolos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar suplicar-Vos humildemente, Senhor, que, como Pastor eterno, que sois, não abandoneis o vosso rebanho, mas antes, por intercessão dos vossos bem-aventurados Apóstolos, o guardeis sob a vossa perpétua protecção, a fim de que seja sempre governado pelos mesmos Directores, que, encarregados como Vigários de perpetuar a vossa obra, designastes seus Pastores. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos um hino à vossa glória, dizendo incessantemente:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu es Petrus, et super hanc petram ædificábo Ecclésiam meam.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu és Pedro, e sobre esta pedra edificarei a minha Igreja.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nQuǽsumus, omnípotens Deus: ut reátus nostros múnera sacráta puríficent, et recte vivéndi nobis operéntur efféctum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDignai-Vos permitir, ó Deus omnipotente, que estes dons nos purifiquem das nossas faltas e que, produzindo em nós os seus efeitos, nos façam viver santamente.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-15":{"date":"2026-10-15","title":"Santa Teresa de Jesus, virgem","forms":[{"number":1,"title":"S. Teresiæ Virginis Duplex vide Commune Unius Virginis tantum (Missa Dilexisti) [Commune/C6a.txt]","winner":"Sancti/10-15.txt","rule":"vide C6a;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:8\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:8\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>mastes a justiça e odiastes a iniquidade; pelo que ungiu-vos o Senhor, vosso Deus, com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: Consagro ao Rei as minhas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>mastes a justiça e odiastes a iniquidade; pelo que ungiu-vos o Senhor, vosso Deus, com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nExáudi nos, Deus, salutáris noster: ut sicut de beátæ Terésiæ Vírginis tuæ festivitáte gaudémus; ita cæléstis ejus doctrínæ pábulo nutriámur, et piæ devotiónis erudiámur afféctu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nOuvi-nos, ó Deus, nosso Salvador, a fim de que, assim como nos alegramos na festa da vossa B. Virgem Teresa, assim também sejamos sustentados com o pão da sua celestial doutrina e Consigamos alcançar os afectos da sua piedosa devoção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 10:17-18; 11:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Qui gloriátur, in Dómino gloriétur. Non enim, qui seípsum comméndat, ille probátus est; sed quem Deus comméndat. Utinam sustinerétis módicum quid insipiéntiæ meæ, sed et supportáte me: æmulor enim vos Dei æmulatióne. Despóndi enim vos uni viro vírginem castam exhibére Christo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 10:17-18; 11:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Aquele que se gloria, glorie-se no Senhor; pois não é aprovado o que se louva a si mesmo, mas aquele a quem Deus recomenda. Queira Deus que possais suportar um pouco ainda a minha loucura; mas suportai-me ainda, pois estou zeloso de vós da parte do zelo de Deus. Com efeito, desposei-vos com o único esposo, para vos apresentar a Cristo como virgem pura.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nSpécie tua et pulchritúdine tua inténde, próspere procéde et regna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nAdducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nCaminhai com beleza e com majestade; ide gozar a vitória e reinai.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Por causa da verdade, da mansidão e da justiça, a vossa dextra praticará maravilhas! Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nApós ela, serão apresentadas virgens ao Rei: as suas companheiras serão introduzidas no meio da alegria. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines íllæ, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos esta parábola: «O reino dos céus é semelhante a dez virgens que, empunhando suas lâmpadas, saíram ao encontro do esposo e da esposa. Porém, cinco destas virgens eram loucas e as outras cinco eram prudentes. Ora, as cinco loucas, empunhando suas lâmpadas, não levaram azeite. Ao contrário, as prudentes tomaram azeite em seus vasos para suas lâmpadas. Como o esposo se demorasse em chegar, tiveram sono e dormiram. Quando era meia-noite, ouviu-se um clamor dizer: «Eis que chega o esposo; ide ao seu encontro». Então todas estas virgens se ergueram e prepararam as suas lâmpadas. As loucas disseram às prudentes: «Dai-nos do vosso azeite, porque as nossas lâmpadas apagam-se». As prudentes responderam-lhes: «Não, porque pode suceder que, como a vós, nos falte o azeite; ide antes aos que o vendem, e comprai-o». Ora, enquanto elas foram comprar o azeite, veio o esposo. Então, as que estavam preparadas entraram com ele para as bodas; e fechou-se a porta. Por fim vieram as outras virgens, e disseram: «Senhor, senhor, abri-nos a porta». Ele respondeu: «Na verdade vos digo: não vos conheço. Vigiai, pois, visto que não sabeis nem o dia nem a hora».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:10\u003c/I>\u003c/FONT>\u003cbr/>\nFíliæ regum in honóre tuo, ástitit regína a dextris tuis in vestítu deauráto, circúmdata varietáte.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:10\u003c/I>\u003c/FONT>\u003cbr/>\nAs filhas dos reis formam a vossa corte de glória: a própria rainha está colocada à vossa direita, envergando um vestido de ouro, recamado da mais rica variedade.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAccépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai, Senhor, esta oferta, que Vos consagra o vosso povo fiel em honra dos vossos santos, pelos méritos dos quais reconhece que tem alcançado a vossa assistência nas tribulações.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:4-6\u003c/I>\u003c/FONT>\u003cbr/>\nQuinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:4; 25:6\u003c/I>\u003c/FONT>\u003cbr/>\nAs cinco virgens prudentes levaram azeite em seus vasos para suas lâmpadas. Ora, no meio da noite, ouviu-se este clamor: «Eis que chega o esposo; comparecei diante de Cristo, vosso Senhor».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSatiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo Vós, Senhor, saciado a vossa família com vossos dons sagrados, dignai-Vos favorecer-nos sempre com a intercessão daquela cuja festa celebrámos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-16":{"date":"2026-10-16","title":"Santa Edwiges, viúva","forms":[{"number":1,"title":"S. Hedwigis Viduæ Semiduplex vide Commune Unius non Virginis nec Martyris (Missa Cognovi) [Commune/C7a.txt]","winner":"Sancti/10-16.txt","rule":"vide C7a\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:75; 118:120\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:75; 118:120\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onheço, Senhor, que os vossos juízos são equitativos e que me humilhastes com justiça. Esmagai as minhas carnes com vosso temor; os vossos Mandamentos inspiram-me temor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles que são imaculados nos seus caminhos e cumprem a lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onheço, Senhor, que os vossos juízos são equitativos e que me humilhastes com justiça. Esmagai as minhas carnes com vosso temor; os vossos Mandamentos inspiram-me temor.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátam Hedwígem a sǽculi pompa ad húmilem tuæ Crucis sequélam toto corde transíre docuísti: concéde; ut ejus méritis et exémplo discámus peritúras mundi calcáre delícias, et in ampléxu tuæ Crucis ómnia nobis adversántia superáre:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que inspirastes a B. Hedviges a deixar as pompas do mundo para abraçar com fervor a humildade da vossa Cruz, concedei-nos pelos seus méritos e exemplos que aprendamos a esmagar as delícias caducas deste mundo e, abraçando a vossa Cruz, a vencer todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 31:10-31\u003c/I>\u003c/FONT>\u003cbr/>\nMulíerem fortem quis invéniet? Procul et de últimis fínibus prétium ejus. Confídit in ea cor viri sui, et spóliis non indigébit. Reddet ei bonum, et non malum, ómnibus diébus vitæ suæ. Quæsívit lanam et linum, et operáta est consílio mánuum suárum. Facta est quasi navis institóris, de longe portans panem suum. Et de nocte surréxit, dedítque prædam domésticis suis, et cibária ancíllis suis. Considerávit agrum, et emit eum: de fructu mánuum suárum plantávit víneam. Accínxit fortitúdine lumbos suos, et roborávit bráchium suum. Gustávit, et vidit, quia bona est negotiátio ejus: non exstinguétur in nocte lucérna ejus. Manum suam misit ad fórtia, et dígiti ejus apprehendérunt fusum. Manum suam apéruit ínopi, et palmas suas exténdit ad páuperem. Non timébit dómui suæ a frigóribus nivis: omnes enim doméstici ejus vestíti sunt duplícibus. Stragulátam vestem fecit sibi: byssus et púrpura induméntum ejus. Nóbilis in portis vir ejus, quando séderit cum senatóribus terræ. Síndonem fecit et véndidit, et cíngulum trádidit Chananǽo. Fortitúdo et decor induméntum ejus, et ridébit in die novíssimo. Os suum apéruit sapiéntiæ, et lex cleméntiæ in lingua ejus. Considerávit sémitas domus suæ, et panem otiósa non comédit. Surrexérunt fílii ejus, et beatíssimam prædicavérunt: vir ejus, et laudávit eam. Multæ fíliæ congregavérunt divítias: tu supergréssa es univérsas. Fallax grátia, et vana est pulchritúdo: múlier timens Dóminum, ipsa laudábitur. Date ei de fructu mánuum suárum: et laudent eam in portis ópera ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Pr 31:10-31\u003c/I>\u003c/FONT>\u003cbr/>\nQuem encontrará uma mulher forte? Seu valor é maior do que o das pérolas que vêm dos confins do mundo. Nela confia o coração do marido, que por isso lhe não faltará proveito. Ela procurará praticar o bem, e não o mal, em todos os dias da sua vida. Ela procurará a lã e o linho, e, diligentemente, trabalhará neles com suas mãos. Ela é como um navio de mercador que traz de longe o seu pão! Levanta-se quando ainda é noite, e dá alimento à família e trabalho aos servos. Ela pensa em um campo, compra-o e planta uma vinha com o trabalho de suas mãos. Cinge com vigor os seus rins e esforça os seus braços. Examina e vê que seu negócio é bom e que sua lâmpada se não apagará durante a noite. Emprega suas mãos em trabalhos rudes e seus dedos no fuso. Estende a sua mão ao indigente e o seu braço ao pobre. Não receia na sua casa nem o frio, nem a neve, porque todos os criados têm roupa em duplo. Fabrica para si tapeçarias e faz os seus vestidos de bom linho e de púrpura. Seu marido será enobrecido, quando se sentar às Portas da cidade com os senadores da terra. Faz vestidos, que vende, e cintas, que entrega aos mercadores. Revestiu-se de coragem e de glória, e, alegre, aguarda o futuro. Fala com sabedoria e a sua língua é clemente. Vigia os caminhos de sua casa e não come o pão na ociosidade. Erguem-se seus filhos e a proclamam bem-aventurada, e seu marido a louva também: «Muitas filhas reuniram virtudes, mas tu excedeste-las». Enganadora é a graça e vã é a formosura. Só a mulher, que teme o Senhor, será louvada. Dai-lhe o produto de suas mãos, e que a louvem às portas da cidade, por causa das suas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:3; 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nDiffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nSpécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:3; 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nA graça espalhou-se nos vossos lábios: eis porque Deus vos abençoou para a eternidade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Por causa da vossa verdade, mansidão e justiça, a vossa dextra praticará maravilhas. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nCaminhai, pois, com beleza e com majestade; ide gozar a vitória e reinai. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 13:44-52\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 13:44-52\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos esta parábola: «O reino dos céus é semelhante a um tesouro escondido no campo, o qual um homem acha e esconde; e, alegre com o achado, vai, vende tudo o que tem e compra o campo. Igualmente o reino dos céus é semelhante a um negociante, que busca pedras preciosas; e, achando uma de grande preço, vai, vende tudo o que tem e compra-a. O reino dos céus é ainda semelhante a uma rede que, lançada ao mar, prende toda a casta de peixes, e, estando já cheia, os pescadores a puxam para a praia, escolhem os bons peixes para os vasos e deitam fora os maus. Assim será no fim dos séculos: virão os Anjos e separarão os maus do meio dos justos e os lançarão na fornalha do fogo, onde não haverá senão fogo e ranger de dentes. Haveis compreendido tudo isto?». «Sim», responderam eles. E Jesus disse-lhes: «Por esta razão todo o escriba douto no que diz respeito ao reino dos céus é semelhante a um pai de família, que tira dos seus tesouros cousas novas e velhas».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:3\u003c/I>\u003c/FONT>\u003cbr/>\nDiffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:3\u003c/I>\u003c/FONT>\u003cbr/>\nA graça espalhou-se nos vossos lábios: por isso Deus vos abençoou para a eternidade e para todos os séculos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAccépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai, Senhor, esta oferta, que Vos consagra o vosso povo fiel em honra dos vossos santos, pelos méritos dos quais reconhece que tem alcançado a vossa assistência nas tribulações.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nDilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nAmastes a justiça e odiastes a iniquidade: eis porque o Senhor, vosso Deus, vos ungiu com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSatiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo Vós, Senhor, saciado a vossa família com vossos dons sagrados, dignai-Vos favorecer-nos sempre com a intercessão daquela cuja festa celebrámos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-17":{"date":"2026-10-17","title":"Santa Margarida Maria Alacoque, virgem","forms":[{"number":1,"title":"S. Margaritæ Mariæ Alaquoque Virginis Duplex vide Commune Unius Virginis tantum (Missa Dilexisti) [Commune/C6a.txt]","winner":"Sancti/10-17.txt","rule":"vide C6a\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cant 2:3.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ub umbra illíus, quem desideráveram, sedi: et fructus ejus dulcis gútturi meo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nQuam dilécta tabernácula tua, Dómine virtútum! Concupíscit, et déficit ánima mea in átria Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ub umbra illíus, quem desideráveram, sedi: et fructus ejus dulcis gútturi meo.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ct 2:3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ssentei-me à sombra daquele que eu desejara: e o seu fruto é doce ao meu paladar.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nComo são amáveis os vossos tabernáculos, ó Senhor dos exércitos! Minha alma suspira ardentemente pelos átrios do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ssentei-me à sombra daquele que eu desejara: e o seu fruto é doce ao meu paladar.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDómine Jesu Christe, qui investigábiles divítias Cordis tui beátæ Margarítæ Maríæ Vírgini mirabíliter revelásti: da nobis ejus méritis et imitatióne; ut, te in ómnibus et super ómnia diligéntes, jugem in eódem Corde tuo mansiónem habére mereámur:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor Jesus Cristo, que de uma maneira admirável Vos dignastes revelar à B. Virgem Margarida Maria as insondáveis riquezas do vosso Coração, concedei-nos pelos seus méritos e à sua imitação que, amando-Vos em tudo e acima de tudo, possamos ter uma mansão no vosso Coração.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Ephésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ephes 3:8-9; 14-19.\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Mihi ómnium sanctórum mínimo data est grátia hæc, in géntibus evangelizáre investigábiles divítias Christi, et illumináre omnes, quæ sit dispensátio sacraménti abscónditi a sǽculis in Deo, qui ómnia creávit. Hujus rei grátia flecto génua mea ad Patrem Dómini nostri Jesu Christi, ex quo omnis patérnitas in cælis et in terra nominátur, ut det vobis secúndum divítias glóriæ suæ, virtúte corroborári per Spíritum ejus in interiórem hóminem: Christum habitáre per fidem in córdibus vestris: in caritáte radicáti et fundáti, ut póssitis comprehéndere cum ómnibus sanctis, quæ sit latitúdo et longitúdo et sublímitas et profúndum: scire étiam supereminéntem sciéntiæ caritátem Christi, ut impleámini in omnem plenitúdinem Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap. Paulo aos Efésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ef 3:8-9; 14-19\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Fui eu, que sou o mínimo de todos os santos, quem recebeu esta graça de anunciar aos povos as riquezas incompreensíveis de Jesus Cristo e de esclarecer todos os homens, revelando-lhes a economia do mystério, que desde tantos séculos está oculto em Deus, criador de todas as cousas, a fim de que, por meio da Igreja, os potentados e as potestades nos céus conheçam a sabedoria infinitamente variada de Deus, segundo o desígnio eterno que Ele realizou por Jesus Cristo, Nosso Senhor, em quem, pela fé que n’Ele depositamos, temos a franca segurança de nos aproximarmos de Deus com confiança. Por este motivo ajoelho diante do Pai de Nosso Senhor Jesus Cristo, que é o princípio desta grande família no céu e na terra, para que, segundo as riquezas da sua glória, sejais fortificados pelo seu Espírito e revestidos com a graça de homens interiores. Permita Ele que Jesus Cristo habite pela fé nos vossos corações, de modo que, enraizados e imbuídos na caridade, possais compreender com todos os santos a largura, o comprimento, a altura e a profundidade deste mystério e conhecer o amor de Jesus Cristo, o qual ultrapassa toda a ciência; e, assim, fiqueis repletos de plenitude dos dons de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cant 8:7.\u003c/I>\u003c/FONT>\u003cbr/>\nAquæ multæ non potuérunt exstínguere caritátem, nec flúmina óbruent illam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 72:26\u003c/I>\u003c/FONT>\u003cbr/>\nDefécit caro mea et cor meum: Deus cordis mei, et pars mea Deus in ætérnum. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cant 7:10.\u003c/I>\u003c/FONT>\u003cbr/>\nEgo dilécto meo, et ad me conversio ejus. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ct 8:7\u003c/I>\u003c/FONT>\u003cbr/>\nAs águas caudalosas não puderam extinguir a caridade, nem os rios a submergiram.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 72:26\u003c/I>\u003c/FONT>\u003cbr/>\nMeu corpo e o meu coração desfaleceram, ó Deus, que sois o Deus do meu coração e a minha herança na eternidade! Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ct 7:10\u003c/I>\u003c/FONT>\u003cbr/>\nEu sou para o meu muito amado! E Ele volveu-se para mim. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 11:25-30\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Respóndens Jesus, dixit: Confíteor tibi, Pater, Dómine cæli et terræ, quia abscondísti hæc a sapiéntibus et prudéntibus, et revelásti ea párvulis. Ita, Pater: quóniam sic fuit plácitum ante te. Omnia mihi trádita sunt a Patre meo. Et nemo novit Fílium nisi Pater: neque Patrem quis novit nisi Fílius, et cui volúerit Fílius reveláre. Veníte ad me, omnes, qui laborátis et oneráti estis, et ego refíciam vos. Tóllite jugum meum super vos, et discite a me, quia mitis sum et húmilis corde: et inveniétis réquiem animábus vestris. Jugum enim meum suave est et onus meum leve.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 11:25-30\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, respondendo Jesus, disse: «Dou-Vos graças, ó Pai, Senhor do céu e da terra, pois que ocultastes estas coisas aos sábios e aos prudentes e as revelastes aos pequenos. Sim, ó Pai, dou-Vos graças, porque assim o quisestes. Todas as cousas me foram dadas pelo meu Pai; e ninguém conhece o Filho senão o Pai, assim como ninguém conhece o Pai senão o Filho, e aquele a quem o Filho o quer revelar. Vinde a mim, vós todos, que trabalhais e estais sobrecarregados, e vos confortarei. Tomai sobre vós o meu jugo e aprendei de mim; pois sou manso e humilde de coração; e achareis o repouso para as vossas almas. Meu jugo é suave e o meu ónus é leve».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Zach 9:17\u003c/I>\u003c/FONT>\u003cbr/>\nQuid bonum ejus est et quid pulchrum ejus, nisi fruméntum electórum et vinum gérminans vírgines?\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Zc 9:17\u003c/I>\u003c/FONT>\u003cbr/>\nQue possui o Senhor de bom e de belo, melhor do que o trigo dos eleitos e o vinho que gera as virgens?\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAccépta tibi sint, Dómine, plebis tuæ múnera: et concéde; ut ignis ille divínus nos inflámmet, quo de Corde Fílii tui emisso beáta Margaríta María veheménter æstuávit.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos aceitar, Senhor, as ofertas do vosso povo e permiti que sejamos inflamados no fogo divino que, irradiando do Coração do vosso Filho, consumiu em seu ardor a B. Margarida Maria.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cant 6:2\u003c/I>\u003c/FONT>\u003cbr/>\nEgo dilécto meo, et diléctus meus mihi, qui páscitur inter lília.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ct 6:2\u003c/I>\u003c/FONT>\u003cbr/>\nEu sou do meu muito amado e o meu muito amado é meu, pois Ele apascenta-se entre os lírios.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nCórporis et Sánguinis tui, Dómine Jesu, sumptis mystériis: concéde nobis, quǽsumus, beáta Margaríta María Vírgine intercedénte; ut, supérbis sǽculi vanitátibus exútis, mansuetúdinem et humilitátem Cordis tui indúere mereámur:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor Jesus, havendo participado dos mystérios do vosso Corpo e Sangue, Vos rogamos, concedei-nos pela intercessão da B. Margarida Maria, Virgem, que, despojando-nos das vaidades do mundo, mereçamos ser revestidos com a mansidão e com a humildade do vosso Coração.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-18":{"date":"2026-10-18","title":"XXI Domingo depois de Pentecostes","forms":[{"number":1,"title":"Dominica XXI Post Pentecosten IV. Octobris\tSemiduplex","winner":"Tempora/Pent21-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 13:9; 13:10-11\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n voluntáte tua, Dómine, univérsa sunt pósita, et non est, qui possit resístere voluntáti tuæ: tu enim fecísti ómnia, cœlum et terram et univérsa, quæ cœli ámbitu continéntur: Dominus universórum tu es\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n voluntáte tua, Dómine, univérsa sunt pósita, et non est, qui possit resístere voluntáti tuæ: tu enim fecísti ómnia, cœlum et terram et univérsa, quæ cœli ámbitu continéntur: Dominus universórum tu es.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 13:9-11\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odas as cousas, Senhor, estão sujeitas à vossa vontade, e ninguém pode resistir-lhe; pois criastes tudo: o céu, a terra e o que se encerra no âmbito dos céus. Sois o Senhor do universo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles cuja vida é imaculada: aqueles que praticam a Lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odas as cousas, Senhor, estão sujeitas à vossa vontade, e ninguém pode resistir-lhe; pois criastes tudo: o céu, a terra e o que se encerra no âmbito dos céus. Sois o Senhor do universo.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nFamíliam tuam, quǽsumus, Dómine, contínua pietáte custódi: ut a cunctis adversitátibus, te protegénte, sit líbera, et in bonis áctibus tuo nómini sit devóta.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Lucæ Evangelistæ\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>ntervéniat pro nobis, quǽsumus, Dómine, sanctus tuus Lucas Evangélista: qui crucis mortificatiónem júgiter in suo córpore, pro tui nóminis honóre, portávit.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nGuardai com vossa contínua misericórdia a vossa família, Senhor, Vos suplicamos, a fim de que sob a vossa protecção seja preservada de todas as adversidades e se dedique à prática das boas obras, em honra do vosso nome.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Lucae Evangelistae\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, Vos rogamos, permiti que o vosso Santo Evangelista Lucas, que, para glória do vosso nome, sempre praticou em seu corpo a mortificação da Cruz, interceda por nós.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLectio Epistolæ beáti Pauli Apóstoli ad Ephésios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ephes 6:10-17\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Confortámini in Dómino et in poténtia virtútis ejus. Indúite vos armatúram Dei, ut póssitis stare advérsus insídias diáboli. Quóniam non est nobis colluctátio advérsus carnem et sánguinem: sed advérsus príncipes et potestátes, advérsus mundi rectóres tenebrárum harum, contra spirituália nequítiæ, in cœléstibus. Proptérea accípite armatúram Dei, ut póssitis resístere in die malo et in ómnibus perfécti stare. State ergo succíncti lumbos vestros in veritáte, et indúti lorícam justítiæ, et calceáti pedes in præparatióne Evangélii pacis: in ómnibus suméntes scutum fídei, in quo póssitis ómnia tela nequíssimi ígnea exstínguere: et gáleam salútis assúmite: et gládium spíritus, quod est verbum Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Efésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eph 6:10-17\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Confortai-vos no Senhor e no seu poder omnipotente. Revesti-vos de todas armas de Deus, a fim de que possais suportar as ciladas do demónio; pois temos de combater, não só contra a carne e o sangue, mas também contra os príncipes e as potestades do inferno, contra os dominadores deste mundo de trevas e contra os espíritos malignos, espalhados nas regiões do ar. Tomai, então, as armas de Deus, a fim de que, estando preparados para tudo, possais resistir no dia mau e ficar de pé e perfeitos em todas as cousas. Sede firmes, pois! Que a verdade seja o cinto dos vossos rins, e a justiça a vossa couraça. Calçai vossos pés para vos preparardes para seguir o Evangelho da paz. Empunhai sempre o escudo da fé, para poderdes quebrar os dardos inflamados do espírito maligno. Revesti-vos, também, com o capacete da salvação e com a espada espiritual, que é a palavra de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 89:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, refúgium factus es nobis, a generatióne et progénie.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Priúsquam montes fíerent aut formarétur terra et orbis: a sǽculo et usque in sǽculum tu es, Deus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 113:1\u003c/I>\u003c/FONT>\u003cbr/>\nIn éxitu Israël de Ægýpto, domus Jacob de pópulo bárbaro. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 89:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nTendes sido, Senhor, o nosso refúgio de geração em geração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Antes que as montanhas houvessem sido formadas e que a terra e o mundo tivessem sido criados, já, desde toda a eternidade, Vós éreis Deus. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 113:1\u003c/I>\u003c/FONT>\u003cbr/>\nQuando Israel saiu do Egipto e a casa de Jacob do meio de um povo bárbaro. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 18:23-35\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Assimilátum est regnum cœlórum hómini regi, qui vóluit ratiónem pónere cum servis suis. Et cum cœpísset ratiónem pónere, oblátus est ei unus, qui debébat ei decem mília talénta. Cum autem non habéret, unde rédderet, jussit eum dóminus ejus venúmdari et uxórem ejus et fílios et ómnia, quæ habébat, et reddi. Prócidens autem servus ille, orábat eum, dicens: Patiéntiam habe in me, et ómnia reddam tibi. Misértus autem dóminus servi illíus, dimísit eum et débitum dimísit ei. Egréssus autem servus ille, invénit unum de consérvis suis, qui debébat ei centum denários: et tenens suffocábat eum, dicens: Redde, quod debes. Et prócidens consérvus ejus, rogábat eum, dicens: Patiéntiam habe in me, et ómnia reddam tibi. Ille autem nóluit: sed ábiit, et misit eum in cárcerem, donec rédderet débitum. Vidéntes autem consérvi ejus, quæ fiébant, contristáti sunt valde: et venérunt et narravérunt dómino suo ómnia, quæ facta fúerant. Tunc vocávit illum dóminus suus: et ait illi: Serve nequam, omne débitum dimísi tibi, quóniam rogásti me: nonne ergo opórtuit et te miseréri consérvi tui, sicut et ego tui misértus sum? Et irátus dóminus ejus, trádidit eum tortóribus, quoadúsque rédderet univérsum débitum. Sic et Pater meus cœléstis fáciet vobis, si non remiséritis unusquísque fratri suo de córdibus vestris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 18:23-35\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, Jesus disse aos seus discípulos esta parábola: O reino dos céus é semelhante a um rei que quis fazer contas com seus servos. Logo que começou as contas, apresentou-se um servo que lhe devia dez mil talentos. Ora, como este não tinha com que pagar, mandou o senhor que o vendessem, assim como sua mulher, filhos e tudo quanto possuía, para liquidar a dívida. Então este servo, prostrando-se aos pés do rei, pedia-lhe: «Tende paciência para comigo, e pagarei tudo». E o senhor compadeceu-se do servo, deixou-o ir embora e perdoou-lhe a dívida. Apenas o servo saiu, encontrou ele um seu companheiro, que lhe devia cem dinheiros. Logo, agarrou-o até quase o sufocar e disse-lhe: «Paga-me o que me deves». O companheiro prostrou-se a seus pés, suplicando-lhe nestes termos: «Tende paciência para comigo, e pagarei tudo». Mas não quis atendê-lo. Foi dali e mandou metê-lo na cadeia, até que lhe pagasse a dívida. Vendo os outros servos, seus companheiros, o que acontecera, ficaram profundamente tristes, indo narrar tudo ao senhor. Então o senhor mandou chamar o servo e disse-lhe: «Perdoei-te toda tua dívida, porque assim me rogaste; portanto não devias tu, também, ter piedade do teu companheiro, como tive de ti?». Imediatamente se encolerizou o senhor, entregando-o aos algozes da justiça, até que lhe pagasse a sua dívida. Pois bem, terminou Jesus, assim vos tratará meu Pai celeste se cada um não perdoar do íntimo do coração a sua dívida ao seu irmão.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Job 1.1\u003c/I>\u003c/FONT>\u003cbr/>\nVir erat in terra Hus, nómine Job: simplex et rectus ac timens Deum: quem Satan pétiit ut tentáret: et data est ei potéstas a Dómino in facultátes et in carnem ejus: perdidítque omnem substántiam ipsíus et fílios: carnem quoque ejus gravi úlcere vulnerávit.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jb 1.1\u003c/I>\u003c/FONT>\u003cbr/>\nVivia no país de Hus um homem chamado Job, que era simples, justo e temente a Deus. Então Satanás pediu licença ao Senhor para o tentar, o que lhe foi permitido, mas somente quanto aos bens e ao corpo: e Satanás fez-lhe perder todos os bens e os filhos, e ainda lhe afligiu o corpo com uma chaga.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSuscipe, Dómine, propítius hóstias: quibus et te placári voluísti, et nobis salútem poténti pietáte restítui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Lucæ Evangelistæ\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>onis cœléstibus da nobis, quǽsumus, Dómine, líbera tibi mente servíre: ut múnera quæ deférimus, interveniénte beáto Evangelísta tuo Luca, et medélam nobis operéntur et glóriam.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai propício, Senhor, estas hóstias com as quais quisestes aplacar-Vos, e, pela vossa infinita bondade, concedei-nos a salvação.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Lucae Evangelistae\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ela virtude destes dons celestiais, Vos suplicamos, Senhor, concedei-nos a graça de Vos servirmos com inteira liberdade de espírito, a fim de que os dons, que Vos apresentamos, nos alcancem, por intercessão do B. Evangelista Lucas, o remédio para os nossos males e a glória eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:81; 118:84; 118:86\u003c/I>\u003c/FONT>\u003cbr/>\nIn salutári tuo ánima mea, et in verbum tuum sperávi: quando fácies de persequéntibus me judícium? iníqui persecúti sunt me, ádjuva me, Dómine, Deus meus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:81; 118:84; 118:86\u003c/I>\u003c/FONT>\u003cbr/>\nA minha alma suspira pela salvação: e pus toda minha esperança na vossa palavra. Quando tratareis com justiça os meus perseguidores? Homens injustos perseguem-me; auxiliai-me, Senhor!\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nImmortalitátis alimóniam consecúti, quǽsumus, Dómine: ut, quod ore percépimus, pura mente sectémur.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Lucæ Evangelistæ\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta, quǽsumus, omnípotens Deus: ut, quod de sancto altári tuo accépimus, précibus beáti Evangelístæ tui Lucæ, sanctíficet ánimas nostras, per quod tuti esse possímus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido o alimento da imortalidade, permiti, Senhor, Vos suplicamos, que guardemos com o coração puro aquilo que a nossa boca recebeu.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Lucae Evangelistae\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> omnipotente Deus, Vos rogamos, fazei que o dom, agora recebido no sagrado altar, santifique, pelas preces do vosso B. Evangelista Lucas, as nossas almas, a fim de que nos defenda dos perigos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-19":{"date":"2026-10-19","title":"São Pedro de Alcântara, confessor","forms":[{"number":1,"title":"S. Petri de Alcantara Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Justus) [Commune/C5-1.txt]","winner":"Sancti/10-19.txt","rule":"vide C5-1;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13-14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>J\u003c/I>\u003c/B>\u003c/FONT>ustus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nBonum est confitéri Dómino: et psállere nómini tuo, Altíssime.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>J\u003c/I>\u003c/B>\u003c/FONT>ustus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13-14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT> justo florescerá, como a palmeira, e multiplicar-se-á, como o cedro do Líbano, plantado na casa do Senhor e nos átrios da casa do nosso Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nÉ bom louvar o Senhor: e cantar hinos em honra do vosso nome, ó Altíssimo!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT> justo florescerá, como a palmeira, e multiplicar-se-á, como o cedro do Líbano, plantado na casa do Senhor e nos átrios da casa do nosso Deus.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum Petrum Confessórem tuum admirábilis pœniténtiæ et altíssimæ contemplatiónis múnere illustráre dignátus es: da nobis, quǽsumus; ut, ejus suffragántibus méritis, carne mortificáti, facílius cœléstia capiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que Vos dignastes ilustrar o B. Pedro, Confessor, com os dons de uma penitência e de uma contemplação sublimes, permiti, Vos suplicamos, que, auxiliados com seus méritos e intercessão e mortificando o nosso corpo, obtenhamos mais facilmente os bens celestiais.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Philippénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Philipp 3:7-12\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Quæ mihi fuérunt lucra, hæc arbitrátus sum propter Christum defriménta. Verúmtamen exístimo ómnia detriméntum esse propter eminéntem sciéntiam Jesu Christi, Dómini mei: propter quem ómnia detriméntum feci et árbitror ut stércora, ut Christum lucrifáciam et invéniar in illo, non habens meam justítiam, quæ ex lege est, sed illam, quæ ex fide est Christi Jesu: quæ ex Deo est justítia in fide, ad cognoscéndum illum, et virtútem resurrectiónis ejus, et societátem passiónum illíus: configurátus morti ejus: si quo modo occúrram ad resurrectiónem, quæ est ex mórtuis: non quod jam accéperim aut jam perféctus sim: sequor autem, si quo modo comprehéndam, in quo et comprehénsus sum a Christo Jesu.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Filipenses.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Fl 3:7-12\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: As cousas que considerava ganho tive-as depois como perda, meditando em Cristo. E, na verdade, considero tudo como perda, pelo melhor conhecimento que tenho de Jesus Cristo, meu Senhor, por amor de quem renunciei a todas as cousas, considerando-as como poeira, a fim de que ganhe a Cristo e me encontre com Ele, não com a minha própria justiça \u003cFONT SIZE='1' COLOR=\"red\">a que vem da Lei\u003c/FONT>, mas com aquela que nasce da fé em Jesus Cristo \u003cFONT SIZE='1' COLOR=\"red\">a justiça que vem de Deus pela fé\u003c/FONT>, para que o conheça a Ele, assim como ao mystério da sua Ressurreição, e tome parte nos seus sofrimentos, havendo-me confortado com sua morte, a fim de que possa de algum modo conseguir a ressurreição dos mortos. Não que eu a tenha alcançado, isto é, me haja tornado já perfeito; mas prossigo o caminho para ver se alcanço o fim para que fui predestinado por Jesus Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nOs justi meditábitur sapiéntiam, et lingua ejus loquétur judícium.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nA boca do justo fala com sabedoria e a sua língua proclama a justiça!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A lei do seu Deus está no seu coração e os seus pés não tropeçarão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que teme o Senhor e que põe todo seu zelo em obedecer-Lhe. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:32-34\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Nolíte timére, pusíllus grex, quia complácuit Patri vestro dare vobis regnum. Véndite quæ possidétis, et date eleemósynam. Fácite vobis sácculos, qui non veteráscunt, thesáurum non deficiéntem in cœlis: quo fur non apprópiat, neque tínea corrúmpit. Ubi enim thesáurus vester est, ibi et cor vestrum erit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:32-34\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Não temais, pequeno rebanho, pois agradou ao vosso Pai dar-vos o seu reino. Vendei tudo quanto possuís e dai-o em esmolas. Fazei para vós bolsas que se não estraguem com o tempo; ajuntai um tesouro no céu, onde o ladrão não pode chegar, nem a traça o pode corromper; pois, onde estiver o vosso tesouro, aí estará o vosso coração».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 20:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nIn virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 20:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nCom o vosso poder, Senhor, se alegrará o justo, o qual exultará de alegria, vendo-se salvo por Vós. Concedestes-lhe, Senhor, o desejo da sua alma.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPræsta nobis, quǽsumus, omnípotens Deus: ut nostræ humilitátis oblátio et pro tuórum tibi grata sit honóre Sanctórum, et nos córpore páriter et mente puríficet.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos conceder-nos, Deus omnipotente, que esta oferta da nossa humildade, em honra dos vossos Santos, Vos seja agradável; e permiti que nos purifique ao mesmo tempo o corpo e a alma.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 19:28-29\u003c/I>\u003c/FONT>\u003cbr/>\nAmen, dico vobis: quod vos, qui reliquístis ómnia et secúti estis me, céntuplum accipiétis, et vitam ætérnam possidébitis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 19:28-29\u003c/I>\u003c/FONT>\u003cbr/>\nEm verdade vos digo: vós, que abandonastes tudo e me seguistes, recebereis o cêntuplo e possuireis a vida eterna.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nQuǽsumus, omnípotens Deus: ut, qui cœléstia aliménta percépimus, intercedénte beáto Petro Confessóre tuo, per hæc contra ómnia advérsa muniámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente, Vos imploramos, havendo nós recebido o alimento celestial, fazei que, por intercessão do B. Confessor Pedro sejamos fortificados contra todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-20":{"date":"2026-10-20","title":"São João Câncio, confessor","forms":[{"number":1,"title":"S. Joannis Cantii Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/10-20.txt","rule":"vide C5;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 18:12-13\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>iserátio hóminis circa próximum: misericórdia autem Dei super omnem carnem. Qui misericórdiam habet, docet et érudit quasi pastor gregem suum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 1:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui non ábiit in consílio impiórum, et in via peccatórum non stetit, et in cáthedra pestiléntiæ non sedit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>iserátio hóminis circa próximum: misericórdia autem Dei super omnem carnem. Qui misericórdiam habet, docet et érudit quasi pastor gregem suum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 18:12-13\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> misericórdia do homem exerce-se para com seu próximo; enquanto que a misericórdia de Deus espalha-se sobre toda a carne. Aquele que possui misericórdia ensina e guia os homens, como um pastor guia o seu rebanho.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 1:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que não foi no conselho dos ímpios, nem ficou no caminho dos pecadores, * e na cadeira pestilencial se não sentou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> misericórdia do homem exerce-se para com seu próximo; enquanto que a misericórdia de Deus espalha-se sobre toda a carne. Aquele que possui misericórdia ensina e guia os homens, como um pastor guia o seu rebanho.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDa, quǽsumus, omnípotens Deus: ut, sancti Joánnis Confessóris exémplo in sciéntia Sanctórum proficiéntes atque áliis misericórdiam exhibéntes; ejus méritis, indulgéntiam apud te consequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nConcedei-nos, ó Deus omnipotente. Vos suplicamos, que, progredindo nós na ciência dos Santos e praticando a misericórdia para com o próximo, a exemplo do Santo Confessor João, obtenhamos pelos seus méritos a vossa indulgência.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Jacóbi Apóstoli\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jac 2:12-17\u003c/I>\u003c/FONT>\u003cbr/>\nCarissimi: Sic loquímini, et sic fácite sicut per legem libertátis incipiéntes judicári. Judícium enim sine misericórdia illi, qui non fecit misericórdiam: superexáltat autem misericórdia judícium. Quid próderit, fratres mei, si fidem quis dicat se habére, ópera autem non hábeat? Numquid poterit fides salváre eum? Si autem frater et soror nudi sint, et indígeant victu quotidiáno, dicat autem áliquis ex vobis illis: Ite in pace, calefacímini et saturámini: non dedéritis autem eis, quæ necessária sunt córpori, quid próderit? Sic et fides, si non hábeat ópera, mórtua est in semetípsa.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Tiago.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 2:12-17\u003c/I>\u003c/FONT>\u003cbr/>\nFalai e procedei como devendo ser julgados pela lei da liberdade; pois o juízo de Deus será sem misericórdia para com aquele que não houver tido misericórdia; enquanto que a misericórdia triunfará no juízo. Meus irmãos: de que serve alguém dizer que tem fé, se não possui obras? Porventura poderá esta fé salvá-lo? Ora, se a um irmão ou irmã, estando nu e carecendo cada dia de sustento, algum de vós disser: «Ide em paz, aquecei-vos e saciai-vos», mas lhe não der aquilo que lhe é necessário ao corpo, de que lhe servirão as palavras? Assim, se a fé não é acompanhada de obras, está morta por si própria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 106:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nConfiteántur Dómino misericórdiæ ejus: et mirabília ejus fíliis hóminum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Quia satiávit ánimam inánem: et ánimam esuriéntem satiavit bonis. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 31:20\u003c/I>\u003c/FONT>\u003cbr/>\nManum suam apéruit ínopi: et palmas suas exténdit ad páuperem. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 106:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLouvai o Senhor pelas suas misericórdias e pelas suas maravilhas em favor dos filhos dos homens.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Pois Ele saciou a alma vazia e encheu de benefícios a alma faminta. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 31:20\u003c/I>\u003c/FONT>\u003cbr/>\nAbriu a sua mão para o indigente: e estendeu os seus braços para o pobre. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Estejam cingidos os vossos rins; tende nas vossas mãos lâmpadas acesas; sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para que, quando chegar e bater à porta, logo lha abram. Bem-aventurados aqueles servos que seu senhor, quando chegar, os achar vigilantes. Em verdade vos digo que se cingirá, e, mandando-os sentar à mesa, passará por entre eles e os servirá. E, se chegar na segunda ou terceira vigília e assim os achar, bem-aventurados são esses servos. Ora, sabei que, se o pai de família conhecesse a hora em que viria o ladrão, vigiava, sem dúvida, para que sua casa não fosse assaltada. Vós, pois, estai preparados, porque o Filho do homem virá à hora em que menos cuidais».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Job 29:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nJustítia indútus sum, et vestívi me, sicut vestiménto et diadémate, judício meo. Oculus fui cæco et pes claudo: pater eram páuperum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jb 29:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nRevesti-me de justiça, e a equidade dos meus juízos serviu-me como que de vestido e de diadema. Tenho sido olhos para o cego e pés para o coxo. Tenho sido o pai dos pobres.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHas, quǽsumus, Dómine, hóstias sancti Joánnis Confessóris tui méritis benígnus assúme: et præsta; ut, te super ómnia et omnes propter te diligéntes, corde tibi et ópere placeámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai benignamente estas hóstias pelos méritos do vosso Santo Confessor João, Vos suplicamos, Senhor, e fazei que, amando-Vos sobre todas as cousas e ao próximo por amor de Vós, nos tornemos agradáveis a Deus pelos nossos sentimentos e obras.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 6:38\u003c/I>\u003c/FONT>\u003cbr/>\nDate, et dábitur vobis: mensúram bonam et confértam et coagitátam et supereffluéntem dabunt in sinum vestrum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 6:38\u003c/I>\u003c/FONT>\u003cbr/>\nDai e ser-vos-á dado: derramar-se-á no vosso seio uma boa medida, cheia, calcada, acogulada e a trasbordar.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPretiósi Córporis et Sánguinis tui, Dómine, pasti delíciis, tuam súpplices deprecámur clementiam: ut, sancti Joánnis Confessóris tui méritis et exémplis, ejúsdem caritátis imitatóres effécti, consórtes simus et glóriæ:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo sido alimentados com as delícias do vosso preciosíssimo Corpo e Sangue, Senhor, imploramos humildemente da vossa clemência, que, pelos méritos e exemplos do vosso Santo Confessor João, nos tornemos imitadores da sua caridade e compartilhemos também da sua glória.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-21":{"date":"2026-10-21","title":"Féria da 21ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Quarta infra Hebdomadam XXI post Octavam Pentecostes IV. Octobris\tFeria","winner":"Tempora/Pent21-3.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 13:9; 13:10-11\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n voluntáte tua, Dómine, univérsa sunt pósita, et non est, qui possit resístere voluntáti tuæ: tu enim fecísti ómnia, cœlum et terram et univérsa, quæ cœli ámbitu continéntur: Dominus universórum tu es\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n voluntáte tua, Dómine, univérsa sunt pósita, et non est, qui possit resístere voluntáti tuæ: tu enim fecísti ómnia, cœlum et terram et univérsa, quæ cœli ámbitu continéntur: Dominus universórum tu es.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 13:9-11\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odas as cousas, Senhor, estão sujeitas à vossa vontade, e ninguém pode resistir-lhe; pois criastes tudo: o céu, a terra e o que se encerra no âmbito dos céus. Sois o Senhor do universo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles cuja vida é imaculada: aqueles que praticam a Lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odas as cousas, Senhor, estão sujeitas à vossa vontade, e ninguém pode resistir-lhe; pois criastes tudo: o céu, a terra e o que se encerra no âmbito dos céus. Sois o Senhor do universo.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nFamíliam tuam, quǽsumus, Dómine, contínua pietáte custódi: ut a cunctis adversitátibus, te protegénte, sit líbera, et in bonis áctibus tuo nómini sit devóta.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Hilarionis Abbatis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>ntercéssio nos, quǽsumus, Dómine, beáti Hilariónis Abbátis comméndet: ut, quod nostris méritis non valémus, ejus patrocínio assequámur.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Ursulæ et Sociarum Virg. et Mart.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>a nobis, quǽsumus, Dómine Deus noster, sanctárum Vírginum et Mártyrum tuárum Ursulæ et Sociárum palmas incessábili devotióne venerári: ut quas digna mente non póssumus celebráre, humílibus saltem frequentémus obséquiis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nGuardai com vossa contínua misericórdia a vossa família, Senhor, Vos suplicamos, a fim de que sob a vossa protecção seja preservada de todas as adversidades e se dedique à prática das boas obras, em honra do vosso nome.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Hilarião, Abade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue a intercessão do B. Abade Hilarião nos favoreça junto de Vós, Senhor, Vos suplicamos, a fim de que aquilo que não podemos conseguir com os nossos méritos o alcancemos com seu patrocínio.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Úrsula e Outras, Virgens e Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, nosso Deus, dignai-Vos conceder-nos a graça de incessantemente venerarmos com devoção a vitória das vossas Santas Virgens e Mártires Úrsula e Companheiras, a fim de que, já que não podemos celebrar dignamente os seus méritos, ao menos possamos oferecer-lhes as nossas humildes homenagens.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLectio Epistolæ beáti Pauli Apóstoli ad Ephésios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ephes 6:10-17\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Confortámini in Dómino et in poténtia virtútis ejus. Indúite vos armatúram Dei, ut póssitis stare advérsus insídias diáboli. Quóniam non est nobis colluctátio advérsus carnem et sánguinem: sed advérsus príncipes et potestátes, advérsus mundi rectóres tenebrárum harum, contra spirituália nequítiæ, in cœléstibus. Proptérea accípite armatúram Dei, ut póssitis resístere in die malo et in ómnibus perfécti stare. State ergo succíncti lumbos vestros in veritáte, et indúti lorícam justítiæ, et calceáti pedes in præparatióne Evangélii pacis: in ómnibus suméntes scutum fídei, in quo póssitis ómnia tela nequíssimi ígnea exstínguere: et gáleam salútis assúmite: et gládium spíritus, quod est verbum Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Efésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eph 6:10-17\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Confortai-vos no Senhor e no seu poder omnipotente. Revesti-vos de todas armas de Deus, a fim de que possais suportar as ciladas do demónio; pois temos de combater, não só contra a carne e o sangue, mas também contra os príncipes e as potestades do inferno, contra os dominadores deste mundo de trevas e contra os espíritos malignos, espalhados nas regiões do ar. Tomai, então, as armas de Deus, a fim de que, estando preparados para tudo, possais resistir no dia mau e ficar de pé e perfeitos em todas as cousas. Sede firmes, pois! Que a verdade seja o cinto dos vossos rins, e a justiça a vossa couraça. Calçai vossos pés para vos preparardes para seguir o Evangelho da paz. Empunhai sempre o escudo da fé, para poderdes quebrar os dardos inflamados do espírito maligno. Revesti-vos, também, com o capacete da salvação e com a espada espiritual, que é a palavra de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 89:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, refúgium factus es nobis, a generatióne et progénie.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Priúsquam montes fíerent aut formarétur terra et orbis: a sǽculo et usque in sǽculum tu es, Deus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 113:1\u003c/I>\u003c/FONT>\u003cbr/>\nIn éxitu Israël de Ægýpto, domus Jacob de pópulo bárbaro. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 89:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nTendes sido, Senhor, o nosso refúgio de geração em geração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Antes que as montanhas houvessem sido formadas e que a terra e o mundo tivessem sido criados, já, desde toda a eternidade, Vós éreis Deus. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 113:1\u003c/I>\u003c/FONT>\u003cbr/>\nQuando Israel saiu do Egipto e a casa de Jacob do meio de um povo bárbaro. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 18:23-35\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Assimilátum est regnum cœlórum hómini regi, qui vóluit ratiónem pónere cum servis suis. Et cum cœpísset ratiónem pónere, oblátus est ei unus, qui debébat ei decem mília talénta. Cum autem non habéret, unde rédderet, jussit eum dóminus ejus venúmdari et uxórem ejus et fílios et ómnia, quæ habébat, et reddi. Prócidens autem servus ille, orábat eum, dicens: Patiéntiam habe in me, et ómnia reddam tibi. Misértus autem dóminus servi illíus, dimísit eum et débitum dimísit ei. Egréssus autem servus ille, invénit unum de consérvis suis, qui debébat ei centum denários: et tenens suffocábat eum, dicens: Redde, quod debes. Et prócidens consérvus ejus, rogábat eum, dicens: Patiéntiam habe in me, et ómnia reddam tibi. Ille autem nóluit: sed ábiit, et misit eum in cárcerem, donec rédderet débitum. Vidéntes autem consérvi ejus, quæ fiébant, contristáti sunt valde: et venérunt et narravérunt dómino suo ómnia, quæ facta fúerant. Tunc vocávit illum dóminus suus: et ait illi: Serve nequam, omne débitum dimísi tibi, quóniam rogásti me: nonne ergo opórtuit et te miseréri consérvi tui, sicut et ego tui misértus sum? Et irátus dóminus ejus, trádidit eum tortóribus, quoadúsque rédderet univérsum débitum. Sic et Pater meus cœléstis fáciet vobis, si non remiséritis unusquísque fratri suo de córdibus vestris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 18:23-35\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, Jesus disse aos seus discípulos esta parábola: O reino dos céus é semelhante a um rei que quis fazer contas com seus servos. Logo que começou as contas, apresentou-se um servo que lhe devia dez mil talentos. Ora, como este não tinha com que pagar, mandou o senhor que o vendessem, assim como sua mulher, filhos e tudo quanto possuía, para liquidar a dívida. Então este servo, prostrando-se aos pés do rei, pedia-lhe: «Tende paciência para comigo, e pagarei tudo». E o senhor compadeceu-se do servo, deixou-o ir embora e perdoou-lhe a dívida. Apenas o servo saiu, encontrou ele um seu companheiro, que lhe devia cem dinheiros. Logo, agarrou-o até quase o sufocar e disse-lhe: «Paga-me o que me deves». O companheiro prostrou-se a seus pés, suplicando-lhe nestes termos: «Tende paciência para comigo, e pagarei tudo». Mas não quis atendê-lo. Foi dali e mandou metê-lo na cadeia, até que lhe pagasse a dívida. Vendo os outros servos, seus companheiros, o que acontecera, ficaram profundamente tristes, indo narrar tudo ao senhor. Então o senhor mandou chamar o servo e disse-lhe: «Perdoei-te toda tua dívida, porque assim me rogaste; portanto não devias tu, também, ter piedade do teu companheiro, como tive de ti?». Imediatamente se encolerizou o senhor, entregando-o aos algozes da justiça, até que lhe pagasse a sua dívida. Pois bem, terminou Jesus, assim vos tratará meu Pai celeste se cada um não perdoar do íntimo do coração a sua dívida ao seu irmão.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Job 1.1\u003c/I>\u003c/FONT>\u003cbr/>\nVir erat in terra Hus, nómine Job: simplex et rectus ac timens Deum: quem Satan pétiit ut tentáret: et data est ei potéstas a Dómino in facultátes et in carnem ejus: perdidítque omnem substántiam ipsíus et fílios: carnem quoque ejus gravi úlcere vulnerávit.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jb 1.1\u003c/I>\u003c/FONT>\u003cbr/>\nVivia no país de Hus um homem chamado Job, que era simples, justo e temente a Deus. Então Satanás pediu licença ao Senhor para o tentar, o que lhe foi permitido, mas somente quanto aos bens e ao corpo: e Satanás fez-lhe perder todos os bens e os filhos, e ainda lhe afligiu o corpo com uma chaga.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSuscipe, Dómine, propítius hóstias: quibus et te placári voluísti, et nobis salútem poténti pietáte restítui.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Hilarionis Abbatis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>acris altáribus, Dómine, hóstias superpósitas sanctus Hilariónis Abbas, quǽsumus, in salútem nobis proveníre depóscat.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Ursulæ et Sociarum Virg. et Mart.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>nténde, quǽsumus, Dómine, múnera altáribus tuis pro sanctárum Vírginum et Mártyrum tuárum Ursulæ et Sociárum festivitáte propósita: ut, sicut per hæc beáta mystéria illis glóriam contulísti; ita nobis indulgéntiam largiáris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai propício, Senhor, estas hóstias com as quais quisestes aplacar-Vos, e, pela vossa infinita bondade, concedei-nos a salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Hilarião, Abade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>os imploramos, Senhor, que o vosso santo Abade Hilarião nos alcance que a hóstia, oferecida no vosso altar, nos proporcione a salvação.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Úrsula e Outras, Virgens e Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, dignai-Vos volver os vossos olhares para estas ofertas, que depositamos nos vossos altares para celebrar a festa das vossas Santas Virgens e Mártires Úrsula e Companheiras, a fim de que, assim como lhes concedestes a glória, assim nos concedais o perdão dos nossos pecados.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:81; 118:84; 118:86\u003c/I>\u003c/FONT>\u003cbr/>\nIn salutári tuo ánima mea, et in verbum tuum sperávi: quando fácies de persequéntibus me judícium? iníqui persecúti sunt me, ádjuva me, Dómine, Deus meus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:81; 118:84; 118:86\u003c/I>\u003c/FONT>\u003cbr/>\nA minha alma suspira pela salvação: e pus toda minha esperança na vossa palavra. Quando tratareis com justiça os meus perseguidores? Homens injustos perseguem-me; auxiliai-me, Senhor!\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nImmortalitátis alimóniam consecúti, quǽsumus, Dómine: ut, quod ore percépimus, pura mente sectémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Hilarionis Abbatis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>rótegat nos, Dómine, cum tui perceptióne sacraménti beátus Hilariónis Abbas, pro nobis intercedéndo: ut et conversatiónis ejus experiámur insígnia, et intercessiónis percipiámus suffrágia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Ursulæ et Sociarum Virg. et Mart.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta nobis, quǽsumus, Dómine, intercedéntibus sanctis Virgínibus et Martýribus tuis Ursula et Sociábus: ut, quod ore contíngimus, pura mente capiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido o alimento da imortalidade, permiti, Senhor, Vos suplicamos, que guardemos com o coração puro aquilo que a nossa boca recebeu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Hilarião, Abade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, unida às preces do B. Hilarião Abade, nos sirva de protecção, a fim de que, imitando os insignes exemplos da sua vida, sintamos os efeitos da sua intercessão.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Úrsula e Outras, Virgens e Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>oncedei-nos, Senhor, Vos suplicamos, que por intercessão das vossas Santas Virgens e Mártires Úrsula e Companheiras guardemos com o coração puro o que a nossa boca acaba de receber.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-22":{"date":"2026-10-22","title":"Féria da 21ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Quinta infra Hebdomadam XXI post Octavam Pentecostes IV. Octobris\tFeria","winner":"Tempora/Pent21-4.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 13:9; 13:10-11\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n voluntáte tua, Dómine, univérsa sunt pósita, et non est, qui possit resístere voluntáti tuæ: tu enim fecísti ómnia, cœlum et terram et univérsa, quæ cœli ámbitu continéntur: Dominus universórum tu es\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n voluntáte tua, Dómine, univérsa sunt pósita, et non est, qui possit resístere voluntáti tuæ: tu enim fecísti ómnia, cœlum et terram et univérsa, quæ cœli ámbitu continéntur: Dominus universórum tu es.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 13:9-11\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odas as cousas, Senhor, estão sujeitas à vossa vontade, e ninguém pode resistir-lhe; pois criastes tudo: o céu, a terra e o que se encerra no âmbito dos céus. Sois o Senhor do universo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles cuja vida é imaculada: aqueles que praticam a Lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odas as cousas, Senhor, estão sujeitas à vossa vontade, e ninguém pode resistir-lhe; pois criastes tudo: o céu, a terra e o que se encerra no âmbito dos céus. Sois o Senhor do universo.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nFamíliam tuam, quǽsumus, Dómine, contínua pietáte custódi: ut a cunctis adversitátibus, te protegénte, sit líbera, et in bonis áctibus tuo nómini sit devóta.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nGuardai com vossa contínua misericórdia a vossa família, Senhor, Vos suplicamos, a fim de que sob a vossa protecção seja preservada de todas as adversidades e se dedique à prática das boas obras, em honra do vosso nome.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLectio Epistolæ beáti Pauli Apóstoli ad Ephésios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ephes 6:10-17\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Confortámini in Dómino et in poténtia virtútis ejus. Indúite vos armatúram Dei, ut póssitis stare advérsus insídias diáboli. Quóniam non est nobis colluctátio advérsus carnem et sánguinem: sed advérsus príncipes et potestátes, advérsus mundi rectóres tenebrárum harum, contra spirituália nequítiæ, in cœléstibus. Proptérea accípite armatúram Dei, ut póssitis resístere in die malo et in ómnibus perfécti stare. State ergo succíncti lumbos vestros in veritáte, et indúti lorícam justítiæ, et calceáti pedes in præparatióne Evangélii pacis: in ómnibus suméntes scutum fídei, in quo póssitis ómnia tela nequíssimi ígnea exstínguere: et gáleam salútis assúmite: et gládium spíritus, quod est verbum Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Efésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eph 6:10-17\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Confortai-vos no Senhor e no seu poder omnipotente. Revesti-vos de todas armas de Deus, a fim de que possais suportar as ciladas do demónio; pois temos de combater, não só contra a carne e o sangue, mas também contra os príncipes e as potestades do inferno, contra os dominadores deste mundo de trevas e contra os espíritos malignos, espalhados nas regiões do ar. Tomai, então, as armas de Deus, a fim de que, estando preparados para tudo, possais resistir no dia mau e ficar de pé e perfeitos em todas as cousas. Sede firmes, pois! Que a verdade seja o cinto dos vossos rins, e a justiça a vossa couraça. Calçai vossos pés para vos preparardes para seguir o Evangelho da paz. Empunhai sempre o escudo da fé, para poderdes quebrar os dardos inflamados do espírito maligno. Revesti-vos, também, com o capacete da salvação e com a espada espiritual, que é a palavra de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 89:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, refúgium factus es nobis, a generatióne et progénie.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Priúsquam montes fíerent aut formarétur terra et orbis: a sǽculo et usque in sǽculum tu es, Deus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 113:1\u003c/I>\u003c/FONT>\u003cbr/>\nIn éxitu Israël de Ægýpto, domus Jacob de pópulo bárbaro. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 89:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nTendes sido, Senhor, o nosso refúgio de geração em geração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Antes que as montanhas houvessem sido formadas e que a terra e o mundo tivessem sido criados, já, desde toda a eternidade, Vós éreis Deus. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 113:1\u003c/I>\u003c/FONT>\u003cbr/>\nQuando Israel saiu do Egipto e a casa de Jacob do meio de um povo bárbaro. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 18:23-35\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Assimilátum est regnum cœlórum hómini regi, qui vóluit ratiónem pónere cum servis suis. Et cum cœpísset ratiónem pónere, oblátus est ei unus, qui debébat ei decem mília talénta. Cum autem non habéret, unde rédderet, jussit eum dóminus ejus venúmdari et uxórem ejus et fílios et ómnia, quæ habébat, et reddi. Prócidens autem servus ille, orábat eum, dicens: Patiéntiam habe in me, et ómnia reddam tibi. Misértus autem dóminus servi illíus, dimísit eum et débitum dimísit ei. Egréssus autem servus ille, invénit unum de consérvis suis, qui debébat ei centum denários: et tenens suffocábat eum, dicens: Redde, quod debes. Et prócidens consérvus ejus, rogábat eum, dicens: Patiéntiam habe in me, et ómnia reddam tibi. Ille autem nóluit: sed ábiit, et misit eum in cárcerem, donec rédderet débitum. Vidéntes autem consérvi ejus, quæ fiébant, contristáti sunt valde: et venérunt et narravérunt dómino suo ómnia, quæ facta fúerant. Tunc vocávit illum dóminus suus: et ait illi: Serve nequam, omne débitum dimísi tibi, quóniam rogásti me: nonne ergo opórtuit et te miseréri consérvi tui, sicut et ego tui misértus sum? Et irátus dóminus ejus, trádidit eum tortóribus, quoadúsque rédderet univérsum débitum. Sic et Pater meus cœléstis fáciet vobis, si non remiséritis unusquísque fratri suo de córdibus vestris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 18:23-35\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, Jesus disse aos seus discípulos esta parábola: O reino dos céus é semelhante a um rei que quis fazer contas com seus servos. Logo que começou as contas, apresentou-se um servo que lhe devia dez mil talentos. Ora, como este não tinha com que pagar, mandou o senhor que o vendessem, assim como sua mulher, filhos e tudo quanto possuía, para liquidar a dívida. Então este servo, prostrando-se aos pés do rei, pedia-lhe: «Tende paciência para comigo, e pagarei tudo». E o senhor compadeceu-se do servo, deixou-o ir embora e perdoou-lhe a dívida. Apenas o servo saiu, encontrou ele um seu companheiro, que lhe devia cem dinheiros. Logo, agarrou-o até quase o sufocar e disse-lhe: «Paga-me o que me deves». O companheiro prostrou-se a seus pés, suplicando-lhe nestes termos: «Tende paciência para comigo, e pagarei tudo». Mas não quis atendê-lo. Foi dali e mandou metê-lo na cadeia, até que lhe pagasse a dívida. Vendo os outros servos, seus companheiros, o que acontecera, ficaram profundamente tristes, indo narrar tudo ao senhor. Então o senhor mandou chamar o servo e disse-lhe: «Perdoei-te toda tua dívida, porque assim me rogaste; portanto não devias tu, também, ter piedade do teu companheiro, como tive de ti?». Imediatamente se encolerizou o senhor, entregando-o aos algozes da justiça, até que lhe pagasse a sua dívida. Pois bem, terminou Jesus, assim vos tratará meu Pai celeste se cada um não perdoar do íntimo do coração a sua dívida ao seu irmão.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Job 1.1\u003c/I>\u003c/FONT>\u003cbr/>\nVir erat in terra Hus, nómine Job: simplex et rectus ac timens Deum: quem Satan pétiit ut tentáret: et data est ei potéstas a Dómino in facultátes et in carnem ejus: perdidítque omnem substántiam ipsíus et fílios: carnem quoque ejus gravi úlcere vulnerávit.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jb 1.1\u003c/I>\u003c/FONT>\u003cbr/>\nVivia no país de Hus um homem chamado Job, que era simples, justo e temente a Deus. Então Satanás pediu licença ao Senhor para o tentar, o que lhe foi permitido, mas somente quanto aos bens e ao corpo: e Satanás fez-lhe perder todos os bens e os filhos, e ainda lhe afligiu o corpo com uma chaga.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSuscipe, Dómine, propítius hóstias: quibus et te placári voluísti, et nobis salútem poténti pietáte restítui.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai propício, Senhor, estas hóstias com as quais quisestes aplacar-Vos, e, pela vossa infinita bondade, concedei-nos a salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:81; 118:84; 118:86\u003c/I>\u003c/FONT>\u003cbr/>\nIn salutári tuo ánima mea, et in verbum tuum sperávi: quando fácies de persequéntibus me judícium? iníqui persecúti sunt me, ádjuva me, Dómine, Deus meus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:81; 118:84; 118:86\u003c/I>\u003c/FONT>\u003cbr/>\nA minha alma suspira pela salvação: e pus toda minha esperança na vossa palavra. Quando tratareis com justiça os meus perseguidores? Homens injustos perseguem-me; auxiliai-me, Senhor!\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nImmortalitátis alimóniam consecúti, quǽsumus, Dómine: ut, quod ore percépimus, pura mente sectémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido o alimento da imortalidade, permiti, Senhor, Vos suplicamos, que guardemos com o coração puro aquilo que a nossa boca recebeu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-23":{"date":"2026-10-23","title":"Santo Antônio Maria Claret, bispo e confessor","forms":[{"number":1,"title":"S. Antonii Mariæ Claret Episcopi et Confessoris Duplex vide Commune Confessoris Pontificis (Missa Sacerdotes Dei) [Commune/C4-1.txt]","winner":"Sancti/10-23r.txt","rule":"vide C4-1;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 131:9-10.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>acerdótes tui, Dómine, induántur justítiam, et sancti tui exsúltent. Propter David servum tuum non avértas fáciem christi tui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 131:1\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>eménto, Dómine, David, et omnis mansuetúdinis ejus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>acerdótes tui, Dómine, induántur justítiam, et sancti tui exsúltent. Propter David servum tuum non avértas fáciem christi tui.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 131:9-10\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue os vossos sacerdotes, Senhor, se revistam de santidade; e que os vossos santos exultem de alegria! Por amor do vosso servo David não afasteis os olhos do vosso Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 131:1\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-Vos, Senhor, de David e da sua grande mansidão.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue os vossos sacerdotes, Senhor, se revistam de santidade; e que os vossos santos exultem de alegria! Por amor do vosso servo David não afasteis os olhos do vosso Cristo.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum Antónium Maríam Confessórem tuum atque Pontíficem, apostólicis virtútibus sublimásti, et per eum novas in Ecclésia clericórum ac vírginum famílias collegísti: concéde, quǽsumus; ut, eius dirigéntibus mónitis ac suffragántibus méritis, animárum salútem quǽrere iúgiter studeámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que embelezastes o B. António Maria, vosso Confessor e Pontífice, com as virtudes apostólicas, e por ele fundastes na vossa Igreja novas congregações de clérigos e de virgens, concedei-nos, Vos suplicamos, que, esclarecidos com seus salutares conselhos e confortados com seus exemplos, consigamos com felicidade unirmo-nos convosco.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Heb 7:23-27.\u003c/I>\u003c/FONT>\u003cbr/>\nFratres : Plures facti sunt sacerdótes, idcírco quod morte prohiberéntur permanére : Iesus autem, eo quod máneat in ætérnum, sempitérnum habet sacerdótium. Unde et salváre in perpétuum potest accedéntes per semetípsum ad Deum : semper vivens ad interpellándum pro nobis. Talis enim decébat, ut nobis esset póntifex, sanctus, ínnocens, impollútus, segregátus a peccatóribus, et excélsior cælis factus : qui non habet necessitátem cotídie, quemádmodum sacerdótes, prius pro suis delíctis hóstias offérre, deínde pro pópuli : hoc enim fecit semel, seípsum offeréndo, Jesus Christus, Dóminus noster.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Hebreus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Heb 7:23-27\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Entre eles, além disso, muitos outros foram feitos sacerdotes, porque a morte os impedia de viverem sempre. Mas Jesus, que permanece eternamente, tem um sacerdócio eterno, por isso Ele pode salvar perpetuamente aqueles que se aproximam de Deus por seu intermédio, pois está sempre vivo para interceder por nós. Convinha, pois, que tivéssemos um Pontífice santo, inocente, imaculado, afastado dos pecadores e mais elevado que os céus; que não tivesse necessidade, como os outros sacerdotes, de oferecer, quotidianamente, vítimas, primeiro pelos seus próprios pecados e depois pelos pecados do povo; pois isto Nosso Senhor Jesus Cristo fez uma vez, oferecendo-se a Si mesmo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 131:16-17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Sacerdótes ejus índuam salutári, et sancti ejus exsultatióne exsultábunt.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Illuc prodúcam cornu David; parávi lucérnam christo meo. Allelúia, allelúia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 109:4\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Jurávit Dóminus, et non pœnitébit eum: Tu es sacérdos in ætérnum secúndum órdinem Melchísedech. Allelúia.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 131:16-17\u003c/I>\u003c/FONT>\u003cbr/>\nRevestirei os seus sacerdotes de salvação e os seus santos exultarão em transportes de alegria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Em Sião farei aparecer o poder de David: prepararei uma lâmpada ao meu Cristo. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 109:4\u003c/I>\u003c/FONT>\u003cbr/>\nO Senhor jurou e não se arrependerá: Tu és sacerdote para sempre, segundo a ordem de Melquisedeque. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>ectio sancti Evangelii secundum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:42-47.\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Vigiláte ergo, quia nescítis qua hora Dóminus vester ventúrus sit. Illud autem scitóte, quóniam si sciret paterfamílias qua hora fur ventúrus esset, vigiláret útique, et non síneret pérfodi domum suam. Ideo et vos estóte paráti: quia qua nescítis hora Fílius hóminis ventúrus est. Quis, putas, est fidélis servus, et prudens, quem constítuit dóminus suus super famíliam suam ut det illis cibum in témpore? Beátus ille servus, quem cum vénerit dóminus ejus, invénerit sic faciéntem. Amen dico vobis, quóniam super ómnia bona sua constítuet eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:42-47\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus a seus discípulos: «Vigiai, porque não sabeis a que hora virá o vosso Senhor. Pois sabei que, se o pai de família conhecesse a que horas viria o ladrão, certamente velaria e não deixaria violar a sua casa. Portanto vós, também, estai preparados, porque o Filho do homem virá durante a hora em que não pensais. Qual é, segundo a vossa opinião, o servo fiel e prudente que o Senhor estabeleceu como superior na sua família para distribuir-lhe o sustento em tempo oportuno? Bem-aventurado aquele servo a quem, quando o seu senhor vier, o achar assim ocupado. Em verdade vos digo que o encarregará de administrar todos seus bens».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSancti Antónii Maríæ Confessóris tui atque Pontíficis, quǽsumus, Dómine, ánnua sollémnitas pietáti tuæ nos reddat accéptos: ut, per hæc piæ placatiónis offícia, et illum beáta retribútio comitétur, et nobis grátiæ tuæ dona concíliet.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nQue a festa anual do vosso santo Confessor e Pontífice António Maria nos torne agradáveis à vossa bondade, Vos suplicamos, Senhor, a fim de que a piedosa oferta desta vítima de expiação lhe aumente a felicidade, que goza como recompensa, e nos obtenha os dons da vossa graça.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, fidélium remunerátor animárum: præsta; ut, beáti Antónii Maríæ Confessóris tui atque Pontíficis, cujus venerándam celebrámus festivitátem, précibus indulgéntiam consequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, remunerador das almas fiéis, dignai-Vos permitir que pelas orações do B. Pontífice e Confessor António Maria, cuja veneranda festa celebramos, obtenhamos o perdão dos nossos pecados.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-24":{"date":"2026-10-24","title":"São Rafael, arcanjo","forms":[{"number":1,"title":"S. Raphaëlis Archangeli Duplex majus","winner":"Sancti/10-24.txt","rule":"ex Sancti/05-08\nGloria\nCredoDA\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 102:20\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>B\u003c/I>\u003c/B>\u003c/FONT>enedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 102:1\u003c/I>\u003c/FONT>\u003cbr/>\nBénedic, ánima mea, Dómino: et ómnia, quæ intra me sunt, nómini sancto ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>B\u003c/I>\u003c/B>\u003c/FONT>enedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 102:20\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>B\u003c/I>\u003c/B>\u003c/FONT>endizei o Senhor, ó vós, todos os Anjos do Senhor: Sois cheios de poder e virtude: e fazeis o que Ele vos manda, obedecendo às suas palavras e ordens.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 102:1\u003c/I>\u003c/FONT>\u003cbr/>\nBendiz o Senhor, ó minha alma: Que tudo quanto houver em mim bendiga o santo Nome do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>B\u003c/I>\u003c/B>\u003c/FONT>endizei o Senhor, ó vós, todos os Anjos do Senhor: Sois cheios de poder e virtude: e fazeis o que Ele vos manda, obedecendo às suas palavras e ordens.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum Raphaélem Archángelum Tobíæ fámulo tuo cómitem dedísti in via: concéde nobis fámulis tuis; ut ejúsdem semper protegámur custódia et muniámur auxílio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que designastes o Arcanjo Rafael para guia do vosso servo Tobias, concedei-nos a nós, que somos vossos servos, a graça de sermos sempre protegidos por ele e fortalecidos com seu auxílio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Tobíæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tob 12:7-15\u003c/I>\u003c/FONT>\u003cbr/>\nIn diébus illis: Dixit Angelus Ráphaël ad Tobíam: Sacraméntum regis abscóndere bonum est: ópera autem Dei reveláre et confitéri honoríficum est. Bona est orátio cum jejúnio, et eleemósyna magis quam thesáuros auri recóndere: quóniam eleemósyna a morte liberat, et ipsa est, quæ purgat peccáta et facit invenire misericórdiam et vitam ætérnam. Qui autem faciunt peccátum et iniquitátem, hostes sunt ánimæ suæ. Manifésto ergo vobis veritátem, et non abscóndam a vobis occúltum sermónem. Quando orábas cum lácrimis, et sepeliébas mórtuos, et derelinquébas prándium tuum, et mórtuos abscondébas per diem in domo tua, et nocte sepeliébas eos, ego óbtuli oratiónem tuam Dómino. Et quia accéptus eras Deo, necésse fuit, ut tentátio probáret te. Et nunc misit me Dóminus, ut curárem te, et Saram uxórem fílii tui a dæmónio liberárem. Ego enim sum Raphaël Angelus, unus ex septem, qui astámus ante Dóminum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro de Tobias.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tob 12:7-15\u003c/I>\u003c/FONT>\u003cbr/>\nNaqueles dias, disse o Anjo Rafael a Tobias: «É bom ocultar o segredo de um rei, mas é honroso descobrir e publicar as obras de Deus. A oração, acompanhada com o jejum e com a esmola, vale mais do que os tesouros que se podem juntar; pois a esmola livra da morte, apaga os pecados e faz alcançar a misericórdia e a vida eterna. Aqueles, porém, que cometem o pecado e a iniquidade são inimigos de suas almas. Quero, pois, descobrir-vos a verdade e não vos ocultar uma só cousa secreta: Quando oráveis com lágrimas; sepultáveis os mortos; deixáveis o vosso descanso; guardáveis os mortos em vossa casa de dia e os sepultáveis de noite: então ofereci ao Senhor as vossas orações. E porque éreis agradável a Deus, foi necessário que a tentação vos experimentasse. Mas logo o Senhor me mandou para vos curar e para do demónio livrar Sara, mulher do vosso filho. Pois sou o Anjo Rafael, um dos sete que estão sempre presentes, diante do Senhor».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tob 8:3\u003c/I>\u003c/FONT>\u003cbr/>\nAngelus Dómini Raphaël apprehéndit et ligávit dæmonem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 146:5.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Magnus Dóminus noster, et magna virtus ejus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 137:1-2.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In conspéctu Angelórum psallam tibi: adorábo ad templum sanctum tuum, et confitébor nómini tuo, Dómine. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tob 8:3\u003c/I>\u003c/FONT>\u003cbr/>\nRafael, o Anjo do Senhor, dominou o demónio e amarrou-o.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 146:5.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Grande é o Senhor, nosso Deus; grande é o seu poder. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 137:1-2\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Cantarei Salmos na presença dos Anjos; adorar-Vos-ei no vosso santo templo e glorificarei o vosso santo nome, ó Senhor. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 5:1-4\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Erat dies festus Judæórum, et ascéndit Jesus Jerosólymam. Est autem Jerosólymis Probática piscína, quæ cognominátur hebráice Bethsaida, quinque pórticus habens. In his jacébat multitúdo magna languéntium, cæcórum, claudórum, aridórum exspectántium aquæ motum. Angelus autem Dómini descendébat secúndum tempus in piscínam, et movebátur aqua. Et, qui prior descendísset in piscínam post motiónem aquæ, sanus fiebat, a quacúmque detinebátur infirmitáte.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 5:1-4\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, sendo o dia da festa dos judeus, Jesus subiu até Jerusalém. Ora há perto de Jerusalém uma piscina que se chama em hebreu Betsaida, e tem cinco alpendres, debaixo dos quais costumava estar deitada grande multidão de enfermos: cegos, coxos e paralíticos, à espera de que a água se movesse; pois um Anjo do Senhor descia de tempos a tempos à piscina, revolvia a água e o primeiro que descia à piscina, depois do movimento da água, ficava curado de qualquer enfermidade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 8:3; 8:4\u003c/I>\u003c/FONT>\u003cbr/>\nStetit Angelus juxta aram templi, habens thuríbulum áureum in manu sua, et data sunt ei incénsa multa: et ascéndit fumus aromátum in conspéctu Dei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 8:3-4\u003c/I>\u003c/FONT>\u003cbr/>\nJunto ao altar, no templo, estava de pé um Anjo, tendo na mão um turíbulo de ouro: e deitaram-lhe muito incenso, subindo o fumo dos perfumes à presença de Deus.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHóstias tibi, Dómine, laudis offérimus, supplíciter deprecántes: ut eásdem, angélico pro nobis interveniénte suffrágio, et placátus accípias, et ad salútem nostram proveníre concédas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor, Vos oferecemos estas hóstias de louvor, suplicando-Vos humildemente que, por intercessão do santo Anjo, as aceiteis propício e nos concedais que sejam úteis à nossa salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dan 3:58\u003c/I>\u003c/FONT>\u003cbr/>\nBenedícite, omnes Angeli Dómini, Dóminum: hymnum dícite et superexaltáte eum in sǽcula.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dn 3:58\u003c/I>\u003c/FONT>\u003cbr/>\nAnjos do Senhor, bendizei todos o Senhor: cantai hinos em seu louvor e exaltai-O em todos os séculos.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDirigere dignáre, Dómine Deus, in adjutórium nostrum sanctum Raphaélem Archángelum: et, quem tuæ majestáti semper assístere crédimus, tibi nostras exíguas preces benedicéndas assígnet.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Senhor, nosso Deus, dignai-Vos mandar para nosso guarda o santo Arcanjo Rafael; e que as nossas humildes preces Vos sejam apresentadas para serem abençoadas por aquele que sabemos estar sempre na presença de vossa majestade.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-25":{"date":"2026-10-25","title":"Cristo Rei","forms":[{"number":1,"title":"In festo Domini Nostri Jesu Christi Regis Duplex 1 class","winner":"Sancti/10-DUr.txt","rule":"9 lectiones\nGloria\nCredo\nPrefatio=Regis\nFestum Domini\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 5:12; 1:6\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ignus est Agnus, qui occísus est, accípere virtútem, et divinitátem, et sapiéntiam, et fortitúdinem, et honórem. Ipsi glória et impérium in sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 71:1\u003c/I>\u003c/FONT>\u003cbr/>\nDeus, judícium tuum Regi da: et justítiam tuam Fílio Regis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ignus est Agnus, qui occísus est, accípere virtútem, et divinitátem, et sapiéntiam, et fortitúdinem, et honórem. Ipsi glória et impérium in sǽcula sæculórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 5:12; 1:6\u003c/I>\u003c/FONT>\u003cbr/>\nO Cordeiro, que foi imolado, é digno de receber o poder, a divindade, a sabedoria, a fortaleza, a honra: A Ele a glória e o império em todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 71:1\u003c/I>\u003c/FONT>\u003cbr/>\nÓ Deus, dai ao Rei o poder de julgar; e a vossa justiça ao Filho do Rei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\nO Cordeiro, que foi imolado, é digno de receber o poder, a divindade, a sabedoria, a fortaleza, a honra: A Ele a glória e o império em todos os séculos dos séculos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, qui in dilécto Fílio tuo, universórum Rege, ómnia instauráre voluísti: concéde propítius; ut cunctæ famíliæ géntium, peccáti vúlnere disgregátæ, ejus suavissímo subdántur império:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nOmnipotente e eterno Deus, que tudo quisestes restaurar no vosso dilecto Filho, Rei de todas as cousas, concedei-nos propício que todas as famílias do mundo, livres da chaga do pecado, se submetam ao Seu suavíssimo império.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Colossénses.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 1:12-20\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Grátias ágimus Deo Patri, qui dignos nos fecit in partem sortis sanctórum in lúmine: qui erípuit nos de potestáte tenebrárum, et tránstulit in regnum Fílii dilectiónis suæ, in quo habémus redemptiónem per sánguinem ejus, remissiónem peccatórum: qui est imágo Dei invisíbilis, primogénitus omnis creatúræ: quóniam in ipso cóndita sunt univérsa in cœlis et in terra, visibília et invisibília, sive Throni, sive Dominatiónes, sive Principátus, sive Potestátes: ómnia per ipsum, et in ipso creáta sunt: et ipse est ante omnes, et ómnia in ipso constant. Et ipse est caput córporis Ecclésiæ, qui est princípium, primogénitus ex mórtuis: ut sit in ómnibus ipse primátum tenens; quia in ipso complácuit omnem plenitúdinem inhabitáre; et per eum reconciliáre ómnia in ipsum, pacíficans per sánguinem crucis ejus, sive quæ in terris, sive quæ in cœlis sunt, in Christo Jesu Dómino nostro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Colossenses.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 1:12-20\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Damos graças a Deus Pai, porque nos fez dignos de participar da herança dos Santos na luz, nos livrou do poder das trevas e nos conduziu para o reino do seu muito amado Filho, no qual possuímos a redenção pelo seu sangue e a remissão dos pecados. Ele é a imagem de Deus invisível e o primogénito de todas as criaturas; porquanto n’Ele foram criadas todas as cousas nos céus e na terra, visíveis e invisíveis, quer sejam os Tronos, quer as Dominações, quer os Principados, quer as Potestades. Tudo foi criado por Ele e n’Ele próprio. Ele existe antes de todas as cousas e todas as cousas subsistem por Ele. Ele é a cabeça do corpo da Igreja e o princípio e o primogénito de todos os mortais, para que assim conserve a primazia de todas as cousas, pois foi do agrado do Pai que n’Ele residisse toda a plenitude e por Ele se reconciliem em si próprio todas as cousas, pacificando pelo seu sangue na Cruz tanto o que está na terra, como o que está no céu, em Nosso Senhor Jesus Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 71:8; 78:11\u003c/I>\u003c/FONT>\u003cbr/>\nDominábitur a mari usque ad mare, et a flúmine usque ad términos orbis terrárum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et adorábunt eum omnes reges terræ: omnes gentes sérvient ei. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dan 7:14.\u003c/I>\u003c/FONT>\u003cbr/>\nPotéstas ejus, potéstas ætérna, quæ non auferétur: et regnum ejus, quod non corrumpétur. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 71:8; 78:11\u003c/I>\u003c/FONT>\u003cbr/>\nDominará de mar a mar e desde o rio aos confins da redondeza da terra! V. Adorá-l’O-ão todos os reis da terra: e todos os povos O servirão! Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dn 7:14\u003c/I>\u003c/FONT>\u003cbr/>\nSeu poder é eterno, nunca Lhe será tirado; seu reino é tal que nunca será corrompido. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 18:33-37\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Pilátus ad Jesum: Tu es Rex Judæórum? Respóndit Jesus: A temetípso hoc dicis, an álii dixérunt tibi de me? Respóndit Pilátus: Numquid ego Judǽus sum? Gens tua et pontífices tradidérunt te mihi: quid fecísti? Respóndit Jesus: Regnum meum non est de hoc mundo. Si ex hoc mundo esset regnum meum, minístri mei útique decertárent, ut non tráderer Judǽis: nunc autem regnum meum non est hinc. Dixit ítaque ei Pilátus: Ergo Rex es tu? Respóndit Jesus: Tu dicis, quia Rex sum ego. Ego in hoc natus sum et ad hoc veni in mundum, ut testimónium perhíbeam veritáti: omnis, qui est ex veritáte, audit vocem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 18:33-37\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Pilatos a Jesus: «Tu és o rei dos Judeus?». Respondeu Jesus: «Tu dizes isso de ti mesmo, ou foram outros que to disseram de mim?». Respondeu Pilatos: «Sou, porventura, judeu? Foram os teus compatriotas e os pontífices que te entregaram nas minhas mãos. O que fizeste?». Jesus respondeu: «Meu reino não é deste mundo. Se o meu reino fosse deste mundo, certamente os meus ministros haviam de pelejar para que Eu não fosse entregue aos judeus; porém, Eu o declaro agora, o meu reino não é daqui». Disse-Lhe, então, Pilatos: «És, portanto, rei?». Jesus respondeu: «Tu dizes que Eu sou rei. Eu para isso nasci e para isso vim a este mundo, a fim de dar testemunho da verdade. Todo aquele que é da verdade, escuta a minha voz».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 2:8.\u003c/I>\u003c/FONT>\u003cbr/>\nPóstula a me, et dabo tibi gentes hereditátem tuam, et possessiónem tuam términos terræ.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 2:8\u003c/I>\u003c/FONT>\u003cbr/>\nPede-me: e dar-te-ei as nações como herança; e como domínio os confins da terra!\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHóstiam tibi, Dómine, humánæ reconciliatiónis offérimus: præsta, quǽsumus; ut, quem sacrifíciis præséntibus immolámus, ipse cunctis géntibus unitátis et pacis dona concédat, Jesus Christus Fílius tuus, Dóminus noster:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nVos oferecemos, Senhor, a hóstia da reconciliação humana, implorando-Vos que este mesmo Jesus Cristo, vosso Filho e Senhor nosso, o qual imolamos no presente sacrifício, conceda a todos os povos os benefícios da união e da paz:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de D.N. Jesu Christi Rege\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui unigénitum Fílium tuum, Dóminum nostrum Jesum Christum, Sacerdótem ætérnum et universórum Regem, óleo exsultatiónis unxísti: ut, seípsum in ara crucis hóstiam immaculátam et pacíficam ófferens, redemptiónis humánæ sacraménta perágeret: et suo subjéctis império ómnibus creatúris, ætérnum et universále regnum, imménsæ tuæ tráderet Majestáti. Regnum veritátis et vitæ: regnum sanctitátis et grátiæ: regnum justítiæ, amóris et pacis. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> de Nosso Senhor Jesus Cristo-Rei\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar dar-Vos graças em todos os lugares e sempre, Senhor santo, Pai omnipotente, eterno Deus, que ungistes com o óleo da alegria o vosso Filho Unigénito, Nosso Senhor Jesus Cristo, como Sacerdote eterno e Rei de todas as cousas, a fim de que, oferecendo-se na ara da Cruz - qual hóstia imaculada e pacífica -, realizasse as maravilhas da redenção humana e, ficando todas as criaturas sujeitas aoseu império, desse à vossa imensa majestade um reino eterno e universal: um reino de verdade e de vida; um reino de santidade e de graça; um reino de justiça, de amor e de paz. E por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos um hino à vossa glória, dizendo incessantemente:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 28:10; 28:11\u003c/I>\u003c/FONT>\u003cbr/>\nSedébit Dóminus Rex in ætérnum: Dóminus benedícet pópulo suo in pace.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 28:10; 28:11\u003c/I>\u003c/FONT>\u003cbr/>\nAssentar-se-á, eternamente, o Senhor como Rei e abençoará o seu povo em paz.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nImmortalitátis alimóniam consecúti, quǽsumus, Dómine: ut, qui sub Christi Regis vexíllis militáre gloriámur, cum ipso, in cœlésti sede, júgiter regnáre possímus:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nTendo nós alcançado o alimento da imortalidade, Vos suplicamos, Senhor, permiti que possamos reinar perpetuamente na celestial mansão, juntamente com Jesus Cristo, sob cujas bandeiras nos gloriamos de militar:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-26":{"date":"2026-10-26","title":"Féria da 22ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Secunda infra Hebdomadam XXII post Octavam Pentecostes V. Octobris\tFeria","winner":"Tempora/Pent22-1.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:3-4\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi vocem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:3-4\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e atenderdes às nossas iniquidades, Senhor, Senhor, quem poderá subsistir diante de Vós? Sois cheio de misericórdia, ó Deus de Israel!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos, Senhor, clamei por Vós: ouvi, pois, a minha oração, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e atenderdes às nossas iniquidades, Senhor, Senhor, quem poderá subsistir diante de Vós? Sois cheio de misericórdia, ó Deus de Israel!\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, refúgium nostrum et virtus: adésto piis Ecclésiæ tuæ précibus, auctor ipse pietátis, et præsta; ut, quod fidéliter pétimus, efficáciter consequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Evaristi Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>G\u003c/I>\u003c/B>\u003c/FONT>regem tuum, Pastor ætérne, placátus inténde: et, per beátum Evarístum Mártyrem tuum atque Summum Pontíficem, perpétua protectióne custódi; quem totíus Ecclésiæ præstitísti esse pastórem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, nosso refúgio e fortaleza, que sois a origem de toda a piedade, ouvi benigno as piedosas preces da vossa Igreja e concedei-nos a graça de alcançarmos com eficácia o que com fé Vos suplicamos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Evaristi Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Pastor eterno, atendei propício ao vosso rebanho; e guardai-o com vossa perpétua protecção por intercessão do bem-aventurado Evarístum Vosso Mártir e Sumo Pontífice, o qual escolhestes como pastor de toda a Igreja.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Philippénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Phil 1:6-11\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Confídimus in Dómino Jesu, quia, qui cœpit in vobis opus bonum, perfíciet usque in diem Christi Jesu. Sicut est mihi justum hoc sentíre pro ómnibus vobis: eo quod hábeam vos in corde, et in vínculis meis, et in defensióne, et confirmatióne Evangélii, sócios gáudii mei omnes vos esse. Testis enim mihi est Deus, quómodo cúpiam omnes vos in viscéribus Jesu Christi. Et hoc oro, ut cáritas vestra magis ac magis abúndet in sciéntia et in omni sensu: ut probétis potióra, ut sitis sincéri et sine offénsa in diem Christi, repléti fructu justítiæ per Jesum Christum, in glóriam et laudem Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Filipenses.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Fl 1:6-11\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Tenho firme confiança de que aquele que começou em vós o bom trabalho há-de continuá-lo até ao dia de Jesus Cristo. Justo é que assim pense de vós, porque sinto no coração que comparticipais da minha alegria, quer seja nas minhas prisões, quer na defesa e confirmação do Evangelho. Deus é testemunha do modo como vos amo a todos, no afecto íntimo de Jesus Cristo. Rogo-lhe que a vossa caridade cresça cada vez mais em luz e inteligência, a fim de que possais distinguir aquilo que é melhor, para serdes puros e sem mancha até ao dia de Cristo e cheios dos frutos da justiça por Jesus Cristo, em louvor e glória de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 132:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nEcce, quam bonum et quam jucúndum, habitáre fratres in unum!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Sicut unguéntum in cápite, quod descéndit in barbam, barbam Aaron.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 113:11\u003c/I>\u003c/FONT>\u003cbr/>\nQui timent Dóminum sperent in eo: adjútor et protéctor eórum est. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 132:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nOh! Como é bom e suave aos irmãos habitarem juntos!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> É como o perfume espalhado pela cabeça que desce por toda a barba, por toda a barba de Aarão!\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 22:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Abeúntes pharisǽi consílium iniérunt, ut cáperent Jesum in sermóne. Et mittunt ei discípulos suos cum Herodiánis, dicéntes: Magíster, scimus, quia verax es et viam Dei in veritáte doces, et non est tibi cura de áliquo: non enim réspicis persónam hóminum: dic ergo nobis, quid tibi vidétur, licet censum dare Cǽsari, an non? Cógnita autem Jesus nequítia eórum, ait: Quid me tentátis, hypócritæ? Osténdite mihi numísma census. At illi obtulérunt ei denárium. Et ait illis Jesus: Cujus est imágo hæc et superscríptio? Dicunt ei: Cǽsaris. Tunc ait illis: Réddite ergo, quæ sunt Cǽsaris, Cǽsari; et, quæ sunt Dei, Deo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 22:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, retirando-se os fariseus, combinaram em conselho surpreender Jesus nas suas palavras, para O acusarem. Mandaram-Lhe, pois, os seus discípulos com os herodianos, que Lhe disseram: «Mestre, sabemos que sois verdadeiro e que ensinais o caminho de Deus com verdade, sem vos preocupardes com quem quer que seja, pois não olhais à situação das pessoas. Dizei-nos, portanto, o que Vos parece a este respeito: É lícito pagar ou não o tributo a César?». Jesus, conhecendo a sua malícia, respondeu-lhes: «Hipócritas, porque me tentais? Mostrai-me a moeda do tributo». Apresentaram-Lhe um dinheiro. Então Jesus continuou: «De quem é esta imagem e esta inscrição?». Responderam eles: «De César». E Jesus continuou: «Dai, portanto, a César o que pertence a César, e dai a Deus o que a Deus pertence».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 14:12; 14:13\u003c/I>\u003c/FONT>\u003cbr/>\nRecordáre mei, Dómine, omni potentátui dóminans: et da sermónem rectum in os meum, ut pláceant verba mea in conspéctu príncipis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ester 14:12-13\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, que estais acima de todo o poder, lembrai-Vos de mim: inspirai aos meus lábios palavras justas, para que sejam agradáveis ao príncipe.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDa, miséricors Deus: ut hæc salutáris oblátio et a própriis nos reátibus indesinénter expédiat, et ab ómnibus tueátur advérsis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Evaristi Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>blátis munéribus, quǽsumus, Dómine, Ecclésiam tuam benígnus illúmina: ut, et gregis tui profíciat ubíque succéssus, et grati fiant nómini tuo, te gubernánte, pastóres.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPermiti, ó Deus de misericórdia, que esta salutar oblação nos livre inteiramente dos laços das nossas próprias faltas e nos defenda de todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Evaristi Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>om as ofertas destes dons, Vos suplicamos, Senhor, iluminai benignamente a vossa Igreja, a fim de que não só o vosso rebanho triunfe em toda a parte, mas também pelo poder do vosso nome os pastores sejam bem acolhidos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 16:6\u003c/I>\u003c/FONT>\u003cbr/>\nEgo clamávi, quóniam exaudísti me, Deus: inclína aurem tuam et exáudi verba mea.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 16:6\u003c/I>\u003c/FONT>\u003cbr/>\nÓ Deus, clamei por Vós, porque me ouvistes: inclinai os vossos ouvidos para mim e ouvi as minhas súplicas.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSúmpsimus, Dómine, sacri dona mystérii, humíliter deprecántes: ut, quæ in tui commemoratiónem nos fácere præcepísti, in nostræ profíciant infirmitátis auxílium:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Evaristi Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>efectióne sancta enutrítam gubérna, quǽsumus, Dómine, tuam placátus Ecclésiam: ut, poténti moderatióne dirécta, et increménta libertátis accípiat et in religiónis integritáte persístat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido os sacrossantos dons deste mystério, Senhor, humildemente Vos imploramos que este sacrifício, que nos mandastes celebrar em vossa memória, sirva de auxílio à nossa fraqueza.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Evaristi Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, Vos suplicamos, governai com mansidão a vossa Igreja, agora que foi alimentada com a sagrada refeição, a fim de que, dirigida com firme suavidade, alcance o incremento da sua liberdade e persista na integridade da sua doutrina.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-27":{"date":"2026-10-27","title":"Féria da 22ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Tertia infra Hebdomadam XXII post Octavam Pentecostes V. Octobris\tFeria","winner":"Tempora/Pent22-2.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:3-4\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi vocem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:3-4\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e atenderdes às nossas iniquidades, Senhor, Senhor, quem poderá subsistir diante de Vós? Sois cheio de misericórdia, ó Deus de Israel!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos, Senhor, clamei por Vós: ouvi, pois, a minha oração, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e atenderdes às nossas iniquidades, Senhor, Senhor, quem poderá subsistir diante de Vós? Sois cheio de misericórdia, ó Deus de Israel!\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, refúgium nostrum et virtus: adésto piis Ecclésiæ tuæ précibus, auctor ipse pietátis, et præsta; ut, quod fidéliter pétimus, efficáciter consequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, nosso refúgio e fortaleza, que sois a origem de toda a piedade, ouvi benigno as piedosas preces da vossa Igreja e concedei-nos a graça de alcançarmos com eficácia o que com fé Vos suplicamos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Philippénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Phil 1:6-11\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Confídimus in Dómino Jesu, quia, qui cœpit in vobis opus bonum, perfíciet usque in diem Christi Jesu. Sicut est mihi justum hoc sentíre pro ómnibus vobis: eo quod hábeam vos in corde, et in vínculis meis, et in defensióne, et confirmatióne Evangélii, sócios gáudii mei omnes vos esse. Testis enim mihi est Deus, quómodo cúpiam omnes vos in viscéribus Jesu Christi. Et hoc oro, ut cáritas vestra magis ac magis abúndet in sciéntia et in omni sensu: ut probétis potióra, ut sitis sincéri et sine offénsa in diem Christi, repléti fructu justítiæ per Jesum Christum, in glóriam et laudem Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Filipenses.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Fl 1:6-11\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Tenho firme confiança de que aquele que começou em vós o bom trabalho há-de continuá-lo até ao dia de Jesus Cristo. Justo é que assim pense de vós, porque sinto no coração que comparticipais da minha alegria, quer seja nas minhas prisões, quer na defesa e confirmação do Evangelho. Deus é testemunha do modo como vos amo a todos, no afecto íntimo de Jesus Cristo. Rogo-lhe que a vossa caridade cresça cada vez mais em luz e inteligência, a fim de que possais distinguir aquilo que é melhor, para serdes puros e sem mancha até ao dia de Cristo e cheios dos frutos da justiça por Jesus Cristo, em louvor e glória de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 132:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nEcce, quam bonum et quam jucúndum, habitáre fratres in unum!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Sicut unguéntum in cápite, quod descéndit in barbam, barbam Aaron.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 113:11\u003c/I>\u003c/FONT>\u003cbr/>\nQui timent Dóminum sperent in eo: adjútor et protéctor eórum est. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 132:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nOh! Como é bom e suave aos irmãos habitarem juntos!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> É como o perfume espalhado pela cabeça que desce por toda a barba, por toda a barba de Aarão!\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 22:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Abeúntes pharisǽi consílium iniérunt, ut cáperent Jesum in sermóne. Et mittunt ei discípulos suos cum Herodiánis, dicéntes: Magíster, scimus, quia verax es et viam Dei in veritáte doces, et non est tibi cura de áliquo: non enim réspicis persónam hóminum: dic ergo nobis, quid tibi vidétur, licet censum dare Cǽsari, an non? Cógnita autem Jesus nequítia eórum, ait: Quid me tentátis, hypócritæ? Osténdite mihi numísma census. At illi obtulérunt ei denárium. Et ait illis Jesus: Cujus est imágo hæc et superscríptio? Dicunt ei: Cǽsaris. Tunc ait illis: Réddite ergo, quæ sunt Cǽsaris, Cǽsari; et, quæ sunt Dei, Deo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 22:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, retirando-se os fariseus, combinaram em conselho surpreender Jesus nas suas palavras, para O acusarem. Mandaram-Lhe, pois, os seus discípulos com os herodianos, que Lhe disseram: «Mestre, sabemos que sois verdadeiro e que ensinais o caminho de Deus com verdade, sem vos preocupardes com quem quer que seja, pois não olhais à situação das pessoas. Dizei-nos, portanto, o que Vos parece a este respeito: É lícito pagar ou não o tributo a César?». Jesus, conhecendo a sua malícia, respondeu-lhes: «Hipócritas, porque me tentais? Mostrai-me a moeda do tributo». Apresentaram-Lhe um dinheiro. Então Jesus continuou: «De quem é esta imagem e esta inscrição?». Responderam eles: «De César». E Jesus continuou: «Dai, portanto, a César o que pertence a César, e dai a Deus o que a Deus pertence».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 14:12; 14:13\u003c/I>\u003c/FONT>\u003cbr/>\nRecordáre mei, Dómine, omni potentátui dóminans: et da sermónem rectum in os meum, ut pláceant verba mea in conspéctu príncipis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ester 14:12-13\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, que estais acima de todo o poder, lembrai-Vos de mim: inspirai aos meus lábios palavras justas, para que sejam agradáveis ao príncipe.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDa, miséricors Deus: ut hæc salutáris oblátio et a própriis nos reátibus indesinénter expédiat, et ab ómnibus tueátur advérsis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPermiti, ó Deus de misericórdia, que esta salutar oblação nos livre inteiramente dos laços das nossas próprias faltas e nos defenda de todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 16:6\u003c/I>\u003c/FONT>\u003cbr/>\nEgo clamávi, quóniam exaudísti me, Deus: inclína aurem tuam et exáudi verba mea.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 16:6\u003c/I>\u003c/FONT>\u003cbr/>\nÓ Deus, clamei por Vós, porque me ouvistes: inclinai os vossos ouvidos para mim e ouvi as minhas súplicas.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSúmpsimus, Dómine, sacri dona mystérii, humíliter deprecántes: ut, quæ in tui commemoratiónem nos fácere præcepísti, in nostræ profíciant infirmitátis auxílium:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido os sacrossantos dons deste mystério, Senhor, humildemente Vos imploramos que este sacrifício, que nos mandastes celebrar em vossa memória, sirva de auxílio à nossa fraqueza.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-28":{"date":"2026-10-28","title":"Santos Simão e Judas Tadeu, apóstolos","forms":[{"number":1,"title":"Ss. Simonis et Judæ Apostolorum Duplex 2 classis ex Commune Apostolorum [Commune/C1.txt]","winner":"Sancti/10-28.txt","rule":"ex C1;\nGloria\nCredo\nPrefatio=Apostolis\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 138:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>ihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 138:1-2.\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>ihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 138:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT>u vejo, ó Deus, que honrais largamente os vossos amigos: e que seu poder se tem fortalecido extraordinariamente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 138:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, perscrutastes o meu íntimo e ficastes conhecendo-me: ficastes conhecendo quando me deito e me levanto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT>u vejo, ó Deus, que honrais largamente os vossos amigos: e que seu poder se tem fortalecido extraordinariamente.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui nos per beátos Apóstolos tuos Simónem et Judam ad agnitiónem tui nóminis veníre tribuísti: da nobis eórum glóriam sempitérnam et proficiéndo celebráre, et celebrándo profícere.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que pelos vossos B. B. Apóstolos Simão e Judas nos proporcionastes o conhecimento do vosso Nome, concedei-nos a graça de celebrar a sua eterna glória, progredindo na virtude, e celebrando esta mesma glória, alcancemos novos progressos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Ephésios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eph 4:7-13\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Unicuíque nostrum data est grátia secúndum mensúram donatiónis Christi. Propter quod dicit: Ascéndens in altum, captívam duxit captivitátem: dedit dona homínibus. Quod autem ascéndit, quid est, nisi quia et descéndit primum in inferióres partes terræ? Qui descéndit, ipse est et qui ascéndit super omnes cœlos, ut impléret ómnia. Et ipse dedit quosdam quidem apóstolos, quosdam autem prophétas, álios vero evangelístas, álios autem pastóres et doctóres, ad consummatiónem sanctórum in opus ministérii, in ædificatiónem córporis Christi: donec occurrámus omnes in unitátem fídei, et agnitiónis Fílii Dei, in virum perféctum, in mensúram ætátis plenitúdinis Christi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Efésios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ef 4:7-13\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: A graça é dada a cada um de nós, segundo a medida do dom de Cristo. Por isso se diz na Escritura: «Subindo ao alto, levou consigo os cativos e repartiu os seus dons pelos homens». Que quer dizer «subiu» senão que, antes, tinha descido às regiões inferiores da terra? Aquele que desceu é o mesmo que subiu acima de todos os céus, a fim de completar todas as cousas. Foi Ele, também, quem deu à sua Igreja uns como Apóstolos, outros como Profetas, outros como Evangelistas, outros como Pastores e Doutores, para que uns e outros trabalhem para a perfeição dos santos, nas funções do ministério e na edificação do corpo de Cristo, até que todos cheguemos à unidade de uma só fé e do mesmo conhecimento do Filho de Deus, ao estado de um homem perfeito a um desenvolvimento orgânico proporcionado à plenitude de Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:17-18\u003c/I>\u003c/FONT>\u003cbr/>\nConstítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Pro pátribus tuis nati sunt tibi fílii: proptérea pópuli confitebúntur tibi. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 138:17\u003c/I>\u003c/FONT>\u003cbr/>\nNimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:17-18\u003c/I>\u003c/FONT>\u003cbr/>\nVós os instituístes príncipes em todo o universo: e eles, Senhor, perpetuarão a glória do vosso nome em toda a terra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Para substituir os vossos pais, nascer-vos-ão filhos: pelo que os povos vos louvarão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 138:17\u003c/I>\u003c/FONT>\u003cbr/>\nHonrais largamente os vossos filhos, ó Deus; o seu poder tem-se fortalecido extraordinariamente. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 15:17-25\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Hæc mando vobis, ut diligátis ínvicem. Si mundus vos odit: scitóte, quia me priórem vobis odio hábuit. Si de mundo fuissétis, mundus quod suum erat dilígeret; quia vero de mundo non estis, sed ego elegi vos de mundo, proptérea odit vos mundus. Mementóte sermónis mei, quem ego dixi vobis: Non est servus major dómino suo. Si me persecúti sunt, et vos persequántur: si sermónem meum servavérunt, et vestrum servábunt. Sed hæc ómnia fácient vobis propter nomen meum: quia nésciunt eum, qui misit me. Si non veníssem et locútus fuíssem eis, peccátum non háberent: nunc autem excusatiónem non habent de peccáto suo. Qui me odit: et Patrem meum odit. Si ópera non fecíssem in eis, quæ nemo álius fecit, peccátum non háberent: nunc autem et vidérunt et odérunt et me et Patrem meum. Sed ut adimpleátur sermo, qui in lege eórum scriptus est: Quia ódio habuérunt me gratis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 15:17-25\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Recomendo-vos que vos ameis uns aos outros. Se o mundo vos odeia, lembrai-vos de que me odiou a mim antes. Se fôsseis do mundo, o mundo amaria o que lhe pertenceria; mas, como não sois do mundo e Eu vos escolhi do mundo, por isso ele vos odiará. Lembrai-vos de que vos disse: «O servo mais não é do que o senhor». Se, pois, me perseguiram, perseguir-vos-ão, também; se guardaram as minhas palavras, guardarão também as vossas. Farão todas estas cousas por causa do meu nome, porque não conhecem Aquele que me mandou. Se não tivesse vindo e lhes não houvesse falado, não seriam culpados; mas agora não têm desculpa do seu pecado. Quem me odeia, odeia também meu Pai. Se Eu no meio de vós não houvesse praticado obras, que ninguém pratica, não teriam pecado; porém, as viram e me odeiam, bem como a meu Pai. Assim se cumpre neles aquela sentença que está escrita na sua lei: «Odiaram-me sem motivo algum».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 18:5\u003c/I>\u003c/FONT>\u003cbr/>\nIn omnem terram exívit sonus eórum: et in fines orbis terræ verba eórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 18:5\u003c/I>\u003c/FONT>\u003cbr/>\nO som da sua voz ecoou por toda a parte, e as suas palavras estenderam-se até às extremidades da terra.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nGlóriam, Dómine, sanctórum Apostolórum tuórum Simónis et Judæ perpétuam venerántes: quǽsumus; ut eam, sacris mystériis expiati, dígnius celebrémus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nVenerando nós, Senhor, a perpétua glória dos vossos Santos Apóstolos Simão e Judas, purificai-nos, Vos imploramos, por estes sacrossantos mystérios, a fim de que os celebremos mais dignamente.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Apostolis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre: Te, Dómine, supplíciter exoráre, ut gregem tuum, Pastor ætérne, non déseras: sed per beátos Apóstolos tuos contínua protectióne custódias. Ut iísdem rectóribus gubernétur, quos óperis tui vicários eídem contulísti præésse pastóres. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Apóstolos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar suplicar-Vos humildemente, Senhor, que, como Pastor eterno, que sois, não abandoneis o vosso rebanho, mas antes, por intercessão dos vossos bem-aventurados Apóstolos, o guardeis sob a vossa perpétua protecção, a fim de que seja sempre governado pelos mesmos Directores, que, encarregados como Vigários de perpetuar a vossa obra, designastes seus Pastores. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos um hino à vossa glória, dizendo incessantemente:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 19:28\u003c/I>\u003c/FONT>\u003cbr/>\nVos, qui secúti estis me, sedébitis super sedes, judicántes duódecim tribus Israël.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 19:28\u003c/I>\u003c/FONT>\u003cbr/>\nVós, que me seguistes, assentar-vos-eis sobre tronos e julgareis as doze tribos de Israel.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPercéptis, Dómine, sacraméntis, supplíciter exorámus: ut, intercedéntibus beátis Apóstolis tuis Simóne et Juda, quæ pro illórum veneránda gérimus passióne, nobis profíciant ad medélam.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo participado destes sacramentos, Vos pedimos humildemente, Senhor, que pela intercessão dos vossos B. B. Apóstolos Simão e Judas, o mystério que celebramos em honra do seu martírio, nos sirva de remédio para os nossos males.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-29":{"date":"2026-10-29","title":"Féria da 22ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Quinta infra Hebdomadam XXII post Octavam Pentecostes V. Octobris\tFeria","winner":"Tempora/Pent22-4.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:3-4\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi vocem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:3-4\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e atenderdes às nossas iniquidades, Senhor, Senhor, quem poderá subsistir diante de Vós? Sois cheio de misericórdia, ó Deus de Israel!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos, Senhor, clamei por Vós: ouvi, pois, a minha oração, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e atenderdes às nossas iniquidades, Senhor, Senhor, quem poderá subsistir diante de Vós? Sois cheio de misericórdia, ó Deus de Israel!\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, refúgium nostrum et virtus: adésto piis Ecclésiæ tuæ précibus, auctor ipse pietátis, et præsta; ut, quod fidéliter pétimus, efficáciter consequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, nosso refúgio e fortaleza, que sois a origem de toda a piedade, ouvi benigno as piedosas preces da vossa Igreja e concedei-nos a graça de alcançarmos com eficácia o que com fé Vos suplicamos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Philippénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Phil 1:6-11\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Confídimus in Dómino Jesu, quia, qui cœpit in vobis opus bonum, perfíciet usque in diem Christi Jesu. Sicut est mihi justum hoc sentíre pro ómnibus vobis: eo quod hábeam vos in corde, et in vínculis meis, et in defensióne, et confirmatióne Evangélii, sócios gáudii mei omnes vos esse. Testis enim mihi est Deus, quómodo cúpiam omnes vos in viscéribus Jesu Christi. Et hoc oro, ut cáritas vestra magis ac magis abúndet in sciéntia et in omni sensu: ut probétis potióra, ut sitis sincéri et sine offénsa in diem Christi, repléti fructu justítiæ per Jesum Christum, in glóriam et laudem Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Filipenses.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Fl 1:6-11\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Tenho firme confiança de que aquele que começou em vós o bom trabalho há-de continuá-lo até ao dia de Jesus Cristo. Justo é que assim pense de vós, porque sinto no coração que comparticipais da minha alegria, quer seja nas minhas prisões, quer na defesa e confirmação do Evangelho. Deus é testemunha do modo como vos amo a todos, no afecto íntimo de Jesus Cristo. Rogo-lhe que a vossa caridade cresça cada vez mais em luz e inteligência, a fim de que possais distinguir aquilo que é melhor, para serdes puros e sem mancha até ao dia de Cristo e cheios dos frutos da justiça por Jesus Cristo, em louvor e glória de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 132:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nEcce, quam bonum et quam jucúndum, habitáre fratres in unum!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Sicut unguéntum in cápite, quod descéndit in barbam, barbam Aaron.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 113:11\u003c/I>\u003c/FONT>\u003cbr/>\nQui timent Dóminum sperent in eo: adjútor et protéctor eórum est. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 132:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nOh! Como é bom e suave aos irmãos habitarem juntos!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> É como o perfume espalhado pela cabeça que desce por toda a barba, por toda a barba de Aarão!\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 22:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Abeúntes pharisǽi consílium iniérunt, ut cáperent Jesum in sermóne. Et mittunt ei discípulos suos cum Herodiánis, dicéntes: Magíster, scimus, quia verax es et viam Dei in veritáte doces, et non est tibi cura de áliquo: non enim réspicis persónam hóminum: dic ergo nobis, quid tibi vidétur, licet censum dare Cǽsari, an non? Cógnita autem Jesus nequítia eórum, ait: Quid me tentátis, hypócritæ? Osténdite mihi numísma census. At illi obtulérunt ei denárium. Et ait illis Jesus: Cujus est imágo hæc et superscríptio? Dicunt ei: Cǽsaris. Tunc ait illis: Réddite ergo, quæ sunt Cǽsaris, Cǽsari; et, quæ sunt Dei, Deo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 22:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, retirando-se os fariseus, combinaram em conselho surpreender Jesus nas suas palavras, para O acusarem. Mandaram-Lhe, pois, os seus discípulos com os herodianos, que Lhe disseram: «Mestre, sabemos que sois verdadeiro e que ensinais o caminho de Deus com verdade, sem vos preocupardes com quem quer que seja, pois não olhais à situação das pessoas. Dizei-nos, portanto, o que Vos parece a este respeito: É lícito pagar ou não o tributo a César?». Jesus, conhecendo a sua malícia, respondeu-lhes: «Hipócritas, porque me tentais? Mostrai-me a moeda do tributo». Apresentaram-Lhe um dinheiro. Então Jesus continuou: «De quem é esta imagem e esta inscrição?». Responderam eles: «De César». E Jesus continuou: «Dai, portanto, a César o que pertence a César, e dai a Deus o que a Deus pertence».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 14:12; 14:13\u003c/I>\u003c/FONT>\u003cbr/>\nRecordáre mei, Dómine, omni potentátui dóminans: et da sermónem rectum in os meum, ut pláceant verba mea in conspéctu príncipis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ester 14:12-13\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, que estais acima de todo o poder, lembrai-Vos de mim: inspirai aos meus lábios palavras justas, para que sejam agradáveis ao príncipe.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDa, miséricors Deus: ut hæc salutáris oblátio et a própriis nos reátibus indesinénter expédiat, et ab ómnibus tueátur advérsis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPermiti, ó Deus de misericórdia, que esta salutar oblação nos livre inteiramente dos laços das nossas próprias faltas e nos defenda de todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 16:6\u003c/I>\u003c/FONT>\u003cbr/>\nEgo clamávi, quóniam exaudísti me, Deus: inclína aurem tuam et exáudi verba mea.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 16:6\u003c/I>\u003c/FONT>\u003cbr/>\nÓ Deus, clamei por Vós, porque me ouvistes: inclinai os vossos ouvidos para mim e ouvi as minhas súplicas.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSúmpsimus, Dómine, sacri dona mystérii, humíliter deprecántes: ut, quæ in tui commemoratiónem nos fácere præcepísti, in nostræ profíciant infirmitátis auxílium:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido os sacrossantos dons deste mystério, Senhor, humildemente Vos imploramos que este sacrifício, que nos mandastes celebrar em vossa memória, sirva de auxílio à nossa fraqueza.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-30":{"date":"2026-10-30","title":"Féria da 22ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Sexta infra Hebdomadam XXII post Octavam Pentecostes V. Octobris\tFeria","winner":"Tempora/Pent22-5.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:3-4\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi vocem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:3-4\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e atenderdes às nossas iniquidades, Senhor, Senhor, quem poderá subsistir diante de Vós? Sois cheio de misericórdia, ó Deus de Israel!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos, Senhor, clamei por Vós: ouvi, pois, a minha oração, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e atenderdes às nossas iniquidades, Senhor, Senhor, quem poderá subsistir diante de Vós? Sois cheio de misericórdia, ó Deus de Israel!\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, refúgium nostrum et virtus: adésto piis Ecclésiæ tuæ précibus, auctor ipse pietátis, et præsta; ut, quod fidéliter pétimus, efficáciter consequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, nosso refúgio e fortaleza, que sois a origem de toda a piedade, ouvi benigno as piedosas preces da vossa Igreja e concedei-nos a graça de alcançarmos com eficácia o que com fé Vos suplicamos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Philippénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Phil 1:6-11\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Confídimus in Dómino Jesu, quia, qui cœpit in vobis opus bonum, perfíciet usque in diem Christi Jesu. Sicut est mihi justum hoc sentíre pro ómnibus vobis: eo quod hábeam vos in corde, et in vínculis meis, et in defensióne, et confirmatióne Evangélii, sócios gáudii mei omnes vos esse. Testis enim mihi est Deus, quómodo cúpiam omnes vos in viscéribus Jesu Christi. Et hoc oro, ut cáritas vestra magis ac magis abúndet in sciéntia et in omni sensu: ut probétis potióra, ut sitis sincéri et sine offénsa in diem Christi, repléti fructu justítiæ per Jesum Christum, in glóriam et laudem Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Filipenses.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Fl 1:6-11\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Tenho firme confiança de que aquele que começou em vós o bom trabalho há-de continuá-lo até ao dia de Jesus Cristo. Justo é que assim pense de vós, porque sinto no coração que comparticipais da minha alegria, quer seja nas minhas prisões, quer na defesa e confirmação do Evangelho. Deus é testemunha do modo como vos amo a todos, no afecto íntimo de Jesus Cristo. Rogo-lhe que a vossa caridade cresça cada vez mais em luz e inteligência, a fim de que possais distinguir aquilo que é melhor, para serdes puros e sem mancha até ao dia de Cristo e cheios dos frutos da justiça por Jesus Cristo, em louvor e glória de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 132:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nEcce, quam bonum et quam jucúndum, habitáre fratres in unum!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Sicut unguéntum in cápite, quod descéndit in barbam, barbam Aaron.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 113:11\u003c/I>\u003c/FONT>\u003cbr/>\nQui timent Dóminum sperent in eo: adjútor et protéctor eórum est. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 132:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nOh! Como é bom e suave aos irmãos habitarem juntos!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> É como o perfume espalhado pela cabeça que desce por toda a barba, por toda a barba de Aarão!\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 22:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Abeúntes pharisǽi consílium iniérunt, ut cáperent Jesum in sermóne. Et mittunt ei discípulos suos cum Herodiánis, dicéntes: Magíster, scimus, quia verax es et viam Dei in veritáte doces, et non est tibi cura de áliquo: non enim réspicis persónam hóminum: dic ergo nobis, quid tibi vidétur, licet censum dare Cǽsari, an non? Cógnita autem Jesus nequítia eórum, ait: Quid me tentátis, hypócritæ? Osténdite mihi numísma census. At illi obtulérunt ei denárium. Et ait illis Jesus: Cujus est imágo hæc et superscríptio? Dicunt ei: Cǽsaris. Tunc ait illis: Réddite ergo, quæ sunt Cǽsaris, Cǽsari; et, quæ sunt Dei, Deo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 22:15-21\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, retirando-se os fariseus, combinaram em conselho surpreender Jesus nas suas palavras, para O acusarem. Mandaram-Lhe, pois, os seus discípulos com os herodianos, que Lhe disseram: «Mestre, sabemos que sois verdadeiro e que ensinais o caminho de Deus com verdade, sem vos preocupardes com quem quer que seja, pois não olhais à situação das pessoas. Dizei-nos, portanto, o que Vos parece a este respeito: É lícito pagar ou não o tributo a César?». Jesus, conhecendo a sua malícia, respondeu-lhes: «Hipócritas, porque me tentais? Mostrai-me a moeda do tributo». Apresentaram-Lhe um dinheiro. Então Jesus continuou: «De quem é esta imagem e esta inscrição?». Responderam eles: «De César». E Jesus continuou: «Dai, portanto, a César o que pertence a César, e dai a Deus o que a Deus pertence».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Esth 14:12; 14:13\u003c/I>\u003c/FONT>\u003cbr/>\nRecordáre mei, Dómine, omni potentátui dóminans: et da sermónem rectum in os meum, ut pláceant verba mea in conspéctu príncipis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ester 14:12-13\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, que estais acima de todo o poder, lembrai-Vos de mim: inspirai aos meus lábios palavras justas, para que sejam agradáveis ao príncipe.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDa, miséricors Deus: ut hæc salutáris oblátio et a própriis nos reátibus indesinénter expédiat, et ab ómnibus tueátur advérsis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPermiti, ó Deus de misericórdia, que esta salutar oblação nos livre inteiramente dos laços das nossas próprias faltas e nos defenda de todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 16:6\u003c/I>\u003c/FONT>\u003cbr/>\nEgo clamávi, quóniam exaudísti me, Deus: inclína aurem tuam et exáudi verba mea.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 16:6\u003c/I>\u003c/FONT>\u003cbr/>\nÓ Deus, clamei por Vós, porque me ouvistes: inclinai os vossos ouvidos para mim e ouvi as minhas súplicas.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSúmpsimus, Dómine, sacri dona mystérii, humíliter deprecántes: ut, quæ in tui commemoratiónem nos fácere præcepísti, in nostræ profíciant infirmitátis auxílium:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido os sacrossantos dons deste mystério, Senhor, humildemente Vos imploramos que este sacrifício, que nos mandastes celebrar em vossa memória, sirva de auxílio à nossa fraqueza.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-10-31":{"date":"2026-10-31","title":"Ofício de Nossa Senhora no sábado","forms":[{"number":1,"title":"Sanctæ Mariæ Sabbato\tSimplex vide  [Commune/C10.txt]","winner":"Commune/C10.txt","rule":"vide C10\nSpecial Benedictio\nSpecial Lectio 3\nDoxology=Nat\nAntiphonas horas\nGloria\nSuffr=Spiritu;Ecclesiæ,Papa;;\nPrefatio=Maria=veneratione;\n\nex C10","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: Consagro ao Rei as minhas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nConcéde nos fámulos tuos, quǽsumus, Dómine Deus, perpétua mentis et córporis sanitáte gaudére: et, gloriósa beátæ Maríæ semper Vírginis intercessióne, a præsénti liberári tristítia, et ætérna pérfrui lætítia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nConcedei aos vossos servos, Senhor Deus, Vos suplicamos, o gozo da perpétua saúde da alma e do corpo, e que pela gloriosa intercessão da B. Maria, sempre Virgem, sejamos livres das tristezas dos tempos presentes e alcancemos o gozo da eterna alegria.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nAb inítio et ante sǽcula creáta sum, et usque ad futúrum sǽculum non désinam, et in habitatióne sancta coram ipso ministrávi. Et sic in Sion firmáta sum, et in civitáte sanctificáta simíliter requiévi, et in Jerúsalem potéstas mea. Et radicávi in pópulo honorificáto, et in parte Dei mei heréditas illíus, et in plenitúdine sanctórum deténtio mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nFui criada desde o princípio, antes de todos os séculos, e não deixarei de existir até à eternidade. Exerci perante Ele o meu ministério; e deste modo tenho habitação fixa em Sião. Ele deixa-me descansar na cidade santa e tenho poder em Jerusalém. Arraiguei-me em um povo glorioso, da parte do meu Deus e da sua herança, e permaneço na companhia dos santos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBenedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Post partum, Virgo, invioláta permansísti: Dei Génetrix, intercéde pro nobis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBendita e venerável sois vós, ó Virgem Maria, que fostes Mãe do Salvador, sem que a vossa pureza sofresse a mais leve ofensa.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ó Virgem Mãe de Deus, Aquele que nem todo o universo é capaz de conter, esteve encerrado, quando se fez homem, no vosso seio. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Depois de haverdes dado à luz, permanecestes Virgem Imaculada: Intercedei por nós, ó Mãe de Deus. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, falando Jesus às turbas, eis que uma mulher, elevando a voz no meio da multidão, Lhe disse: «Bem-aventurado o seio que Vos trouxe; bem-aventurados os peitos que Vos amamentaram!». E Jesus respondeu, dizendo: «Bem-aventurados, antes, aqueles que ouvem a palavra de Deus e a cumprem».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 1:28 1:42\u003c/I>\u003c/FONT>\u003cbr/>\nAve, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 1:28; 1:42\u003c/I>\u003c/FONT>\u003cbr/>\nAve, Maria, cheia de graça: o Senhor é convosco: bendita sois vós entre as mulheres, e bendito é o fruto do vosso ventre.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nTua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPela vossa misericórdia, Senhor, e pela intercessão da B. Maria, sempre Virgem, fazei que esta oblação nos assegure a prosperidade e a paz, agora e sempre.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Beata Maria Virgine\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in veneratione beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da B. Virgem Maria\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, e de sempre Vos louvar, bendizer e anunciar da Bem-aventurada Maria, sempre Virgem. Foi ela quem concebeu o vosso Filho Unigénito por obra do Espírito Santo, e, sem a mais leve perda de glória da virgindade, deu ao mundo a Luz eterna, Jesus Cristo, Nosso Senhor, por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos céus e os bem-aventurados Serafins a festejam em transportes de alegria. E, Vos imploramos, permiti que unamos as nossas vozes às de todos estes, dizendo em suplicante confissão:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBeáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBem-aventuradas as entranhas da Virgem Maria, que trouxeram encerrado o Filho do Pai Eterno.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo nós, Senhor, alcançado o poderoso auxílio da nossa salvação, concedei-nos, Vos imploramos, que sejamos protegidos com o patrocínio da B. Maria, sempre Virgem, em cuja honra oferecemos à vossa majestade este sacrifício.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]}}};
